 && inTokenScope) {\n            acc.push(key);\n        }\n        return acc;\n    }, []);\n\n    const createCalendars = async (calendarsToBeCreated: CalendarImportMapping[], hasNoCalendar: boolean) => {\n        if (!activeAddresses.length) {\n            throw new Error(c('Error').t`No valid address found`);\n        }\n\n        setCalendarsToBeCreatedCount(calendarsToBeCreated.length);\n\n        const [{ ID: addressID }] = activeAddresses;\n        const { privateKey: primaryAddressKey } = getPrimaryKey(await getAddressKeys(addressID)) || {};\n\n        if (!primaryAddressKey) {\n            throw new Error(c('Error').t`Primary address key is not decrypted.`);\n        }\n\n        const newMapping = await Promise.all(\n            calendarsToBeCreated.map(async ({ Source, Destination, Description }) => {\n                const Name = Destination.replace(CALENDAR_TO_BE_CREATED_PREFIX, '').slice(\n                    0,\n                    MAX_LENGTHS_API.CALENDAR_NAME\n                );\n\n                const { Calendar } = await api(\n                    createCalendar({\n                        Name,\n                        Color: ACCENT_COLORS[randomIntFromInterval(0, ACCENT_COLORS.length - 1)],\n                        Description,\n                        Display: 1,\n                        AddressID: addressID,\n                        IsImport: 1,\n                    })\n                );\n\n                await setupCalendarKey({\n                    api,\n                    calendarID: Calendar.ID,\n                    addressID,\n                    getAddressKeys,\n                });\n\n                setCreatedCalendarsCount(createdCalendarsCount + 1);\n\n                return { Source, Destination: Calendar.ID, Description };\n            })\n        );\n\n        if (hasNoCalendar) {\n            await api(\n                updateCalendarUserSettings({\n                    PrimaryTimezone: getTimezone(),\n                    AutoDetectPrimaryTimezone: 1,\n                })\n            );\n        }\n\n        return newMapping;\n    };\n\n    const handleSubmit = async () => {\n        if (modalModel.step === AUTHENTICATION && provider === OAUTH_PROVIDER.GOOGLE) {\n            setModalModel({\n                ...modalModel,\n                step: OAUTH_INSTRUCTIONS,\n            });\n        }\n\n        if (\n            (modalModel.step === OAUTH_INSTRUCTIONS && provider === OAUTH_PROVIDER.GOOGLE) ||\n            (modalModel.step === AUTHENTICATION && provider !== OAUTH_PROVIDER.GOOGLE)\n        ) {\n            setImportError([]);\n\n            const useNewGmailScope = useNewScopeFeature.feature?.Value === true;\n            const scopes = getScopeFromProvider(provider, checkedTypes, useNewGmailScope);\n\n            triggerOAuthPopup({\n                provider,\n                scope: scopes.join(' '),\n                callback: async (oauthProps: OAuthProps) => {\n                    setIsLoadingOAuth(true);\n                    const checkedProducts = getCheckedProducts(checkedTypes);\n\n                    try {\n                        const { Code, Provider, RedirectUri } = oauthProps;\n\n                        const { Token }: { Token: ImportToken } = await api(\n                            createToken({\n                                Provider,\n                                Code,\n                                RedirectUri,\n                                Source: source,\n                                Products: checkedProducts,\n                            })\n                        );\n\n                        const { Products, ID, Account } = Token;\n\n                        const tokenScope = Products;\n\n                        const createImportPayload: CreateImportPayload = { TokenID: ID, Source: source };\n\n                        if (Products.includes(ImportType.MAIL)) {\n                            createImportPayload[ImportType.MAIL] = {\n                                Account,\n                                Sasl: AuthenticationMethod.OAUTH,\n                            };\n                        }\n\n                        // Calendar and contacts need empty payload\n                        if (Products.includes(ImportType.CALENDAR)) {\n                            createImportPayload[ImportType.CALENDAR] = {};\n                        }\n\n                        if (Products.includes(ImportType.CONTACTS)) {\n                            createImportPayload[ImportType.CONTACTS] = {};\n                        }\n\n                        const { ImporterID } = await api(createImport(createImportPayload));\n\n                        const importErrorsClone = [...importError];\n                        const importsRawData = await Promise.all(\n                            checkedProducts.map(async (importType) => {\n                                if (importType === MAIL) {\n                                    try {\n                                        const { Folders } = await silentApi<{\n                                            Code: number;\n                                            Folders: ImportedMailFolder[];\n                                        }>(getMailImportData(ImporterID));\n                                        return {\n                                            importType,\n                                            Folders,\n                                        };\n                                    } catch (e) {\n                                        const { code, status } = getApiError(e);\n                                        if (status === 422 && code === IMPORT_ERROR.ACCOUNT_DOES_NOT_EXIST) {\n                                            importErrorsClone.push([MAIL, IMPORT_ERROR.ACCOUNT_DOES_NOT_EXIST]);\n                                            return {\n                                                importType,\n                                                Folders: [],\n                                                error: c('Error')\n                                                    .t`No emails found to import - the account does not have an inbox`,\n                                            };\n                                        } else {\n                                            throw e;\n                                        }\n                                    }\n                                }\n\n                                if (importType === CALENDAR) {\n                                    try {\n                                        const { Calendars } = await silentApi<{\n                                            Code: number;\n                                            Calendars: ImportedCalendar[];\n                                        }>(getCalendarImportData(ImporterID));\n                                        return {\n                                            importType,\n                                            Calendars,\n                                        };\n                                    } catch (e) {\n                                        const { code, status } = getApiError(e);\n                                        if (status === 422 && code === IMPORT_ERROR.ACCOUNT_DOES_NOT_EXIST) {\n                                            importErrorsClone.push([CALENDAR, IMPORT_ERROR.ACCOUNT_DOES_NOT_EXIST]);\n                                            return {\n                                                importType,\n                                                Folders: [],\n                                                error: c('Error').t`No calendars found to import`,\n                                            };\n                                        } else {\n                                            throw e;\n                                        }\n                                    }\n                                }\n\n                                if (importType === CONTACTS) {\n                                    try {\n                                        const { Contacts } = await silentApi<{ Contacts: any }>(\n                                            getContactsImportData(ImporterID)\n                                        );\n                                        return {\n                                            importType,\n                                            Contacts,\n                                        };\n                                    } catch (e) {\n                                        const { code, status } = getApiError(e);\n                                        if (status === 422 && code === IMPORT_ERROR.ACCOUNT_DOES_NOT_EXIST) {\n                                            importErrorsClone.push([CALENDAR, IMPORT_ERROR.ACCOUNT_DOES_NOT_EXIST]);\n                                            return {\n                                                importType,\n                                                Folders: [],\n                                                error: c('Error').t`No contacts found to import`,\n                                            };\n                                        } else {\n                                            throw e;\n                                        }\n                                    }\n                                }\n                            })\n                        );\n\n                        if (importErrorsClone.length) {\n                            setImportError(importErrorsClone);\n                        }\n\n                        const data = importsRawData.filter(isTruthy).reduce<IAOauthModalModelImportData>(\n                            (acc, currentImport) => {\n                                const { importType } = currentImport;\n\n                                if (importType === MAIL && currentImport.Folders) {\n                                    acc[importType].providerFolders = currentImport.Folders;\n                                }\n\n                                if (importType === CALENDAR && currentImport.Calendars) {\n                                    acc[importType].providerCalendars = currentImport.Calendars;\n                                }\n\n                                if (importType === CONTACTS) {\n                                    acc[importType].numContacts = currentImport.Contacts.NumContacts || 0;\n                                    acc[importType].numContactGroups = currentImport.Contacts.NumGroups || 0;\n                                }\n\n                                if (currentImport.error) {\n                                    acc[importType].error = currentImport.error;\n                                }\n\n                                return {\n                                    ...acc,\n                                    [importType]: {\n                                        ...acc[importType],\n                                    },\n                                };\n                            },\n                            {\n                                ...modalModel.data,\n                                importerID: ImporterID,\n                            }\n                        );\n\n                        setModalModel({\n                            ...modalModel,\n                            step: SELECT_IMPORT_TYPE,\n                            importedEmail: Account,\n                            oauthProps,\n                            tokenScope,\n                            data,\n                        });\n                        setIsLoadingOAuth(false);\n                    } catch (error) {\n                        setIsLoadingOAuth(false);\n                        errorHandler(error);\n                    }\n                },\n            });\n\n            return;\n        }\n\n        if (modalModel.step === SELECT_IMPORT_TYPE) {\n            const payloads = modalModel.payload;\n\n            const calendarPayload = payloads[ImportType.CALENDAR] as CalendarImporterPayload;\n\n            let createdCalendarMapping;\n\n            const calendarsToBeCreated =\n                modalModel.payload[ImportType.CALENDAR]?.Mapping.filter((m) =>\n                    m.Destination.startsWith(CALENDAR_TO_BE_CREATED_PREFIX)\n                ) || [];\n\n            if (\n                selectedImportTypes.includes(ImportType.CALENDAR) &&\n                payloads[ImportType.CALENDAR] &&\n                calendarsToBeCreated.length\n            ) {\n                setIsLoadingCreateCalendars(true);\n                try {\n                    createdCalendarMapping = await createCalendars(calendarsToBeCreated, !calendars.length);\n                    await call();\n                    calendarPayload.Mapping = [\n                        ...calendarPayload.Mapping.filter(\n                            (m) => !m.Destination.startsWith(CALENDAR_TO_BE_CREATED_PREFIX)\n                        ),\n                        ...createdCalendarMapping,\n                    ];\n                    setIsLoadingCreateCalendars(false);\n                } catch (error) {\n                    setIsLoadingCreateCalendars(false);\n                    errorHandler(error);\n                }\n            }\n\n            const payloadKeys = Object.keys(payloads) as ImportType[];\n            const apiPayload = payloadKeys\n                .filter((key) => Object.values(ImportType).includes(key))\n                .filter((importType) => selectedImportTypes.includes(importType))\n                .reduce<LaunchImportPayload>(\n                    (acc, importType) => {\n                        // Format mail payload\n                        if (importType === ImportType.MAIL) {\n                            const payload = payloads[ImportType.MAIL] as MailImporterPayload;\n\n                            return {\n                                ...acc,\n                                [importType]: {\n                                    ...payload,\n                                    StartTime: payload.StartTime\n                                        ? dateToTimestamp(payload.StartTime as Date)\n                                        : undefined,\n                                    Mapping: payload.Mapping.filter(({ checked }: MailImportMapping) => checked).map(\n                                        ({ Source, Destinations }: MailImportMapping) => ({\n                                            Source,\n                                            Destinations,\n                                        })\n                                    ),\n                                },\n                            };\n                        }\n\n                        return {\n                            ...acc,\n                            [importType]: importType === ImportType.CALENDAR ? calendarPayload : payloads[importType],\n                        };\n                    },\n                    {\n                        ImporterID: modalModel.payload.ImporterID,\n                    }\n                );\n\n            if (importError.length) {\n                importError.forEach(([type, error]) => {\n                    if (error === IMPORT_ERROR.ACCOUNT_DOES_NOT_EXIST) {\n                        delete apiPayload[type];\n                    }\n                });\n            }\n\n            setImportError([]);\n            setIsLoadingStartImportTask(true);\n\n            try {\n                await api(startImportTask(apiPayload));\n                await call();\n\n                setModalModel({\n                    ...modalModel,\n                    step: SUCCESS,\n                });\n\n                setIsLoadingStartImportTask(false);\n            } catch (error) {\n                /* Delete newly created calendars */\n                if (createdCalendarMapping) {\n                    await Promise.all(\n                        createdCalendarMapping.map(async ({ Destination }) => api(removeCalendar(Destination)))\n                    );\n                    await call();\n                }\n\n                setModalModel({\n                    ...modalModel,\n                    isImportError: true,\n                });\n\n                setIsLoadingStartImportTask(false);\n                errorHandler(error);\n            }\n        }\n\n        return null;\n    };\n\n    const submitRenderer = () => {\n        if (showLoadingState) {\n            return null;\n        }\n\n        if (modalModel.step === OAUTH_INSTRUCTIONS) {\n            return <PrimaryButton type=\"submit\">{c('Action').t`Continue`}</PrimaryButton>;\n        }\n\n        if ([SELECT_IMPORT_TYPE, AUTHENTICATION].includes(modalModel.step)) {\n            if (modalModel.oauthProps) {\n                const checkedProducts = getCheckedProducts(checkedTypes);\n                return (\n                    <PrimaryButton\n                        type=\"submit\"\n                        disabled={\n                            !selectedImportTypes.length ||\n                            modalModel.isPayloadInvalid ||\n                            !hasDataToImport(modalModel.data, checkedProducts)\n                        }\n                    >\n                        {c('Action').t`Start import`}\n                    </PrimaryButton>\n                );\n            }\n\n            return (\n                <PrimaryButton type=\"submit\" disabled={!selectedImportTypes.length}>\n                    {c('Action').t`Next`}\n                </PrimaryButton>\n            );\n        }\n\n        if (modalModel.step === SUCCESS && !isCurrentLocationImportPage) {\n            return (\n                <PrimaryButton\n                    onClick={() => {\n                        onClose();\n                        settingsLink(`/easy-switch`);\n                    }}\n                >\n                    {c('Action').t`Check import progress`}\n                </PrimaryButton>\n            );\n        }\n\n        return null;\n    };\n\n    const handleCancel = () => {\n        if (modalModel.step === OAUTH_INSTRUCTIONS) {\n            setModalModel({\n                ...modalModel,\n                step: AUTHENTICATION,\n            });\n\n            return;\n        }\n\n        onClose();\n    };\n\n    const cancelRenderer = () => {\n        let copy = '';\n\n        switch (modalModel.step) {\n            case SUCCESS:\n                copy = c('Action').t`Close`;\n                break;\n            case OAUTH_INSTRUCTIONS:\n                copy = c('Action').t`Back`;\n                break;\n\n            default:\n                copy = c('Action').t`Cancel`;\n                break;\n        }\n\n        return !showLoadingState ? (\n            <Button shape=\"outline\" onClick={handleCancel}>\n                {copy}\n            </Button>\n        ) : null;\n    };\n\n    const titleRenderer = () => {\n        if (showLoadingState) {\n            return null;\n        }\n\n        switch (modalModel.step) {\n            case AUTHENTICATION:\n                return c('Title').t`What would you like to import?`;\n            case SELECT_IMPORT_TYPE:\n                return c('Title').t`Customize and confirm`;\n            case OAUTH_INSTRUCTIONS:\n                return c('Title').t`Sign in and grant access`;\n            case SUCCESS:\n                return null;\n            default:\n                return PRODUCT_NAMES.EASY_SWITCH;\n        }\n    };\n\n    return (\n        <FormModal\n            title={titleRenderer()}\n            submit={submitRenderer()}\n            close={cancelRenderer()}\n            onSubmit={handleSubmit}\n            onClose={handleCancel}\n            intermediate={modalModel.step === OAUTH_INSTRUCTIONS}\n            {...rest}\n        >\n            {showLoadingState ? (\n                <IALoadingStep\n                    isLoadingOAuth={isLoadingOAuth}\n                    isLoadingCreateCalendars={isLoadingCreateCalendars}\n                    isLoadingStartImportTask={isLoadingStartImportTask}\n                    calendarsToBeCreated={calendarsToBeCreatedCount}\n                    createdCalendars={createdCalendarsCount}\n                />\n            ) : (\n                <>\n                    {modalModel.step === OAUTH_INSTRUCTIONS && <IAOauthInstructionsStep modalModel={modalModel} />}\n                    {[SELECT_IMPORT_TYPE, AUTHENTICATION].includes(modalModel.step) && (\n                        <IASelectImportTypeStep\n                            checkedTypes={checkedTypes}\n                            updateCheckedTypes={(importTypes) => setCheckedTypes(importTypes)}\n                            modalModel={modalModel}\n                            toEmail={addressMap[modalModel.AddressID].Email}\n                            calendars={getPersonalCalendars(visualCalendars)}\n                            addresses={addresses}\n                            labels={labels}\n                            folders={folders}\n                            provider={provider}\n                            updateModalModel={(newModel) => setModalModel(newModel)}\n                            featureMap={featureMap}\n                        />\n                    )}\n                    {modalModel.step === SUCCESS && (\n                        <ImportStartedStep\n                            importedEmailAddress={modalModel.importedEmail}\n                            toEmail={addressMap[modalModel.AddressID].Email}\n                            onClose={onClose}\n                        />\n                    )}\n                </>\n            )}\n        </FormModal>\n    );\n};\n\nexport default EasySwitchOauthModal;\n","import { c } from 'ttag';\n\nimport { EASY_SWITCH_SOURCE, EasySwitchFeatureFlag, ImportType } from '@proton/shared/lib/interfaces/EasySwitch';\n\nimport { GoogleButton, Loader, PrimaryButton } from '../../../components';\nimport { useAddresses, useFeature, useModals, useUser } from '../../../hooks';\nimport { EasySwitchOauthModal } from '../../easySwitch';\nimport { FeatureCode } from '../../features';\n\ninterface Props {\n    onImport: () => void;\n    easySwitchSource?: EASY_SWITCH_SOURCE;\n}\n\nconst ImportCsvContactButton = ({ easySwitchSource = EASY_SWITCH_SOURCE.IMPORT_CONTACTS_BUTTON, onImport }: Props) => {\n    const { createModal } = useModals();\n    const [user, loadingUser] = useUser();\n    const [addresses, loadingAddresses] = useAddresses();\n\n    const easySwitchFeature = useFeature<EasySwitchFeatureFlag>(FeatureCode.EasySwitch);\n    const easySwitchFeatureLoading = easySwitchFeature.loading;\n    const easySwitchFeatureValue = easySwitchFeature.feature?.Value;\n\n    const isLoading = loadingUser || loadingAddresses || easySwitchFeatureLoading;\n\n    if (isLoading) {\n        return <Loader />;\n    }\n\n    const disabled = isLoading || !user.hasNonDelinquentScope;\n\n    return (\n        <>\n            {!easySwitchFeatureLoading && easySwitchFeatureValue?.GoogleContacts && (\n                <GoogleButton\n                    onClick={() => {\n                        createModal(\n                            <EasySwitchOauthModal\n                                source={easySwitchSource}\n                                addresses={addresses}\n                                defaultCheckedTypes={[ImportType.CONTACTS]}\n                                featureMap={easySwitchFeatureValue}\n                            />\n                        );\n                    }}\n                    disabled={disabled}\n                    className=\"mr1 mb0-5\"\n                />\n            )}\n            <PrimaryButton className=\"mb0-5\" id=\"import-contacts-button\" disabled={disabled} onClick={onImport}>\n                {c('Action').t`Import from .csv or vCard`}\n            </PrimaryButton>\n        </>\n    );\n};\n\nexport default ImportCsvContactButton;\n","import { c } from 'ttag';\n\nimport { Label } from '@proton/components';\nimport { EASY_SWITCH_SOURCE } from '@proton/shared/lib/interfaces/EasySwitch';\n\nimport ImportCsvContactButton from './ImportCsvContactButton';\n\ninterface Props {\n    onImport: () => void;\n}\n\nconst ContactsWidgetSettingsContainerImport = ({ onImport }: Props) => (\n    <>\n        <Label htmlFor=\"import-contacts-button\" className=\"text-semibold\">\n            <span role=\"heading\" aria-level={2}>{c('Label').t`Import contacts`}</span>\n        </Label>\n\n        <p className=\"color-weak mt0-5 mb1\">\n            {c('Info')\n                .t`CSV files from Outlook, Outlook Express, Yahoo! Mail, Hotmail, Eudora and some other apps as well as vCard 3.1 and 4.0 formats (UTF-8 encoding) are supported.`}\n        </p>\n\n        <ImportCsvContactButton easySwitchSource={EASY_SWITCH_SOURCE.CONTACTS_WIDGET_SETTINGS} onImport={onImport} />\n    </>\n);\n\nexport default ContactsWidgetSettingsContainerImport;\n","import { c } from 'ttag';\n\nimport { CircleLoader } from '@proton/atoms';\nimport { Field, Info, Label } from '@proton/components';\nimport { useContacts, useMailSettings } from '@proton/components/hooks';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport AutoSaveContactsToggle from '../../general/AutoSaveContactsToggle';\nimport ContactsWidgetSettingsContainerExport from './ContactsWidgetSettingsContainerExport';\nimport ContactsWidgetSettingsContainerImport from './ContactsWidgetSettingsContainerImport';\n\ninterface Props {\n    onImport: () => void;\n    onExport: () => void;\n    onClose: () => void;\n}\n\nconst ContactsWidgetSettingsContainer = ({ onImport, onExport, onClose }: Props) => {\n    const [mailSettings, loadingMailSettings] = useMailSettings();\n    const { AutoSaveContacts } = mailSettings || {};\n    const [, loadingContacts] = useContacts();\n\n    const loading = loadingContacts || loadingMailSettings;\n\n    const handleImport = () => {\n        onImport();\n        onClose();\n    };\n\n    const handleExport = () => {\n        onExport();\n        onClose();\n    };\n\n    return (\n        <>\n            {loading ? (\n                <div className=\"flex h100 pb2\">\n                    <CircleLoader className=\"mauto color-primary\" size=\"large\" />\n                </div>\n            ) : (\n                <div className=\"pl2 pr2 pt1 pb1 scroll-if-needed h100\">\n                    <div className=\"flex mb1 on-mobile-flex-column\">\n                        <Label htmlFor=\"saveContactToggle\">\n                            <span className=\"mr0-5 text-semibold\" role=\"heading\" aria-level={2}>{c('Label')\n                                .t`Automatically save contacts`}</span>\n                            <Info url={getKnowledgeBaseUrl('/autosave-contact-list')} />\n                        </Label>\n                        <Field className=\"pt0-5\">\n                            <AutoSaveContactsToggle autoSaveContacts={!!AutoSaveContacts} id=\"saveContactToggle\" />\n                        </Field>\n                    </div>\n                    <div className=\"mb2\">\n                        <ContactsWidgetSettingsContainerImport onImport={handleImport} />\n                    </div>\n                    <div className=\"mb2\">\n                        <ContactsWidgetSettingsContainerExport onExport={handleExport} />\n                    </div>\n                </div>\n            )}\n        </>\n    );\n};\n\nexport default ContactsWidgetSettingsContainer;\n","import { ReactNode } from 'react';\n\nimport { ContactEmail } from '@proton/shared/lib/interfaces/contacts/index';\nimport { Recipient, SimpleMap } from '@proton/shared/lib/interfaces/index';\n\nimport useContactList from '../hooks/useContactList';\n\nexport enum CONTACT_WIDGET_TABS {\n    CONTACTS,\n    GROUPS,\n}\n\nexport interface CustomActionRenderProps {\n    onClose: () => void;\n    noSelection: boolean;\n    selected: string[];\n    contactList?: ReturnType<typeof useContactList>;\n    groupsEmailsMap?: SimpleMap<ContactEmail[]>;\n    recipients?: Recipient[];\n}\n\nexport interface CustomAction {\n    render: ({\n        onClose,\n        noSelection,\n        selected,\n        contactList,\n        groupsEmailsMap,\n        recipients,\n    }: CustomActionRenderProps) => ReactNode;\n    tabs: CONTACT_WIDGET_TABS[];\n}\n","import { forwardRef, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Dropdown, DropdownButton, Icon, Tabs, usePopperAnchor } from '@proton/components';\nimport TopNavbarListItemButton, {\n    TopNavbarListItemButtonProps,\n} from '@proton/components/components/topnavbar/TopNavbarListItemButton';\nimport { generateUID } from '@proton/components/helpers';\nimport { Recipient } from '@proton/shared/lib/interfaces';\nimport noop from '@proton/utils/noop';\n\nimport { useModalTwo } from '../../../components/modalTwo/useModalTwo';\nimport { useContactMergeModals } from '../hooks/useContactMergeModals';\nimport { useContactModals } from '../hooks/useContactModals';\nimport ContactImportModal from '../import/ContactImportModal';\nimport ContactsWidgetContainer from './ContactsWidgetContainer';\nimport ContactsWidgetGroupsContainer from './ContactsWidgetGroupsContainer';\nimport ContactsWidgetSettingsContainer from './ContactsWidgetSettingsContainer';\nimport { CONTACT_WIDGET_TABS, CustomAction } from './types';\n\nimport './ContactsWidget.scss';\n\nconst TopNavbarListItemContactsButton = forwardRef(\n    (props: Omit<TopNavbarListItemButtonProps<'button'>, 'icon' | 'text' | 'as'>, ref: typeof props.ref) => {\n        return (\n            <TopNavbarListItemButton\n                {...props}\n                ref={ref}\n                as=\"button\"\n                type=\"button\"\n                icon={<Icon name=\"users\" />}\n                text={c('Header').t`Contacts`}\n            />\n        );\n    }\n);\nTopNavbarListItemContactsButton.displayName = 'TopNavbarListItemContactsButton';\n\ninterface Props {\n    className?: string;\n    onCompose?: (recipients: Recipient[], attachments: File[]) => void;\n    onMailTo?: (src: string) => void;\n    customActions?: CustomAction[];\n}\n\nconst TopNavbarListItemContactsDropdown = ({ className, onCompose, onMailTo = noop, customActions = [] }: Props) => {\n    const [uid] = useState(generateUID('dropdown'));\n    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();\n    const [tabIndex, setTabIndex] = useState(0);\n    const [lock, setLock] = useState(false);\n\n    const {\n        modals,\n        onDetails,\n        onEdit,\n        onDelete,\n        onExport,\n        onGroupDetails,\n        onGroupEdit,\n        onGroupDelete,\n        onUpgrade,\n        onSelectEmails,\n    } = useContactModals({ onMailTo });\n    const [importModal, onImport] = useModalTwo<void, void>(ContactImportModal, false);\n    const { modals: mergeModals, onMerge } = useContactMergeModals();\n\n    const actionIncludes = (tab: CONTACT_WIDGET_TABS) => (customAction: CustomAction) =>\n        customAction.tabs.includes(tab);\n\n    const handleClose = () => {\n        setTabIndex(0);\n        close();\n    };\n\n    const handleDetails = (contactID: string) => {\n        void onDetails(contactID);\n        handleClose();\n    };\n\n    const handleClickDropdownButton = () => {\n        if (isOpen) {\n            handleClose();\n        } else {\n            toggle();\n        }\n    };\n\n    return (\n        <>\n            <DropdownButton\n                as={TopNavbarListItemContactsButton}\n                isOpen={isOpen}\n                className={className}\n                ref={anchorRef}\n                onClick={handleClickDropdownButton}\n                title={c('Title').t`View contacts`}\n            >\n                <></>\n            </DropdownButton>\n            <Dropdown\n                id={uid}\n                isOpen={isOpen}\n                anchorRef={anchorRef}\n                onClose={handleClose}\n                autoClose={false}\n                autoCloseOutside={!lock}\n                originalPlacement=\"bottom\"\n                className=\"contacts-widget\"\n                contentProps={{\n                    className: 'flex-no-min-children flex-column flex-nowrap',\n                }}\n                noMaxSize\n                noMaxWidth\n                noMaxHeight\n                disableDefaultArrowNavigation\n            >\n                {/* Translator: this text is \"visually\"-hidden, it's for helping blind people */}\n                <h1 className=\"sr-only\">{c('Header').t`Contacts, groups and settings`}</h1>\n                <Tabs\n                    className=\"flex flex-column flex-item-fluid flex-nowrap\"\n                    containerClassName=\"contacts-widget-tabs flex-item-noshrink\"\n                    contentClassName=\"flex-item-fluid\"\n                    tabs={[\n                        {\n                            title: c('Title').t`Contacts`,\n                            content: (\n                                <ContactsWidgetContainer\n                                    onClose={handleClose}\n                                    onCompose={onCompose}\n                                    onLock={setLock}\n                                    customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.CONTACTS))}\n                                    onDetails={handleDetails}\n                                    onEdit={onEdit}\n                                    onDelete={onDelete}\n                                    onImport={onImport}\n                                    onMerge={onMerge}\n                                    onGroupDetails={onGroupDetails}\n                                    onGroupEdit={onGroupEdit}\n                                    onUpgrade={onUpgrade}\n                                    onSelectEmails={onSelectEmails}\n                                />\n                            ),\n                        },\n                        {\n                            title: c('Title').t`Groups`,\n                            content: (\n                                <ContactsWidgetGroupsContainer\n                                    onClose={handleClose}\n                                    onCompose={onCompose}\n                                    onImport={onImport}\n                                    customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.GROUPS))}\n                                    onDetails={onGroupDetails}\n                                    onEdit={onGroupEdit}\n                                    onDelete={onGroupDelete}\n                                    onUpgrade={onUpgrade}\n                                />\n                            ),\n                        },\n                        {\n                            title: c('Title').t`Settings`,\n                            content: (\n                                <ContactsWidgetSettingsContainer\n                                    onImport={onImport}\n                                    onExport={onExport}\n                                    onClose={handleClose}\n                                />\n                            ),\n                        },\n                    ]}\n                    value={tabIndex}\n                    onChange={setTabIndex}\n                />\n            </Dropdown>\n            {modals}\n            {importModal}\n            {mergeModals}\n        </>\n    );\n};\n\nexport default TopNavbarListItemContactsDropdown;\n","import { ContactEmail } from '@proton/shared/lib/interfaces/contacts';\nimport noop from '@proton/utils/noop';\n\nimport { useModalTwo } from '../../../components/modalTwo/useModalTwo';\nimport ContactEditModal, { ContactEditModalProps, ContactEditProps } from '../edit/ContactEditModal';\nimport ContactEmailSettingsModal, { ContactEmailSettingsProps } from '../email/ContactEmailSettingsModal';\nimport ContactGroupDeleteModal, { ContactGroupDeleteProps } from '../group/ContactGroupDeleteModal';\nimport ContactGroupDetailsModal, { ContactGroupDetailsProps } from '../group/ContactGroupDetailsModal';\nimport ContactGroupEditModal, { ContactGroupEditProps } from '../group/ContactGroupEditModal';\nimport ContactClearDataConfirmModal, {\n    ContactClearDataConfirmModalProps,\n    ContactClearDataConfirmProps,\n} from '../modals/ContactClearDataConfirmModal';\nimport ContactClearDataExecutionModal, {\n    ContactClearDataExecutionProps,\n} from '../modals/ContactClearDataExecutionModal';\nimport ContactDecryptionErrorModal, {\n    ContactDecryptionErrorModalProps,\n    ContactDecryptionErrorProps,\n} from '../modals/ContactDecryptionErrorModal';\nimport ContactDeleteModal, { ContactDeleteProps } from '../modals/ContactDeleteModal';\nimport ContactExportingModal, { ContactExportingProps } from '../modals/ContactExportingModal';\nimport ContactImageModal, { ContactImageProps } from '../modals/ContactImageModal';\nimport ContactResignExecutionModal from '../modals/ContactResignExecutionModal';\nimport ContactSignatureErrorModal, {\n    ContactSignatureErrorModalProps,\n    ContactSignatureErrorProps,\n} from '../modals/ContactSignatureErrorModal';\nimport ContactUpgradeModal from '../modals/ContactUpgradeModal';\nimport SelectEmailsModal, { SelectEmailsProps } from '../modals/SelectEmailsModal';\nimport ContactDetailsModal, { ContactDetailsProps } from '../view/ContactDetailsModal';\n\nexport const useContactModals = ({ onMailTo = noop }: { onMailTo: (email: string) => void }) => {\n    const [contactDetailsModal, handleShowContactDetailsModal] = useModalTwo<ContactDetailsProps, void>(\n        ContactDetailsModal,\n        false\n    );\n\n    const [contactEditModal, handleShowContactEditModal] = useModalTwo<ContactEditProps & ContactEditModalProps, void>(\n        ContactEditModal,\n        false\n    );\n\n    const [contactDeleteModal, handleShowContactDeleteModal] = useModalTwo<ContactDeleteProps, void>(\n        ContactDeleteModal,\n        false\n    );\n\n    const [contactEmailSettingsModal, handleShowContactEmailSettingsModal] = useModalTwo<\n        ContactEmailSettingsProps,\n        void\n    >(ContactEmailSettingsModal, false);\n\n    const [contactExportingModal, handleShowContactExportingModal] = useModalTwo<ContactExportingProps, void>(\n        ContactExportingModal,\n        false\n    );\n\n    const [contactGroupDeleteModal, handleShowContactGroupDeleteModal] = useModalTwo<ContactGroupDeleteProps, void>(\n        ContactGroupDeleteModal,\n        false\n    );\n\n    const [contactGroupEditModal, handleShowContactGroupEditModal] = useModalTwo<ContactGroupEditProps, void>(\n        ContactGroupEditModal,\n        false\n    );\n\n    const [contactGroupDetailsModal, handleShowContactGroupDetailsModal] = useModalTwo<ContactGroupDetailsProps, void>(\n        ContactGroupDetailsModal,\n        false\n    );\n\n    const [contactUpgradeModal, handleShowContactUpgradeModal] = useModalTwo<void, void>(ContactUpgradeModal, false);\n\n    const [contactImageModal, handleShowContactImageModal] = useModalTwo<ContactImageProps, void>(\n        ContactImageModal,\n        false\n    );\n\n    const [contactSignatureErrorModal, handleShowContactSignatureErrorModal] = useModalTwo<\n        ContactSignatureErrorProps & ContactSignatureErrorModalProps,\n        void\n    >(ContactSignatureErrorModal, false);\n\n    const [contactResignExecutionModal, handleShowContactResignExecutionModal] = useModalTwo<void, void>(\n        ContactResignExecutionModal,\n        false\n    );\n\n    const [contactDecryptionErrorModal, handleShowContactDecryptionErrorModal] = useModalTwo<\n        ContactDecryptionErrorProps & ContactDecryptionErrorModalProps,\n        void\n    >(ContactDecryptionErrorModal, false);\n\n    const [contactClearDataConfirmModal, handleShowContactClearDataConfirmModal] = useModalTwo<\n        ContactClearDataConfirmProps & ContactClearDataConfirmModalProps,\n        void\n    >(ContactClearDataConfirmModal, false);\n\n    const [contactClearDataExecutionModal, handleShowContactClearDataExecutionModal] = useModalTwo<\n        ContactClearDataExecutionProps,\n        void\n    >(ContactClearDataExecutionModal, false);\n\n    const [contactSelectEmailsModal, handleShowContactSelectEmailsModal] = useModalTwo<\n        SelectEmailsProps,\n        ContactEmail[]\n    >(SelectEmailsModal);\n\n    const handleUpgrade = () => {\n        void handleShowContactUpgradeModal();\n    };\n\n    const handleSelectImage = (props: ContactImageProps) => {\n        void handleShowContactImageModal(props);\n    };\n\n    const handleResign = () => {\n        void handleShowContactResignExecutionModal();\n    };\n\n    const handleSignatureError = (contactID: string) => {\n        void handleShowContactSignatureErrorModal({ contactID, onResign: handleResign });\n    };\n\n    const handleClearData = (props: ContactClearDataExecutionProps) => {\n        void handleShowContactClearDataExecutionModal(props);\n    };\n\n    const handleClearDataConfirm = (props: ContactClearDataConfirmProps) => {\n        void handleShowContactClearDataConfirmModal({ ...props, onClearData: handleClearData });\n    };\n\n    const handleDecryptionError = (contactID: string) => {\n        void handleShowContactDecryptionErrorModal({ contactID, onClearDataConfirm: handleClearDataConfirm });\n    };\n\n    const handleGroupEdit = (props: ContactGroupEditProps) => {\n        void handleShowContactGroupEditModal(props);\n    };\n\n    const handleEdit = (props: ContactEditProps) => {\n        void handleShowContactEditModal({\n            ...props,\n            onUpgrade: handleUpgrade,\n            onSelectImage: handleSelectImage,\n            onGroupEdit: handleGroupEdit,\n        });\n    };\n\n    const handleDelete = (props: ContactDeleteProps) => {\n        void handleShowContactDeleteModal(props);\n    };\n\n    const handleEmailSettings = (props: ContactEmailSettingsProps) => {\n        void handleShowContactEmailSettingsModal(props);\n    };\n\n    const handleExport = (props: ContactExportingProps = {}) => {\n        void handleShowContactExportingModal(props);\n    };\n\n    const handleGroupDelete = (props: ContactGroupDeleteProps) => {\n        void handleShowContactGroupDeleteModal(props);\n    };\n\n    const handleGroupDetails = (contactGroupID: string) => {\n        void handleShowContactGroupDetailsModal({\n            contactGroupID,\n            onEdit: handleGroupEdit,\n            onDelete: handleGroupDelete,\n            onExport: handleExport,\n            onUpgrade: handleUpgrade,\n        });\n    };\n\n    const handleDetails = (contactID: string) => {\n        void handleShowContactDetailsModal({\n            contactID,\n            onMailTo,\n            onEdit: handleEdit,\n            onDelete: handleDelete,\n            onEmailSettings: handleEmailSettings,\n            onGroupDetails: handleGroupDetails,\n            onGroupEdit: handleGroupEdit,\n            onUpgrade: handleUpgrade,\n            onSignatureError: handleSignatureError,\n            onDecryptionError: handleDecryptionError,\n        });\n    };\n\n    const handleSelectEmails = (props: SelectEmailsProps) => {\n        return handleShowContactSelectEmailsModal(props);\n    };\n\n    const modals = (\n        <>\n            {contactDetailsModal}\n            {contactEditModal}\n            {contactDeleteModal}\n            {contactEmailSettingsModal}\n            {contactExportingModal}\n            {contactGroupDetailsModal}\n            {contactGroupEditModal}\n            {contactGroupDeleteModal}\n            {contactUpgradeModal}\n            {contactImageModal}\n            {contactSignatureErrorModal}\n            {contactResignExecutionModal}\n            {contactDecryptionErrorModal}\n            {contactClearDataConfirmModal}\n            {contactClearDataExecutionModal}\n            {contactSelectEmailsModal}\n        </>\n    );\n\n    return {\n        modals,\n        onEdit: handleEdit,\n        onDetails: handleDetails,\n        onDelete: handleDelete,\n        onEmailSettings: handleEmailSettings,\n        onExport: handleExport,\n        onGroupDetails: handleGroupDetails,\n        onGroupEdit: handleGroupEdit,\n        onGroupDelete: handleGroupDelete,\n        onUpgrade: handleUpgrade,\n        onSignatureError: handleSignatureError,\n        onDecryptionError: handleDecryptionError,\n        onSelectEmails: handleSelectEmails,\n    };\n};\n","import { useModalTwo } from '../../../components/modalTwo/useModalTwo';\nimport ContactMergeDetailsModal, { ContactMergeDetailsModalProps } from '../merge/ContactMergeDetailsModal';\nimport ContactMergeModal, { ContactMergeModalProps, ContactMergeProps } from '../merge/ContactMergeModal';\nimport ContactMergePreviewModal, { ContactMergePreviewModalProps } from '../merge/ContactMergePreviewModal';\n\nexport const useContactMergeModals = () => {\n    const [contactMergeModal, handleShowContactMergeModal] = useModalTwo<ContactMergeModalProps, void>(\n        ContactMergeModal,\n        false\n    );\n\n    const [contactMergePreviewModal, handleShowContactMergePreviewModal] = useModalTwo<\n        ContactMergePreviewModalProps,\n        void\n    >(ContactMergePreviewModal, false);\n\n    const [contactMergeDetailsModal, handleShowContactMergeDetailsModal] = useModalTwo<\n        ContactMergeDetailsModalProps,\n        void\n    >(ContactMergeDetailsModal, false);\n\n    const handleMergeDetails = (contactID: string) => {\n        void handleShowContactMergeDetailsModal({ contactID });\n    };\n\n    const handleMergePreview = (props: ContactMergePreviewModalProps) => {\n        void handleShowContactMergePreviewModal(props);\n    };\n\n    const handleMerge = (props: ContactMergeProps) => {\n        void handleShowContactMergeModal({\n            ...props,\n            onMergeDetails: handleMergeDetails,\n            onMergePreview: handleMergePreview,\n        });\n    };\n\n    const modals = (\n        <>\n            {contactMergeModal}\n            {contactMergePreviewModal}\n            {contactMergeDetailsModal}\n        </>\n    );\n\n    return {\n        modals,\n        onMerge: handleMerge,\n    };\n};\n","import { useEffect, useState } from 'react';\n\n/*\n * Same as setState with the difference being that the value\n * passed in the argument of the hook is not only an initial\n * value but will synchronize with the returned state should\n * it change (pointer identity).\n */\nconst useSynchronizingState = <V>(value: V) => {\n    const [state, setState] = useState<V>(value);\n\n    useEffect(() => {\n        setState(value);\n    }, [value]);\n\n    return [state, setState] as const;\n};\n\nexport default useSynchronizingState;\n","import { ChangeEvent } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport useSynchronizingState from '@proton/hooks/useSynchronizingState';\nimport { CALENDAR_APP_NAME, DRIVE_APP_NAME, MAIL_APP_NAME } from '@proton/shared/lib/constants';\n\nimport {\n    Checkbox,\n    Form,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n} from '../../components';\nimport useEarlyAccess from '../../hooks/useEarlyAccess';\n\nconst EarlyAccessModal = ({ onClose, ...rest }: ModalProps) => {\n    const earlyAccess = useEarlyAccess();\n\n    const [earlyAccessEnabled, setEarlyAccessEnabled] = useSynchronizingState(earlyAccess.value);\n\n    const handleChange = async (e: ChangeEvent<HTMLInputElement>) => {\n        setEarlyAccessEnabled(e.target.checked);\n    };\n\n    const update = async () => {\n        await earlyAccess.update(earlyAccessEnabled);\n        window.location.reload();\n    };\n\n    return (\n        <ModalTwo as={Form} onSubmit={update} onClose={onClose} {...rest}>\n            <ModalTwoHeader title={c('Title').t`Beta Access`} />\n            <ModalTwoContent>\n                <p>\n                    {c('Beta access description')\n                        .t`Beta Access lets you use the beta version of ${MAIL_APP_NAME}, ${CALENDAR_APP_NAME}, and ${DRIVE_APP_NAME} before they are released to the public. This means you can be the first to try new products, get new updates, and use new features.`}\n                </p>\n                <p>{c('Beta access description').t`If you encounter issues, you can always disable Beta Access.`}</p>\n                <div className=\"mb0-5 flex flex-align-items-center\">\n                    <label className=\"flex flex-nowrap\" htmlFor=\"enable-early-access-checkbox\">\n                        <Checkbox\n                            id=\"enable-early-access-checkbox\"\n                            checked={earlyAccessEnabled}\n                            onChange={handleChange}\n                            className=\"mr0-5\"\n                        />\n                        {c('Label').t`Enable Beta Access`}\n                    </label>\n                </div>\n                <p className=\"mb0-5 color-weak\">\n                    {c('Refresh on apply warning').t`Note: the service will reload after you click the Apply button.`}\n                </p>\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                <Button onClick={onClose}>{c('Action').t`Close`}</Button>\n                <Button\n                    type=\"submit\"\n                    color=\"norm\"\n                    loading={earlyAccess.loading}\n                    disabled={earlyAccessEnabled === earlyAccess.value || !earlyAccess.canUpdate}\n                >\n                    {c('Action').t`Apply`}\n                </Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default EarlyAccessModal;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\n\nimport { classnames } from '../../helpers';\n\nimport './ThemeCard.scss';\n\n// just for proper sizing when zooming\n\ninterface Props {\n    label: string;\n    id: string;\n    src: string;\n    selected: boolean;\n    onChange: () => void;\n    disabled?: boolean;\n}\n\nconst ThemeCard = ({ label, id, src, selected, onChange, disabled }: Props) => {\n    return (\n        <Button\n            name=\"themeCard\"\n            shape=\"outline\"\n            color={selected ? 'norm' : 'weak'}\n            id={id}\n            fullWidth\n            className={classnames(['theme-card-button', selected && 'is-active no-pointer-events text-bold'])}\n            aria-pressed={selected}\n            onClick={onChange}\n            disabled={disabled}\n            type=\"button\"\n            aria-label={c('Action').t`Use ${label} theme`}\n            title={c('Action').t`Use ${label} theme`}\n        >\n            <span className=\"flex flex-nowrap flex-column flex-align-items-center\">\n                <img alt=\"\" src={src} className=\"mb0-5 theme-card-image rounded-sm on-rtl-mirror\" />\n                <div className=\"py0-25\">{label}</div>\n            </span>\n        </Button>\n    );\n};\n\nexport default ThemeCard;\n","import { ThemeTypes } from '@proton/shared/lib/themes/themes';\n\nimport { classnames } from '../../helpers';\nimport ThemeCard from './ThemeCard';\n\nexport interface Theme {\n    label: string;\n    identifier: ThemeTypes;\n    src: { medium: string; small: string };\n}\n\ninterface Props {\n    themeIdentifier: ThemeTypes;\n    className?: string;\n    liClassName?: string;\n    onChange: (themeType: ThemeTypes) => void;\n    disabled?: boolean;\n    list: Theme[];\n    size?: 'small' | 'medium';\n}\n\nconst ThemeCards = ({ themeIdentifier, onChange, disabled, className, liClassName, list, size = 'medium' }: Props) => {\n    return (\n        <ul className={classnames(['unstyled m0', className])}>\n            {list.map(({ identifier, label, src }) => {\n                const id = `id_${identifier}`;\n                return (\n                    <li className={liClassName} key={label}>\n                        <ThemeCard\n                            label={label}\n                            id={id}\n                            src={src[size]}\n                            selected={themeIdentifier === identifier}\n                            onChange={() => onChange(identifier)}\n                            disabled={disabled}\n                        />\n                    </li>\n                );\n            })}\n        </ul>\n    );\n};\n\nexport default ThemeCards;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { updateThemeType } from '@proton/shared/lib/api/settings';\nimport { getAppFromHostname } from '@proton/shared/lib/apps/slugHelper';\nimport { postMessageToIframe } from '@proton/shared/lib/sideApp/helpers';\nimport { SIDE_APP_EVENTS } from '@proton/shared/lib/sideApp/models';\nimport { PROTON_THEMES, ThemeTypes } from '@proton/shared/lib/themes/themes';\n\nimport { ThemeCards, useTheme } from '.';\nimport { ModalProps, ModalTwo, ModalTwoContent, ModalTwoFooter, ModalTwoHeader } from '../../components';\nimport { useApi, useSideApp } from '../../hooks';\n\nconst ThemesModal = (props: ModalProps) => {\n    const api = useApi();\n    const [theme, setTheme] = useTheme();\n    const { sideAppUrl } = useSideApp();\n\n    const handleThemeChange = async (newThemeType: ThemeTypes) => {\n        setTheme(newThemeType);\n        await api(updateThemeType(newThemeType));\n\n        // If the side panel is open, we need to make the app inside the iframe to call the event manager\n        // Otherwise, the theme is not updated before the next event manager call\n        if (sideAppUrl) {\n            const sideApp = getAppFromHostname(new URL(sideAppUrl).hostname);\n            if (sideApp) {\n                postMessageToIframe(\n                    { type: SIDE_APP_EVENTS.SIDE_APP_UPDATE_THEME, payload: { theme: newThemeType } },\n                    sideApp\n                );\n            }\n        }\n    };\n\n    return (\n        <ModalTwo size=\"large\" {...props}>\n            <ModalTwoHeader title={c('Title').t`Select a theme`} />\n            <ModalTwoContent>\n                <ThemeCards\n                    className=\"theme-modal-list\"\n                    list={PROTON_THEMES}\n                    size=\"small\"\n                    themeIdentifier={theme}\n                    onChange={handleThemeChange}\n                />\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                <Button color=\"norm\" className=\"mlauto\" onClick={props.onClose}>{c('Action').t`OK`}</Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default ThemesModal;\n","import { ComponentPropsWithoutRef, ReactNode, forwardRef } from 'react';\n\nimport { c } from 'ttag';\n\nimport { PROTON_THEMES_MAP } from '@proton/shared/lib/themes/themes';\n\nimport { AppLink, DropdownMenu, DropdownMenuButton, DropdownMenuLink, Icon } from '../../components';\nimport SimpleDropdown from '../../components/dropdown/SimpleDropdown';\nimport TopNavbarListItemButton, {\n    TopNavbarListItemButtonProps,\n} from '../../components/topnavbar/TopNavbarListItemButton';\nimport { useEarlyAccess, useModals } from '../../hooks';\nimport EarlyAccessModal from '../earlyAccess/EarlyAccessModal';\nimport { useTheme } from '../themes';\nimport ThemesModal from '../themes/ThemesModal';\n\nconst TopNavbarListItemSettingsButtonBase = (\n    props: Omit<TopNavbarListItemButtonProps<'button'>, 'icon' | 'text' | 'as'>,\n    ref: typeof props.ref\n) => {\n    return (\n        <TopNavbarListItemButton\n            {...props}\n            ref={ref}\n            type=\"button\"\n            as=\"button\"\n            data-test-id=\"view:general-settings\"\n            icon={<Icon name=\"cog-wheel\" />}\n            text={c('Text').t`Settings`}\n            title={c('Title').t`Open settings menu`}\n        />\n    );\n};\n\nconst TopNavbarListItemSettingsButton = forwardRef(TopNavbarListItemSettingsButtonBase);\n\ninterface Props extends ComponentPropsWithoutRef<typeof AppLink> {\n    children?: ReactNode;\n}\n\nconst TopNavbarListItemSettingsDropdown = (props: Props) => {\n    const { createModal } = useModals();\n    const earlyAccess = useEarlyAccess();\n    const [theme] = useTheme();\n\n    const handleEarlyAccessClick = () => {\n        createModal(<EarlyAccessModal />);\n    };\n\n    const handleThemeClick = () => {\n        createModal(<ThemesModal />);\n    };\n\n    const { to, toApp, children } = props;\n\n    return (\n        <SimpleDropdown\n            as={TopNavbarListItemSettingsButton}\n            originalPlacement=\"bottom-start\"\n            hasCaret={false}\n            dropdownStyle={{ '--min-width': '18em' }}\n        >\n            <DropdownMenu>\n                <DropdownMenuLink as={AppLink} to={to} toApp={toApp} target=\"_self\">\n                    {c('Action').t`Go to settings`}\n                </DropdownMenuLink>\n\n                <hr className=\"mt0-5 mb0-5\" />\n\n                <DropdownMenuButton\n                    onClick={handleEarlyAccessClick}\n                    className=\"flex flex-nowrap flex-justify-space-between flex-align-items-center\"\n                >\n                    <span className=\"flex-item-fluid text-left\">{c('Action').t`Beta Access`}</span>\n                    <span className=\"color-primary ml0-5\">\n                        {earlyAccess.value ? c('Early Access Enabled').t`On` : c('Early Access Disabled').t`Off`}\n                    </span>\n                </DropdownMenuButton>\n\n                <DropdownMenuButton\n                    onClick={handleThemeClick}\n                    className=\"flex flex-nowrap flex-justify-space-between flex-align-items-center\"\n                >\n                    <span className=\"flex-item-fluid text-left\">{c('Action').t`Theme`}</span>\n                    <span className=\"color-primary ml0-5\">{PROTON_THEMES_MAP[theme].label}</span>\n                </DropdownMenuButton>\n                {children}\n            </DropdownMenu>\n        </SimpleDropdown>\n    );\n};\n\nexport default TopNavbarListItemSettingsDropdown;\n","import { ComponentPropsWithoutRef } from 'react';\n\nimport { ButtonLike, ButtonLikeProps as TButtonLikeProps } from '@proton/atoms';\n\nimport { classnames } from '../../helpers';\n\nexport interface InputButtonProps extends ComponentPropsWithoutRef<'input'> {\n    id?: string;\n    type?: 'checkbox' | 'radio';\n    title?: string;\n    checked?: boolean;\n    labelProps?: ComponentPropsWithoutRef<'label'>;\n    ButtonLikeProps?: TButtonLikeProps<'span'>;\n}\n\nconst InputButton = ({\n    id,\n    title,\n    checked,\n    children,\n    type = 'checkbox',\n    labelProps = {},\n    ButtonLikeProps = {},\n    ...rest\n}: InputButtonProps) => {\n    const { className: labelClassNameProp, ...labelPropsRest } = labelProps;\n\n    const labelClassName = classnames(['inline-flex relative', labelClassNameProp]);\n\n    return (\n        <label htmlFor={id} title={title} className={labelClassName} {...labelPropsRest}>\n            <input id={id} type={type} className=\"input-button-input sr-only\" checked={checked} {...rest} />\n\n            <ButtonLike\n                as=\"span\"\n                {...ButtonLikeProps}\n                className={classnames([\n                    'input-button flex flex-justify-center flex-item-noshrink rounded-50',\n                    ButtonLikeProps.className,\n                ])}\n            >\n                {children}\n            </ButtonLike>\n        </label>\n    );\n};\n\nexport default InputButton;\n","import { ComponentPropsWithRef } from 'react';\n\ninterface ScaleLabelProps extends ComponentPropsWithRef<'div'> {\n    fromLabel: string;\n    toLabel: string;\n}\n\nconst ScaleLabel = ({ fromLabel, toLabel, ...rest }: ScaleLabelProps) => {\n    return (\n        <div className=\"flex flex-justify-space-between flex-align-items-start flex-gap-1\" {...rest}>\n            <span className=\"text-sm m0\">{fromLabel}</span>\n            <span className=\"text-sm m0\">{toLabel}</span>\n        </div>\n    );\n};\n\nexport default ScaleLabel;\n","import { ChangeEvent, ComponentPropsWithoutRef } from 'react';\n\nimport { c } from 'ttag';\n\nimport emojiAwful from '@proton/styles/assets/img/emojis/emoji-awful.svg';\nimport emojiBad from '@proton/styles/assets/img/emojis/emoji-bad.svg';\nimport emojiGood from '@proton/styles/assets/img/emojis/emoji-good.svg';\nimport emojiOk from '@proton/styles/assets/img/emojis/emoji-ok.svg';\nimport emojiWonderful from '@proton/styles/assets/img/emojis/emoji-wonderful.svg';\n\nimport { classnames } from '../../helpers';\nimport { Tooltip } from '../tooltip';\nimport InputButton, { InputButtonProps } from './InputButton';\nimport ScaleLabel from './ScaleLabel';\n\nimport './EmojiScale.scss';\n\nexport interface EmojiScaleProps extends Omit<ComponentPropsWithoutRef<'div'>, 'onChange'> {\n    fromLabel: string;\n    toLabel: string;\n    value?: number;\n    InputButtonProps?: Partial<InputButtonProps>;\n    onChange: (value: number) => void;\n}\n\nconst scale = [\n    { value: 1, emoji: emojiAwful, label: () => c('Label').t`Awful` },\n    { value: 2, emoji: emojiBad, label: () => c('Label').t`Bad` },\n    { value: 3, emoji: emojiOk, label: () => c('Label').t`OK` },\n    { value: 4, emoji: emojiGood, label: () => c('Label').t`Good` },\n    { value: 5, emoji: emojiWonderful, label: () => c('Label').t`Wonderful` },\n];\n\nconst EmojiScale = ({ fromLabel, toLabel, value, InputButtonProps, onChange, className, ...rest }: EmojiScaleProps) => {\n    const handleChange = (e: ChangeEvent<HTMLInputElement>) => {\n        onChange(Number(e.target.value));\n    };\n\n    return (\n        <div className={classnames([className, 'flex flex-column flex-gap-1'])} {...rest}>\n            <div className=\"flex flex-justify-space-between flex-align-items-center\">\n                {scale.map((option) => (\n                    <Tooltip title={option.label()} key={option.value}>\n                        <span>\n                            <InputButton\n                                id={`score-${option.value}`}\n                                name=\"score\"\n                                type=\"radio\"\n                                value={option.value}\n                                checked={value === option.value}\n                                onChange={handleChange}\n                                ButtonLikeProps={{ className: 'emoji-scale_input-button' }}\n                                {...InputButtonProps}\n                            >\n                                <img src={option.emoji} alt={option.label()} aria-hidden=\"true\" />\n                                <span className=\"sr-only\">{option.label()}</span>\n                            </InputButton>\n                        </span>\n                    </Tooltip>\n                ))}\n            </div>\n            <ScaleLabel fromLabel={fromLabel} toLabel={toLabel} />\n        </div>\n    );\n};\n\nexport default EmojiScale;\n","import { ChangeEvent, DetailedHTMLProps, Ref, TextareaHTMLAttributes, useEffect, useRef, useState } from 'react';\n\nimport { classnames, generateUID } from '../../helpers';\nimport useAutoGrow from '../../hooks/useAutoGrow';\nimport ErrorZone from '../text/ErrorZone';\nimport useInput from './useInput';\n\nexport interface Props extends DetailedHTMLProps<TextareaHTMLAttributes<HTMLTextAreaElement>, HTMLTextAreaElement> {\n    ref?: Ref<HTMLTextAreaElement>; // override ref so that LegacyRef isn't used\n    error?: string;\n    isSubmitted?: boolean;\n    loading?: boolean;\n    rows?: number;\n    minRows?: number;\n    autoGrow?: boolean;\n}\n\n/**\n * @deprecated please use TextAreaTwo instead\n */\nconst TextArea = ({\n    className = '',\n    error,\n    rows: maxRows = 5,\n    minRows = 1,\n    autoGrow = false,\n    onChange,\n    isSubmitted,\n    ...rest\n}: Props) => {\n    const textAreaRef = useRef<HTMLTextAreaElement>(null);\n    const { rows, updateTextArea } = useAutoGrow({ maxRows, minRows, autoGrow });\n    const { handlers, statusClasses, status } = useInput<HTMLTextAreaElement>({\n        ...rest,\n        onChange(e: ChangeEvent<HTMLTextAreaElement>) {\n            if (updateTextArea) {\n                updateTextArea(e.target);\n            }\n            if (onChange) {\n                onChange(e);\n            }\n        },\n    });\n\n    useEffect(() => {\n        if (updateTextArea && textAreaRef.current) {\n            updateTextArea(textAreaRef.current);\n        }\n    }, [updateTextArea]);\n\n    const [uid] = useState(generateUID('textarea'));\n\n    const hasError = !!(error && (status.isDirty || isSubmitted));\n\n    return (\n        <>\n            <textarea\n                ref={textAreaRef}\n                rows={rows}\n                className={classnames(['field w100', className, statusClasses])}\n                aria-invalid={hasError}\n                aria-describedby={uid}\n                {...rest}\n                {...handlers}\n            />\n            {hasError && <ErrorZone id={uid}>{error}</ErrorZone>}\n        </>\n    );\n};\n\nexport default TextArea;\n","import { ChangeEvent, FormEvent, useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { sendFeedback } from '@proton/shared/lib/api/feedback';\n\nimport {\n    EmojiScale,\n    EmojiScaleProps,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    TextArea,\n} from '../../components';\nimport { useApi, useLoading, useNotifications } from '../../hooks';\n\ninterface FeedbackModalModel {\n    Score?: number;\n    Feedback: string;\n}\n\ntype FeedbackType = 'v4_migration' | 'calendar_launch' | 'web_clients_relaunch';\n\nexport interface FeedbackModalProps extends ModalProps {\n    onClose?: () => void;\n    onSuccess?: () => void;\n    onMount?: () => void;\n    feedbackType: FeedbackType;\n    description?: string;\n    scaleTitle: string;\n    scaleProps: Omit<EmojiScaleProps, 'value' | 'InputButtonProps' | 'onChange'>;\n}\n\nconst FeedbackModal = ({ feedbackType, description, scaleTitle, scaleProps, onMount, ...rest }: FeedbackModalProps) => {\n    const api = useApi();\n    const { createNotification } = useNotifications();\n    const [loading, withLoading] = useLoading();\n    const [model, setModel] = useState<FeedbackModalModel>({\n        Score: undefined,\n        Feedback: '',\n    });\n\n    useEffect(() => {\n        onMount?.();\n    }, []);\n\n    const handleSubmit = async () => {\n        if (model.Score === undefined) {\n            createNotification({\n                text: c('Error notification when score is missing in user feedback form modal').t`Score is required`,\n                type: 'error',\n            });\n            return;\n        }\n        await api(\n            sendFeedback({\n                Score: model.Score,\n                Feedback: model.Feedback,\n                FeedbackType: feedbackType,\n            })\n        );\n        createNotification({ text: c('Success notification when user send feedback').t`Feedback sent` });\n        rest.onSuccess?.();\n        rest.onClose?.();\n    };\n\n    const handleChange = (field: string) => (e: ChangeEvent<HTMLTextAreaElement>) => {\n        setModel({\n            ...model,\n            [field]: e.target.value,\n        });\n    };\n\n    const handleScoreChange = (Score: number) => {\n        setModel({ ...model, Score });\n    };\n\n    return (\n        <Modal\n            as=\"form\"\n            onSubmit={(e: FormEvent) => {\n                e.preventDefault();\n                withLoading(handleSubmit());\n            }}\n            size=\"large\"\n            {...rest}\n        >\n            <ModalHeader title={c('Feedback Modal Title').t`Your feedback`} />\n            <ModalContent>\n                {description && <p className=\"mb2\">{description}</p>}\n                <div className=\"mb2\">\n                    <label className=\"mb1 block text-semibold\" id=\"score-label\">\n                        {scaleTitle}\n                    </label>\n                    <div>\n                        <EmojiScale\n                            {...scaleProps}\n                            value={model.Score}\n                            InputButtonProps={{ 'aria-describedby': 'score-label' }}\n                            onChange={handleScoreChange}\n                        />\n                    </div>\n                </div>\n\n                {model.Score !== undefined && (\n                    <div>\n                        <label className=\"mb1 block text-semibold\" htmlFor=\"feedback-label\">{c('new_plans: label')\n                            .t`Tell us about your experience. (Optional)`}</label>\n                        <TextArea\n                            id=\"feedback-label\"\n                            value={model.Feedback}\n                            placeholder={c('new_plans: placeholder').t`Feedback`}\n                            onChange={handleChange('Feedback')}\n                        />\n                    </div>\n                )}\n            </ModalContent>\n            <ModalFooter>\n                <Button disabled={loading} onClick={rest.onClose}>{c('Action').t`Cancel`}</Button>\n                <Button type=\"submit\" color=\"norm\" loading={loading}>{c('Action').t`Send feedback`}</Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default FeedbackModal;\n","export const sendFeedback = ({\n    Score,\n    Feedback,\n    FeedbackType,\n}: {\n    Score: number;\n    Feedback: string;\n    FeedbackType: string;\n}) => ({\n    url: `v4/feedback`,\n    method: 'post',\n    data: { Score, Feedback, FeedbackType },\n});\n","import { c } from 'ttag';\n\nimport useFeature from '../../hooks/useFeature';\nimport { FeatureCode } from '../features/FeaturesContext';\nimport FeedbackModal, { FeedbackModalProps } from './FeedbackModal';\nimport { RebrandingFeatureValue } from './useRebrandingFeedback';\n\ninterface RebrandingModalProps extends Partial<FeedbackModalProps> {\n    onMount?: () => void;\n}\n\nconst RebrandingFeedbackModal = (props: RebrandingModalProps) => {\n    const rebranding = useFeature<RebrandingFeatureValue>(FeatureCode.RebrandingFeedback);\n\n    const handleSuccess = () => {\n        if (rebranding.feature?.Value.completed !== true) {\n            /*\n             * The value of the rebranding feature is guaranteed to exist here\n             * because we're disabling the Feedback Modal until it's available.\n             */\n            rebranding.update({\n                ...rebranding.feature!.Value,\n                completed: true,\n            });\n        }\n    };\n\n    if (!rebranding.feature?.Value) {\n        return null;\n    }\n\n    return (\n        <FeedbackModal\n            size=\"medium\"\n            onSuccess={handleSuccess}\n            feedbackType=\"web_clients_relaunch\"\n            scaleTitle={c('Label').t`How would you describe your experience with the new Proton?`}\n            scaleProps={{\n                fromLabel: c('Label').t`Awful`,\n                toLabel: c('Label').t`Wonderful`,\n            }}\n            {...props}\n        />\n    );\n};\n\nexport default RebrandingFeedbackModal;\n","import { OnboardingStepProps } from './interface';\n\nconst OnboardingStep = ({ children }: OnboardingStepProps) => {\n    return <>{children}</>;\n};\n\nexport default OnboardingStep;\n","import { HTMLProps, ReactNode } from 'react';\n\nexport interface Props extends HTMLProps<HTMLDivElement> {\n    description?: ReactNode;\n    children?: ReactNode;\n    img?: ReactNode;\n}\n\nconst OnboardingContent = ({ description, img, children, title, ...rest }: Props) => {\n    return (\n        <div {...rest}>\n            {img && <div className=\"pb1 text-center mauto w100 on-mobile-w100\">{img}</div>}\n            {title && <h1 className=\"mb0-5 text-2xl text-bold text-center\">{title}</h1>}\n            {description && <div className=\"mb2 text-center color-weak\">{description}</div>}\n            {children && <div className=\"mb2\">{children}</div>}\n        </div>\n    );\n};\n\nexport default OnboardingContent;\n","import { Children, HTMLProps, ReactElement, cloneElement } from 'react';\n\nimport { classnames } from '../../helpers';\nimport { Props as StepDotProps } from '../stepDot/StepDot';\n\nexport interface Props extends Omit<HTMLProps<HTMLDivElement>, 'onChange'> {\n    value: number;\n    onChange?: (index: number) => void;\n    ulClassName?: string;\n    children: ReactElement<StepDotProps>[];\n}\n\nconst StepDots = ({ value, onChange, children, className, ulClassName, ...rest }: Props) => {\n    const clonedChildren = Children.map(children, (child, index) =>\n        cloneElement(child, {\n            active: index === value,\n            index,\n            onChange,\n        })\n    );\n\n    return (\n        <nav {...rest} className={classnames([className, 'step-dots-container'])}>\n            <ul className={classnames(['step-dots-list unstyled inline-flex flex-row', ulClassName])} role=\"tablist\">\n                {clonedChildren}\n            </ul>\n        </nav>\n    );\n};\n\nexport default StepDots;\n","import { HTMLProps } from 'react';\n\nimport { c } from 'ttag';\n\nimport { classnames } from '../../helpers';\n\n/*\n * 'type' is string in HTMLButtonElement but the button React elements wants a union between\n * the possible values for types, omitting for now due to incompatibility\n */\nexport interface Props extends Omit<HTMLProps<HTMLButtonElement>, 'onChange' | 'type'> {\n    onChange?: (index: number) => void;\n    index?: number;\n    active?: boolean;\n}\n\nconst StepDot = ({ index, className, onChange, active, role = 'presentation', ...rest }: Props) => {\n    function handleClick() {\n        if (index !== undefined) {\n            onChange?.(index);\n        }\n    }\n\n    return (\n        <li className=\"step-dots-item\" role={role}>\n            <button\n                type=\"button\"\n                role=\"tab\"\n                aria-selected={active}\n                className={classnames([className, 'step-dots-dot', 'rounded-50', !onChange && 'no-pointer-events'])}\n                title={onChange ? c('Action').t`Go to panel ${index}` : undefined}\n                onClick={handleClick}\n                {...rest}\n            >\n                <span className=\"sr-only\">{c('Action').t`Go to panel ${index}`}</span>\n            </button>\n        </li>\n    );\n};\n\nexport default StepDot;\n","import { c } from 'ttag';\n\nimport onboardingDiscover from '@proton/styles/assets/img/onboarding/discover.svg';\n\nimport OnboardingContent, { Props as OnboardingContentProps } from './OnboardingContent';\n\nconst OnboardingDiscoverApps = (props: Omit<OnboardingContentProps, 'decription' | 'img'>) => {\n    return (\n        <OnboardingContent\n            title={c('Onboarding Proton').t`Discover all Proton services`}\n            description={c('Onboarding Proton')\n                .t`Use the app selector in the top left to access other Proton services, including VPN, Calendar and Drive.`}\n            img={<img src={onboardingDiscover} alt={c('Onboarding Proton').t`Discover all Proton services`} />}\n            {...props}\n        />\n    );\n};\n\nexport default OnboardingDiscoverApps;\n","import { c } from 'ttag';\n\nimport onboardingOrganization from '@proton/styles/assets/img/onboarding/organization.svg';\n\nimport OnboardingContent, { Props as OnboardingContentProps } from './OnboardingContent';\n\nconst OnboardingSetupOrganization = (props: Omit<OnboardingContentProps, 'decription' | 'img'>) => {\n    return (\n        <OnboardingContent\n            title={c('Onboarding Proton').t`Set up your organization`}\n            description={c('Onboarding Proton')\n                .t`Configure your organization, link your domain name, and create accounts to ensure all members of your organization are protected.`}\n            img={<img src={onboardingOrganization} alt={c('Onboarding Proton').t`Set up your organization`} />}\n            {...props}\n        />\n    );\n};\n\nexport default OnboardingSetupOrganization;\n","import { c } from 'ttag';\n\nimport { ThemeTypes } from '@proton/shared/lib/themes/themes';\n\nimport ThemeCards, { Theme } from '../themes/ThemeCards';\nimport OnboardingContent, { Props as OnboardingContentProps } from './OnboardingContent';\n\ninterface Props extends Omit<OnboardingContentProps, 'decription' | 'onChange'> {\n    themes: Theme[];\n    themeIdentifier: ThemeTypes;\n    onChange: (identifier: ThemeTypes) => void;\n}\n\nconst OnboardingThemes = ({ themes, themeIdentifier, onChange, ...rest }: Props) => {\n    return (\n        <OnboardingContent\n            title={c('Onboarding Proton').t`Select a theme`}\n            description={c('Onboarding Proton').t`You can change this anytime in your settings.`}\n            {...rest}\n        >\n            <ThemeCards\n                className=\"theme-modal-list\"\n                list={themes}\n                size=\"small\"\n                themeIdentifier={themeIdentifier}\n                onChange={onChange}\n            />\n        </OnboardingContent>\n    );\n};\n\nexport default OnboardingThemes;\n","import { isValidElement, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { updateFlags, updateThemeType, updateWelcomeFlags } from '@proton/shared/lib/api/settings';\nimport { hasNewVisionary, hasVisionary } from '@proton/shared/lib/helpers/subscription';\nimport { PROTON_THEMES, ThemeTypes } from '@proton/shared/lib/themes/themes';\nimport isTruthy from '@proton/utils/isTruthy';\nimport noop from '@proton/utils/noop';\nimport range from '@proton/utils/range';\n\nimport { ModalTwoContent as ModalContent, ModalTwo, StepDot, StepDots, useSettingsLink } from '../../components';\nimport { useApi, useOrganization, useSubscription, useUser, useUserSettings, useWelcomeFlags } from '../../hooks';\nimport { useTheme } from '../themes/ThemeProvider';\nimport OnboardingDiscoverApps from './OnboardingDiscoverApps';\nimport OnboardingSetupOrganization from './OnboardingSetupOrganization';\nimport OnboardingStep from './OnboardingStep';\nimport OnboardingThemes from './OnboardingThemes';\nimport { OnboardingStepProps, OnboardingStepRenderCallback } from './interface';\n\nimport './OnboardingModal.scss';\n\ninterface Props {\n    onClose?: () => void;\n    onExit?: () => void;\n    onDone?: () => void;\n    children?: ((props: OnboardingStepRenderCallback) => JSX.Element)[];\n    showGenericSteps?: boolean;\n}\n\nconst OnboardingModal = ({ children, showGenericSteps, onDone, ...rest }: Props) => {\n    const [user] = useUser();\n    const [userSettings] = useUserSettings();\n    const goToSettings = useSettingsLink();\n    const [organization, loadingOrganization] = useOrganization();\n    const [subscription, loadingSubscription] = useSubscription();\n    const [theme, setTheme] = useTheme();\n    const api = useApi();\n    const [welcomeFlags] = useWelcomeFlags();\n    let isLastStep = false;\n    const canSetupOrganization =\n        !loadingOrganization &&\n        !loadingSubscription &&\n        user.isAdmin &&\n        organization.MaxMembers > 1 &&\n        organization.UsedMembers === 1 &&\n        !organization.HasKeys &&\n        !hasNewVisionary(subscription) &&\n        !hasVisionary(subscription);\n\n    const [step, setStep] = useState(0);\n\n    const handleNext = () => {\n        if (isLastStep) {\n            if (welcomeFlags.isWelcomeFlow) {\n                // Set generic welcome to true\n                api(updateFlags({ Welcomed: 1 })).catch(noop);\n            }\n            if (!userSettings.WelcomeFlag) {\n                // Set product specific welcome to true\n                api(updateWelcomeFlags()).catch(noop);\n            }\n            onDone?.();\n            rest?.onClose?.();\n            return;\n        }\n        setStep((step) => step + 1);\n    };\n\n    const handleBack = () => {\n        setStep((step) => step - 1);\n    };\n\n    const handleThemeChange = async (newThemeType: ThemeTypes) => {\n        setTheme(newThemeType);\n        await api(updateThemeType(newThemeType));\n    };\n\n    const setupOrganizationStep = (\n        <OnboardingStep>\n            <OnboardingSetupOrganization />\n            <footer>\n                <div className=\"flex flex-nowrap mb1\">\n                    <Button size=\"large\" color=\"weak\" className=\"mr1\" fullWidth onClick={handleBack}>{c('Action')\n                        .t`Back`}</Button>\n                    <Button\n                        size=\"large\"\n                        color=\"norm\"\n                        fullWidth\n                        onClick={() => {\n                            goToSettings('/multi-user-support', undefined, true);\n                            handleNext();\n                        }}\n                    >\n                        {c('Action').t`Start setup`}\n                    </Button>\n                </div>\n                <Button size=\"large\" color=\"norm\" shape=\"ghost\" className=\"mb1\" fullWidth onClick={handleNext}>{c(\n                    'Action'\n                ).t`Skip`}</Button>\n            </footer>\n        </OnboardingStep>\n    );\n\n    const themesStep = (\n        <OnboardingStep>\n            <OnboardingThemes themeIdentifier={theme} themes={PROTON_THEMES} onChange={handleThemeChange} />\n            <footer className=\"flex flex-nowrap\">\n                <Button size=\"large\" color=\"weak\" className=\"mr1\" fullWidth onClick={handleBack}>{c('Action')\n                    .t`Back`}</Button>\n                <Button size=\"large\" color=\"norm\" fullWidth onClick={handleNext}>\n                    {c('Action').t`Next`}\n                </Button>\n            </footer>\n        </OnboardingStep>\n    );\n\n    const discoverAppsStep = (\n        <OnboardingStep>\n            <OnboardingDiscoverApps />\n            <footer className=\"flex flex-nowrap\">\n                <Button size=\"large\" className=\"mr1\" fullWidth onClick={handleBack}>{c('Action').t`Back`}</Button>\n                <Button size=\"large\" color=\"norm\" fullWidth onClick={handleNext}>\n                    {c('Action').t`Get started`}\n                </Button>\n            </footer>\n        </OnboardingStep>\n    );\n\n    const displayGenericSteps = welcomeFlags?.hasGenericWelcomeStep || showGenericSteps;\n    const genericSteps = displayGenericSteps\n        ? [canSetupOrganization && setupOrganizationStep, themesStep, discoverAppsStep].filter(isTruthy)\n        : [];\n\n    const productSteps = children\n        ? (Array.isArray(children) ? children : [children])\n              .map(\n                  (renderCallback) =>\n                      renderCallback?.({\n                          onNext: handleNext,\n                          onBack: handleBack,\n                          displayGenericSteps,\n                      }) ?? null\n              )\n              .filter((x) => x !== null)\n        : [];\n\n    const steps = [...productSteps, ...genericSteps];\n    isLastStep = steps.length - 1 === step;\n    const childStep = steps[step];\n    const hasDots = steps.length > 1 && step < steps.length;\n\n    if (!steps.length) {\n        rest?.onClose?.();\n    }\n\n    if (!isValidElement<OnboardingStepProps>(childStep)) {\n        throw new Error('Missing step');\n    }\n\n    return (\n        <ModalTwo {...rest} size=\"small\" className=\"onboarding-modal\">\n            <ModalContent className=\"m2\">\n                {childStep}\n                {hasDots ? (\n                    <div className=\"text-center\">\n                        <StepDots value={step} ulClassName=\"mb0\">\n                            {range(0, steps.length).map((index) => (\n                                <StepDot\n                                    key={index}\n                                    index={index}\n                                    aria-controls={`onboarding-${index}`}\n                                    onClick={() => {\n                                        setStep(index);\n                                    }}\n                                />\n                            ))}\n                        </StepDots>\n                    </div>\n                ) : null}\n            </ModalContent>\n        </ModalTwo>\n    );\n};\n\nexport default OnboardingModal;\n","import { ChecklistId } from '../interfaces';\n\nexport const getChecklist = (checklistId: ChecklistId) => ({\n    method: 'get',\n    url: `core/v4/checklist/${checklistId}`,\n});\n\nexport const seenCompletedChecklist = (checklistId: ChecklistId) => ({\n    method: 'post',\n    url: `core/v4/checklist/${checklistId}/seen-completed-list`,\n});\n\nexport const getDriveChecklist = (checklistId: ChecklistId) => ({\n    method: 'get',\n    url: `drive/v2/checklist/${checklistId}`,\n});\n\nexport const seenCompletedDriveChecklist = (checklistId: ChecklistId) => ({\n    method: 'post',\n    url: `drive/v2/checklist/${checklistId}/seen-completed-list`,\n});\n\nexport const hidePaidUserChecklist = () => ({\n    method: 'post',\n    url: `core/v4/checklist/paying-user/hide`,\n});\n","import { useEffect, useState } from 'react';\n\nimport { differenceInDays, fromUnixTime } from 'date-fns';\n\nimport { useApi, useLoading, useUser } from '@proton/components';\nimport { getDriveChecklist, seenCompletedDriveChecklist } from '@proton/shared/lib/api/checklist';\nimport { ChecklistApiResponse } from '@proton/shared/lib/interfaces';\n\nexport default function useChecklist() {\n    const api = useApi();\n    const [user] = useUser();\n    const [isLoading, withLoading] = useLoading(false);\n    const [checklist, setChecklist] = useState<ChecklistApiResponse>();\n\n    useEffect(() => {\n        if (user.isPaid) {\n            return;\n        }\n        withLoading(api<ChecklistApiResponse>(getDriveChecklist('get-started')).then(setChecklist)).catch(\n            console.error\n        );\n    }, []);\n\n    const reload = () => {\n        api<ChecklistApiResponse>(getDriveChecklist('get-started')).then(setChecklist).catch(console.error);\n    };\n\n    const expiresInDays = checklist?.ExpiresAt ? differenceInDays(fromUnixTime(checklist.ExpiresAt), new Date()) : 0;\n\n    // If dismiss is set to true, then the checklist disappears completely.\n    // If set to false, it just marks seen on backend but keeps it on web for the session.\n    const markCompletedAsSeen = (dismiss: boolean = true) => {\n        if (dismiss) {\n            setChecklist(undefined);\n        }\n        api<ChecklistApiResponse>(seenCompletedDriveChecklist('get-started'));\n    };\n\n    return {\n        isLoading,\n        completedActions: checklist?.Items || [],\n        isCompleted: checklist ? checklist.UserWasRewarded : true,\n        isVisible: checklist?.Visible || false,\n        expiresInDays,\n        reload,\n        markCompletedAsSeen,\n    };\n}\n","import { c, msgid } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    Icon,\n    InnerModal,\n    Loader,\n    ModalTwo,\n    OnboardingContent,\n    OnboardingModal,\n    OnboardingStep,\n    OnboardingStepRenderCallback,\n} from '@proton/components';\nimport { getAppName } from '@proton/shared/lib/apps/helper';\nimport { APPS } from '@proton/shared/lib/constants';\nimport drive1gbSvg from '@proton/styles/assets/img/onboarding/drive-1gb.svg';\nimport onboardingWelcome from '@proton/styles/assets/img/onboarding/drive-welcome.svg';\n\nimport useChecklist from './useChecklist';\n\ninterface Props {\n    showGenericSteps?: boolean;\n    onDone?: () => void;\n    open?: boolean;\n}\n\nconst DriveOnboardingModal = (props: Props) => {\n    const appName = getAppName(APPS.PROTONDRIVE);\n\n    const { isLoading, expiresInDays } = useChecklist();\n\n    if (isLoading) {\n        return (\n            <ModalTwo open={true} size=\"small\">\n                <InnerModal className=\"mt2 mb2\">\n                    <div className=\"flex flex-column flex-align-items-center\">\n                        <Loader size=\"medium\" className=\"mt1 mb1\" />\n                    </div>\n                </InnerModal>\n            </ModalTwo>\n        );\n    }\n\n    const onboardingSteps = [\n        ({ onNext, displayGenericSteps }: OnboardingStepRenderCallback) => (\n            <OnboardingStep>\n                <OnboardingContent\n                    title={c('Onboarding Title').t`Welcome to ${appName}`}\n                    description={c('Onboarding Info')\n                        .t`Your trusty online vault for vital documents and precious memories.`}\n                    img={<img src={onboardingWelcome} alt={appName} />}\n                />\n                <footer>\n                    <Button size=\"large\" color=\"norm\" fullWidth onClick={onNext}>\n                        {displayGenericSteps || expiresInDays > 0\n                            ? c('Onboarding Action').t`Next`\n                            : c('Onboarding Action').t`Start using ${appName}`}\n                    </Button>\n                </footer>\n            </OnboardingStep>\n        ),\n    ];\n\n    if (expiresInDays > 0) {\n        onboardingSteps.push(({ onNext, displayGenericSteps }: OnboardingStepRenderCallback) => (\n            <OnboardingStep>\n                <OnboardingContent\n                    title={c('Onboarding Title').t`Your welcome bonus`}\n                    description={c('Onboarding Info')\n                        .t`Get started using Proton Drive and we'll double your free storage to 1GB!`}\n                    img={<img src={drive1gbSvg} alt={appName} />}\n                />\n                <div>\n                    {c('Onboarding Info').ngettext(\n                        msgid`Simply complete the following in the next ${expiresInDays} day:`,\n                        `Simply complete the following in the next ${expiresInDays} days:`,\n                        expiresInDays\n                    )}\n                    <ul className=\"unstyled mt1\">\n                        <li className=\"my0-5\">\n                            <Icon name=\"checkmark-circle\" /> {c('Onboarding Info').t`Upload a file`}\n                        </li>\n                        <li className=\"my0-5\">\n                            <Icon name=\"checkmark-circle\" /> {c('Onboarding Info').t`Create a share link`}\n                        </li>\n                        <li className=\"my0-5\">\n                            <Icon name=\"checkmark-circle\" /> {c('Onboarding Info').t`Set a recovery method`}\n                        </li>\n                    </ul>\n                </div>\n                <footer>\n                    <Button size=\"large\" color=\"norm\" fullWidth onClick={onNext}>\n                        {displayGenericSteps\n                            ? c('Onboarding Action').t`Next`\n                            : c('Onboarding Action').t`Start using ${appName}`}\n                    </Button>\n                </footer>\n            </OnboardingStep>\n        ));\n    }\n\n    return <OnboardingModal {...props}>{onboardingSteps}</OnboardingModal>;\n};\n\nexport default DriveOnboardingModal;\n","import { c } from 'ttag';\n\nimport { DropdownMenuButton, Tooltip } from '@proton/components';\n\nimport useConfirm from '../../../hooks/util/useConfirm';\nimport { useSearchControl } from '../../../store';\n\nexport default function ClearSearchDataButton() {\n    const { openConfirmModal } = useConfirm();\n    const { searchEnabled, hasData, deleteData } = useSearchControl();\n\n    if (!hasData || !searchEnabled) {\n        return null;\n    }\n\n    const handleDeleteESIndex = () => {\n        openConfirmModal({\n            onConfirm: deleteData,\n            title: c('Info').t`Clear encrypted search data`,\n            confirm: c('Info').t`Clear data`,\n            message: c('Info')\n                .t`Clearing browser data will clear the search index on this device. All files would need to be re-indexed again while using the search functionality.`,\n        });\n    };\n\n    return (\n        <>\n            <hr className=\"mt0-5 mb0-5\" />\n            <Tooltip title={c('Info').t`Clears browser data related to the encrypted search.`}>\n                <DropdownMenuButton onClick={handleDeleteESIndex} className=\"flex flex-nowrap flex-justify-center\">\n                    <span className=\"color-weak\">{c('Action').t`Clear browser data`}</span>\n                </DropdownMenuButton>\n            </Tooltip>\n        </>\n    );\n}\n","import { useEffect, useRef, useState } from 'react';\n\nimport { useUser } from '@proton/components';\nimport { ESIndexingState, defaultESIndexingState, estimateIndexingProgress } from '@proton/encrypted-search';\nimport { SECOND } from '@proton/shared/lib/constants';\nimport { wait } from '@proton/shared/lib/helpers/promise';\n\nimport { useSearchLibrary } from '..';\n\nconst useSearchState = () => {\n    const [user] = useUser();\n    const { getProgressRecorderRef, getESDBStatus } = useSearchLibrary();\n    const { isBuilding, isRefreshing } = getESDBStatus();\n    const [esState, setESState] = useState<ESIndexingState>(defaultESIndexingState);\n\n    const abortProgressRef = useRef<AbortController>(new AbortController());\n\n    const setProgress = async () => {\n        while (!abortProgressRef.current.signal.aborted) {\n            setESState((esState) => {\n                const [esProgress, esTotal] = getProgressRecorderRef().current;\n                const endTime = performance.now();\n\n                const { estimatedMinutes, currentProgressValue } = estimateIndexingProgress(\n                    user.ID,\n                    esProgress,\n                    esTotal,\n                    endTime,\n                    esState\n                );\n\n                return {\n                    ...esState,\n                    endTime,\n                    esProgress,\n                    totalIndexingMessages: esTotal,\n                    estimatedMinutes: estimatedMinutes || esState.estimatedMinutes,\n                    currentProgressValue: currentProgressValue || esState.currentProgressValue,\n                };\n            });\n            await wait(2 * SECOND);\n        }\n    };\n\n    const startProgress = async () => {\n        abortProgressRef.current = new AbortController();\n        const [esPrevProgress, totalIndexingMessages] = getProgressRecorderRef().current;\n        setESState((esState) => {\n            return {\n                ...esState,\n                startTime: performance.now(),\n                esPrevProgress,\n                totalIndexingMessages,\n            };\n        });\n        await wait(2 * SECOND);\n        void setProgress();\n    };\n\n    const stopProgress = () => {\n        abortProgressRef.current.abort();\n        setESState(() => defaultESIndexingState);\n    };\n\n    useEffect(() => {\n        if (isBuilding || isRefreshing) {\n            void startProgress();\n        } else {\n            stopProgress();\n        }\n    }, [isBuilding, isRefreshing]);\n\n    useEffect(() => {\n        // Safety stop for situation when the whole component where\n        // the hook is used is removed from the DOM.\n        return () => stopProgress();\n    }, []);\n\n    return esState;\n};\n\nexport default useSearchState;\n","import * as React from 'react';\n\nimport { c, msgid } from 'ttag';\n\nimport { Progress, classnames, useUser } from '@proton/components';\nimport { getESCurrentProgress, getESTotal } from '@proton/encrypted-search';\n\nimport { useSearchLibrary } from '../../../store';\nimport useSearchState from '../../../store/_search/useSearchState';\n\nimport './SearchDropdown.scss';\n\nexport const SearchIndexingProgress = () => {\n    const [user] = useUser();\n    const { getESDBStatus } = useSearchLibrary();\n    const { isRefreshing } = getESDBStatus();\n    const { esProgress, totalIndexingMessages, estimatedMinutes, currentProgressValue } = useSearchState();\n    const isEstimating =\n        estimatedMinutes === 0 && (totalIndexingMessages === 0 || esProgress !== totalIndexingMessages);\n\n    const progressFromBuildEvent = isRefreshing ? 0 : getESCurrentProgress(user.ID);\n    const progressValue = isEstimating ? progressFromBuildEvent : currentProgressValue;\n\n    // Progress indicator\n    const totalProgressToShow = Math.max(esProgress, getESTotal(user.ID));\n    let progressStatus: string = '';\n    if (isEstimating) {\n        progressStatus = c('Info').t`Estimating time remaining...`;\n    } else if (isRefreshing) {\n        progressStatus = c('Info').t`Updating drive search...`;\n    } else {\n        // translator: esProgress is a number representing the current message being fetched, totalIndexingMessages is the total number of message in the mailbox\n        progressStatus = c('Info').jt`Indexing items ${esProgress} out of ${totalProgressToShow}` as string;\n    }\n\n    const etaMessage =\n        estimatedMinutes <= 1\n            ? c('Info').t`Estimated time remaining: Less than a minute`\n            : // translator: the variable is a positive integer (written in digits) always strictly bigger than 1\n              c('Info').ngettext(\n                  msgid`Estimated time remaining: ${estimatedMinutes} minute`,\n                  `Estimated time remaining: ${estimatedMinutes} minutes`,\n                  estimatedMinutes\n              );\n\n    return (\n        <div className=\"mt1-5 flex flex-column\">\n            <span className=\"color-weak relative advanced-search-progress-status\" aria-live=\"polite\" aria-atomic=\"true\">\n                {progressStatus}\n            </span>\n            <div className=\"flex flex-justify-space-between\">\n                <Progress\n                    value={progressValue || 0}\n                    aria-describedby=\"timeRemaining\"\n                    className={classnames(['mt0-5 mb0-5 flex-item-fluid'])}\n                />\n            </div>\n            <span\n                id=\"timeRemaining\"\n                aria-live=\"polite\"\n                aria-atomic=\"true\"\n                className={classnames([\n                    'color-weak relative advanced-search-time-remaining',\n                    isEstimating ? 'visibility-hidden' : undefined,\n                ])}\n            >\n                {etaMessage}\n            </span>\n        </div>\n    );\n};\n","import * as React from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { Dropdown, useUser } from '@proton/components';\nimport { indexKeyExists, isDBReadyAfterBuilding } from '@proton/encrypted-search';\nimport { DRIVE_APP_NAME } from '@proton/shared/lib/constants';\n\nimport { useSearchLibrary } from '../../../store';\nimport { SearchIndexingProgress } from './SearchIndexingProgress';\n\nimport './SearchDropdown.scss';\n\ninterface Props {\n    isOpen: boolean;\n    anchorRef: React.RefObject<HTMLDivElement>;\n    onClose: (e: any) => void;\n    onClosed: () => void;\n}\n\nexport const SearchDropdown = ({ isOpen, anchorRef, onClose, onClosed }: Props) => {\n    const [user] = useUser();\n    const { getESDBStatus } = useSearchLibrary();\n    const { isRefreshing, esEnabled, dbExists } = getESDBStatus();\n    const showProgress = indexKeyExists(user.ID) && esEnabled && (!isDBReadyAfterBuilding(user.ID) || isRefreshing);\n\n    return (\n        <>\n            <Dropdown\n                anchorRef={anchorRef as React.RefObject<HTMLElement>}\n                isOpen={isOpen}\n                originalPlacement=\"bottom-start\"\n                autoClose={false}\n                autoCloseOutside={true}\n                noMaxSize\n                onClose={onClose}\n                onClosed={onClosed}\n                className=\"dropdown-content--wide advanced-search-dropdown search-dropdown\"\n                disableDefaultArrowNavigation\n                UNSTABLE_AUTO_HEIGHT\n            >\n                <div className=\"pl1-5 pr1-5 pt1-5 pb1\">\n                    <div>\n                        <div className=\"flex\">\n                            <span className=\"inline-flex text-bold text-lg\">\n                                {dbExists ? c('Info').t`Search Enabled` : c('Info').t`Enabling drive search`}\n                            </span>\n                        </div>\n                        <p className=\"mb0\">\n                            {dbExists\n                                ? c('Info')\n                                      .t`Private search enabled. You may now close this dialogue and search for files and folders.`\n                                : c('Info')\n                                      .t`To enable truly private search, we need to index your files locally. You can still use ${DRIVE_APP_NAME} normally - we’ll let you know when indexing is done.`}\n                        </p>\n                    </div>\n                    {showProgress && <SearchIndexingProgress />}\n                    <div className=\"flex flex-justify-end mt1\">\n                        <Button shape=\"ghost\" color=\"norm\" onClick={onClose}>{c('Action').t`Got it`}</Button>\n                    </div>\n                </div>\n            </Dropdown>\n        </>\n    );\n};\n","import React, { useCallback, useRef } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { Href, Icon, InputTwo, Spotlight, usePopperAnchor } from '@proton/components';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport esSpotlightIcon from '@proton/styles/assets/img/illustrations/spotlight-stars.svg';\n\nimport useNavigate from '../../../hooks/drive/useNavigate';\nimport { useSearchControl } from '../../../store';\nimport { useSearchResults } from '../../../store/_search';\nimport { reportError } from '../../../store/_utils';\nimport { useSpotlight } from '../../useSpotlight';\nimport { SearchDropdown } from './SearchDropdown';\nimport { useSearchParams } from './useSearchParams';\n\nimport './SearchField.scss';\n\nexport const SearchField = () => {\n    const indexingDropdownAnchorRef = useRef<HTMLDivElement>(null);\n    const indexingDropdownControl = usePopperAnchor<HTMLButtonElement>();\n    const { searchSpotlight } = useSpotlight();\n    const { dbExists } = useSearchResults();\n\n    const navigation = useNavigate();\n    const { searchEnabled, isBuilding, isDisabled, disabledReason, prepareSearchData } = useSearchControl();\n    const [searchParams, setSearchParams] = useSearchParams();\n\n    const handleSearch = useCallback((keyword = '') => {\n        const encodedKeyword = encodeURIComponent(keyword);\n        if (keyword.length !== 0) {\n            navigation.navigateToSearch(encodedKeyword);\n        } else {\n            navigation.navigateToRoot();\n        }\n    }, []);\n\n    const handleFieldFocus = () => {\n        return prepareSearchData().catch(reportError);\n    };\n\n    const handleInputClick = () => {\n        if (dbExists && !isBuilding) {\n            return;\n        }\n\n        searchSpotlight.close();\n\n        if (indexingDropdownControl.isOpen) {\n            indexingDropdownControl.close();\n            return;\n        }\n        indexingDropdownControl.open();\n\n        return handleFieldFocus();\n    };\n\n    const handleClosedDropdown = (e?: Event) => {\n        e?.stopPropagation();\n        indexingDropdownControl.close();\n    };\n\n    if (!searchEnabled) {\n        return null;\n    }\n\n    const placeholderText = isDisabled ? disabledReason : c('Action').t`Search drive`;\n    const imageProps = { src: esSpotlightIcon, alt: c('Info').t`Encrypted search is here` };\n    const shouldShowSpotlight = searchSpotlight.isOpen && !indexingDropdownControl.isOpen;\n\n    return (\n        <div ref={indexingDropdownAnchorRef} className=\"searchfield-container\">\n            <Spotlight\n                className=\"search-spotlight\"\n                originalPlacement=\"bottom-start\"\n                show={shouldShowSpotlight}\n                onDisplayed={searchSpotlight.onDisplayed}\n                content={\n                    <div className=\"flex flex-nowrap\">\n                        <figure className=\"flex-item flex-item-noshrink pr1\">\n                            {imageProps && <img className=\"hauto\" {...imageProps} alt={imageProps.alt || ''} />}\n                        </figure>\n                        <div className=\"flex-item\">\n                            <div className=\"text-bold text-lg mauto\">{c('Spotlight').t`Encrypted search is here`}</div>\n                            {c('Spotlight').t`Now you can easily search Drive files while keeping your data secure.`}\n                            <br />\n                            <Href url={getKnowledgeBaseUrl('/search-drive')} title=\"How does encrypted search work?\">\n                                {c('Info').t`How does encrypted search work?`}\n                            </Href>\n                        </div>\n                    </div>\n                }\n            >\n                <>\n                    <div onClick={handleInputClick}>\n                        <InputTwo\n                            value={searchParams}\n                            placeholder={placeholderText}\n                            // this handler has to be passed with `onFocus` prop, as before it used to trigger\n                            // caching twice in certain cases (the focus stayed on the searchbar after\n                            // indexing, the prepareSearchData is not called until the user hits enter\n                            // to do the search.)\n                            onFocus={handleFieldFocus}\n                            onChange={(e) => setSearchParams(e.target.value)}\n                            onKeyDown={(e) => {\n                                if (e.key === 'Enter') {\n                                    handleSearch(searchParams);\n                                }\n                                if (e.key === 'Escape') {\n                                    setSearchParams('');\n                                    e.currentTarget.blur();\n                                }\n                            }}\n                            disabled={isDisabled}\n                            prefix={\n                                <Button\n                                    icon\n                                    disabled={!searchParams || isDisabled}\n                                    shape=\"ghost\"\n                                    color=\"weak\"\n                                    size=\"small\"\n                                    className=\"rounded-sm\"\n                                    title={c('Action').t`Search`}\n                                    onClick={() => {\n                                        handleSearch(searchParams);\n                                    }}\n                                >\n                                    <Icon name=\"magnifier\" alt={c('Action').t`Search`} />\n                                </Button>\n                            }\n                            suffix={\n                                searchParams ? (\n                                    <Button\n                                        type=\"button\"\n                                        shape=\"ghost\"\n                                        color=\"weak\"\n                                        size=\"small\"\n                                        className=\"rounded-sm\"\n                                        title={c('Action').t`Clear`}\n                                        onClick={() => {\n                                            setSearchParams('');\n                                            handleSearch('');\n                                        }}\n                                    >\n                                        {c('Action').t`Clear`}\n                                    </Button>\n                                ) : null\n                            }\n                        />\n                    </div>\n                    <SearchDropdown\n                        isOpen={indexingDropdownControl.isOpen}\n                        anchorRef={indexingDropdownAnchorRef}\n                        onClose={handleClosedDropdown}\n                        onClosed={handleClosedDropdown}\n                    />\n                </>\n            </Spotlight>\n        </div>\n    );\n};\n","import { useEffect, useState } from 'react';\nimport { useLocation } from 'react-router';\n\n// TODO: handle it with containers\nimport { extractSearchParameters } from '../../../store/_search/utils';\n\nexport const useSearchParams = () => {\n    const location = useLocation();\n\n    const [value, updateValue] = useState('');\n\n    useEffect(() => {\n        updateValue(extractSearchParameters(location));\n    }, [location]);\n\n    return [value, updateValue] as [string, React.Dispatch<React.SetStateAction<string>>];\n};\n","import { ReactNode } from 'react';\n\nimport { c } from 'ttag';\n\nimport {\n    PrivateHeader,\n    RebrandingFeedbackModal,\n    TopNavbarListItemContactsDropdown,\n    TopNavbarListItemFeedbackButton,\n    TopNavbarListItemSettingsDropdown,\n    UserDropdown,\n    useActiveBreakpoint,\n    useHasRebrandingFeedback,\n    useModalState,\n} from '@proton/components';\nimport { APPS } from '@proton/shared/lib/constants';\n\nimport DriveOnboardingModal from '../onboarding/DriveOnboardingModal';\nimport ClearSearchDataButton from './search/ClearSearchDataButton';\nimport { SearchField } from './search/SearchField';\n\ninterface Props {\n    isHeaderExpanded: boolean;\n    toggleHeaderExpanded: () => void;\n    floatingPrimary: ReactNode;\n    logo: ReactNode;\n    searchBox?: ReactNode;\n    title?: string;\n}\n\nexport const DriveHeader = ({\n    logo,\n    isHeaderExpanded,\n    toggleHeaderExpanded,\n    floatingPrimary,\n    title = c('Title').t`Drive`,\n    searchBox,\n}: Props) => {\n    const { isNarrow } = useActiveBreakpoint();\n    const hasRebrandingFeedback = useHasRebrandingFeedback();\n    const [onboardingModal, setOnboardingModal, renderOnboardingModal] = useModalState();\n    const [rebrandingFeedbackModal, setRebrandingFeedbackModal] = useModalState();\n\n    return (\n        <>\n            {renderOnboardingModal && <DriveOnboardingModal showGenericSteps {...onboardingModal} />}\n            <PrivateHeader\n                feedbackButton={\n                    hasRebrandingFeedback ? (\n                        <TopNavbarListItemFeedbackButton onClick={() => setRebrandingFeedbackModal(true)} />\n                    ) : null\n                }\n                userDropdown={<UserDropdown onOpenIntroduction={() => setOnboardingModal(true)} />}\n                logo={logo}\n                title={title}\n                contactsButton={<TopNavbarListItemContactsDropdown />}\n                settingsButton={\n                    <TopNavbarListItemSettingsDropdown to=\"/drive\" toApp={APPS.PROTONACCOUNT}>\n                        <ClearSearchDataButton />\n                    </TopNavbarListItemSettingsDropdown>\n                }\n                expanded={isHeaderExpanded}\n                onToggleExpand={toggleHeaderExpanded}\n                isNarrow={isNarrow}\n                floatingButton={floatingPrimary}\n                searchBox={searchBox}\n            />\n\n            <RebrandingFeedbackModal {...rebrandingFeedbackModal} />\n        </>\n    );\n};\n\nexport const DriveHeaderPrivate = (props: Props) => {\n    return <DriveHeader {...props} searchBox={<SearchField />} />;\n};\n","/**\n * Tells whether or not a given value is between two other given min and max values,\n * including the min value, but excluding the max value.\n */\nconst isBetween = (value: number, min: number, max: number) => value >= min && value < max;\n\nexport default isBetween;\n","import { ComponentPropsWithoutRef } from 'react';\n\nimport isBetween from '@proton/utils/isBetween';\n\nimport { classnames } from '../../helpers';\n\ninterface Props extends ComponentPropsWithoutRef<'div'> {\n    /** whether or not the meter should be thin */\n    thin?: boolean;\n    /** whether or not the meter should be squared */\n    squared?: boolean;\n    /** add a textual label */\n    label?: string;\n    min?: number;\n    low?: number;\n    high?: number;\n    max?: number;\n    optimum?: number;\n    value?: number;\n}\n\nexport enum MeterValue {\n    Optimum = 0,\n    Min = 0,\n    Low = 50,\n    High = 80,\n    Max = 100,\n}\n\nconst { Optimum, Min, Low, High, Max } = MeterValue;\n\nexport const getMeterColor = (\n    value: number,\n    optimum: number = Optimum,\n    min: number = Min,\n    low: number = Low,\n    high: number = High,\n    max: number = Max\n) => {\n    const isLow = isBetween(value, min, low);\n    const isMid = isBetween(value, low, high);\n    const isHigh = isBetween(value, high, max) || value >= max;\n\n    if (isBetween(optimum, min, low)) {\n        if (isHigh) {\n            return 'danger';\n        }\n        if (isMid) {\n            return 'warning';\n        }\n        if (isLow) {\n            return 'success';\n        }\n    }\n\n    if (isBetween(optimum, low, high)) {\n        if (isHigh) {\n            return 'warning';\n        }\n        if (isMid) {\n            return 'success';\n        }\n        if (isLow) {\n            return 'warning';\n        }\n    }\n\n    if (isBetween(optimum, high, max) || optimum === max) {\n        if (isHigh) {\n            return 'success';\n        }\n        if (isMid) {\n            return 'warning';\n        }\n        if (isLow) {\n            return 'danger';\n        }\n    }\n\n    console.error(\n        `Misuse of getMeterColor, verify values provided for value (${value}), optimum (${optimum}), min (${min}), max (${max}), low (${low}), high (${high})`\n    );\n\n    return 'danger';\n};\n\nconst Meter = ({\n    thin = false,\n    squared = false,\n    label,\n    min = Min,\n    max = Max,\n    value = 0,\n    id,\n    className,\n    ...rest\n}: Props) => (\n    <div\n        id={id}\n        className={classnames(['meter-bar', thin && 'is-thin', squared && 'is-squared', className])}\n        role=\"meter\"\n        aria-valuemin={min}\n        aria-valuemax={max}\n        aria-valuenow={value}\n        {...rest}\n    >\n        <div\n            className={classnames(['meter-bar-thumb w-custom', `meter-bar-thumb--${getMeterColor(value)}`, 'mrauto'])}\n            style={{ '--width-custom': `${Math.ceil((value / max) * 100)}%` }}\n        >\n            {!rest['aria-labelledby'] && <span className=\"sr-only\">{label || `${value} / ${max}`}</span>}\n        </div>\n    </div>\n);\n\nexport default Meter;\n","import { ReactNode } from 'react';\n\nimport { APPS } from '@proton/shared/lib/constants';\n\nimport { useActiveBreakpoint, useConfig } from '../../hooks';\n\ninterface Props {\n    children: ReactNode;\n}\nconst MobileNavServices = ({ children }: Props) => {\n    const { isNarrow } = useActiveBreakpoint();\n    const { APP_NAME } = useConfig();\n\n    if (!isNarrow || APP_NAME === APPS.PROTONVPN_SETTINGS) {\n        return null;\n    }\n\n    return <nav className=\"p1 flex flex-row flex-justify-space-around flex-item-noshrink bg-norm\">{children}</nav>;\n};\n\nexport default MobileNavServices;\n","import { APPS, APPS_CONFIGURATION, VPN_HOSTNAME } from '@proton/shared/lib/constants';\n\nimport { AppLink, Logo, VpnLogo } from '..';\nimport { useApps, useConfig } from '../../hooks';\nimport Href from '../link/Href';\nimport MobileNavServices from './MobileNavServices';\n\nconst MobileAppsLinks = () => {\n    const { APP_NAME } = useConfig();\n    const applications = useApps();\n    const apps = applications.map((app) => ({\n        toApp: app,\n        title: APPS_CONFIGURATION[app].name,\n    }));\n\n    return (\n        <MobileNavServices>\n            {apps.map(({ toApp, title }) => {\n                const isCurrent = toApp === APP_NAME;\n                return (\n                    <AppLink key={toApp} to=\"/\" toApp={toApp} target=\"_self\" title={title} aria-current={isCurrent}>\n                        <Logo appName={toApp} variant=\"glyph-only\" />\n                    </AppLink>\n                );\n            })}\n            <Href url={`https://${VPN_HOSTNAME}/login`} title={APPS_CONFIGURATION[APPS.PROTONVPN_SETTINGS].name}>\n                <VpnLogo variant=\"glyph-only\" />\n            </Href>\n        </MobileNavServices>\n    );\n};\n\nexport default MobileAppsLinks;\n","import { ComponentPropsWithoutRef, ReactNode, useMemo, useRef } from 'react';\n\nimport { c } from 'ttag';\n\nimport { APPS } from '@proton/shared/lib/constants';\nimport humanSize from '@proton/shared/lib/helpers/humanSize';\nimport { hasMailProfessional, hasNewVisionary, hasVisionary } from '@proton/shared/lib/helpers/subscription';\nimport percentage from '@proton/utils/percentage';\n\nimport { classnames } from '../../helpers';\nimport { useConfig, useSubscription, useUser } from '../../hooks';\nimport { useFocusTrap } from '../focus';\nimport { SettingsLink } from '../link';\nimport { Meter, getMeterColor } from '../progress';\nimport { Tooltip } from '../tooltip';\nimport Hamburger from './Hamburger';\nimport MobileAppsLinks from './MobileAppsLinks';\n\ninterface Props extends ComponentPropsWithoutRef<'div'> {\n    logo?: ReactNode;\n    expanded?: boolean;\n    onToggleExpand?: () => void;\n    primary?: ReactNode;\n    children?: ReactNode;\n    version?: ReactNode;\n    storageGift?: ReactNode;\n    hasAppLinks?: boolean;\n}\n\nconst Sidebar = ({\n    expanded = false,\n    onToggleExpand,\n    hasAppLinks = true,\n    logo,\n    primary,\n    children,\n    version,\n    storageGift,\n    ...rest\n}: Props) => {\n    const rootRef = useRef<HTMLDivElement>(null);\n    const focusTrapProps = useFocusTrap({\n        active: expanded,\n        rootRef,\n    });\n    const { APP_NAME } = useConfig();\n    const [user] = useUser();\n    const [subscription] = useSubscription();\n    const { UsedSpace, MaxSpace, isMember, isSubUser } = user;\n    const spacePercentage = percentage(MaxSpace, UsedSpace);\n\n    const canAddStorage = useMemo(() => {\n        if (!subscription) {\n            return false;\n        }\n        if (isSubUser) {\n            return false;\n        }\n        if (isMember) {\n            return false;\n        }\n        if (hasNewVisionary(subscription) || hasVisionary(subscription) || hasMailProfessional(subscription)) {\n            return false;\n        }\n        return true;\n    }, [subscription, user]);\n\n    const storageText = (\n        <>\n            <span className={classnames(['used-space text-bold', `color-${getMeterColor(spacePercentage)}`])}>\n                {humanSize(UsedSpace)}\n            </span>\n            &nbsp;/&nbsp;<span className=\"max-space\">{humanSize(MaxSpace)}</span>\n        </>\n    );\n\n    return (\n        <div\n            ref={rootRef}\n            className=\"sidebar flex flex-nowrap flex-column no-print outline-none\"\n            data-expanded={expanded}\n            {...rest}\n            {...focusTrapProps}\n        >\n            <div className=\"no-desktop no-tablet flex-item-noshrink\">\n                <div className=\"flex flex-justify-space-between flex-align-items-center pl1 pr1\">\n                    {logo}\n                    <Hamburger expanded={expanded} onToggle={onToggleExpand} />\n                </div>\n            </div>\n            {primary ? <div className=\"px0-5 pb0-5 flex-item-noshrink\">{primary}</div> : null}\n            <div className=\"on-mobile-mt1\" aria-hidden=\"true\" />\n            <div className=\"flex-item-fluid flex-nowrap flex flex-column scroll-if-needed pb1\">{children}</div>\n            {APP_NAME !== APPS.PROTONVPN_SETTINGS ? (\n                <div className=\"app-infos px1\">\n                    <Meter\n                        thin\n                        label={`${c('Storage').t`Your current storage:`} ${humanSize(UsedSpace)} / ${humanSize(\n                            MaxSpace\n                        )}`}\n                        value={Math.ceil(spacePercentage)}\n                    />\n                    <div className=\"flex flex-nowrap flex-justify-space-between py0-5\">\n                        <span>\n                            {canAddStorage ? (\n                                <Tooltip title={c('Storage').t`Upgrade storage`}>\n                                    <SettingsLink\n                                        path=\"/upgrade\"\n                                        className=\"app-infos-storage text-no-decoration text-xs m0\"\n                                    >\n                                        {storageText}\n                                    </SettingsLink>\n                                </Tooltip>\n                            ) : (\n                                <span className=\"app-infos-storage text-xs m0\">{storageText}</span>\n                            )}\n                            {storageGift}\n                        </span>\n\n                        <span className=\"app-infos-compact\">{version}</span>\n                    </div>\n                </div>\n            ) : (\n                <div className=\"border-top\">\n                    <div className=\"text-center pt0-5 pr1 pb0-5 pl1\">{version}</div>\n                </div>\n            )}\n\n            {hasAppLinks ? <MobileAppsLinks /> : null}\n        </div>\n    );\n};\n\nexport default Sidebar;\n","export default function percentage(entire: number, fraction: number) {\n    /*\n     * Safeguard against division by 0 error as well as\n     * NaN inputs for either \"entire\" or \"fraction\".\n     */\n    if (!entire || !fraction) {\n        return 0;\n    }\n\n    return (fraction / entire) * 100;\n}\n","import { HTMLAttributes, ReactNode } from 'react';\n\nimport { c } from 'ttag';\n\nimport { classnames } from '../../helpers';\n\ninterface Props extends HTMLAttributes<HTMLDivElement> {\n    children: ReactNode;\n    className?: string;\n}\n\nconst SidebarNav = ({ children, className, ...rest }: Props) => {\n    return (\n        <nav className={classnames(['navigation max-w100 flex-item-fluid-auto', className])} {...rest}>\n            <h2 className=\"sr-only\">\n                {\n                    // translator: This is a hidden headline for users with screen readers to highlight the main navigation\n                    c('Label').t`Navigation`\n                }\n            </h2>\n            {children}\n        </nav>\n    );\n};\n\nexport default SidebarNav;\n","export const getAppVersion = (versionString: string) => {\n    return versionString.replace(/-beta.(\\d+)/, ' - Beta $1');\n};\n","import { useState } from 'react';\n\nimport markdownit from 'markdown-it';\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\n\nimport { getAppVersion } from '../../helpers';\nimport {\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n} from '../modalTwo';\n\nimport './ChangeLogModal.scss';\n\nconst md = markdownit('default', {\n    breaks: true,\n    linkify: true,\n});\n\nconst defaultRender =\n    md.renderer.rules.link_open ||\n    function render(tokens, idx, options, env, self) {\n        return self.renderToken(tokens, idx, options);\n    };\n\nmd.renderer.rules.link_open = (tokens, idx, options, env, self) => {\n    tokens[idx].attrPush(['target', '_blank']);\n    return defaultRender(tokens, idx, options, env, self);\n};\n\ninterface Props extends ModalProps {\n    changelog?: string;\n}\n\nconst ChangelogModal = ({ changelog = '', ...rest }: Props) => {\n    const [html] = useState(() => {\n        const modifiedChangelog = changelog.replace(/\\[(\\d+\\.\\d+\\.\\d+[^\\]]*)]/g, (match, capture) => {\n            return `[${getAppVersion(capture)}]`;\n        });\n        return {\n            __html: md.render(modifiedChangelog),\n        };\n    });\n\n    return (\n        <Modal size=\"large\" data-testid=\"changelog-modal\" {...rest}>\n            <ModalHeader title={c('Title').t`What's new`} />\n            <ModalContent>\n                <div className=\"modal-content-inner-changelog\" dangerouslySetInnerHTML={html} dir=\"ltr\" lang=\"en\" />\n            </ModalContent>\n            <ModalFooter>\n                <Button data-testid=\"changelog-modal:close\" onClick={rest.onClose}>{c('Action').t`Close`}</Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default ChangelogModal;\n","import { c } from 'ttag';\n\nimport { APPS_CONFIGURATION } from '@proton/shared/lib/constants';\n\nimport { getAppVersion } from '../../helpers';\nimport { useConfig, useEarlyAccess } from '../../hooks';\nimport { useModalState } from '../modalTwo';\nimport { Tooltip } from '../tooltip';\nimport ChangelogModal from './ChangelogModal';\n\ninterface Props {\n    appName?: string;\n    appVersion?: string;\n    changelog?: string;\n}\n\nconst envMap = {\n    alpha: 'α',\n    beta: 'β',\n    relaunch: 'δ',\n};\n\nconst AppVersion = ({ appVersion: maybeAppVersion, appName: maybeAppName, changelog }: Props) => {\n    const { APP_NAME, APP_VERSION, DATE_VERSION } = useConfig();\n    const { currentEnvironment } = useEarlyAccess();\n    const [changelogModal, setChangelogModalOpen, render] = useModalState();\n\n    const appName = maybeAppName || APPS_CONFIGURATION[APP_NAME]?.name;\n    const appVersion = getAppVersion(maybeAppVersion || APP_VERSION);\n    const className = 'app-infos-version text-xs m0';\n    const title = DATE_VERSION;\n    const children = (\n        <>\n            <span className=\"app-infos-name mr0-25\">{appName}</span>\n            <span className=\"app-infos-number\" data-testid=\"app-infos:release-notes\">\n                {appVersion}\n                {currentEnvironment && envMap[currentEnvironment] && ` ${envMap[currentEnvironment]}`}\n            </span>\n        </>\n    );\n\n    if (!changelog) {\n        return (\n            <span title={title} className={className}>\n                {children}\n            </span>\n        );\n    }\n\n    return (\n        <>\n            {render && <ChangelogModal {...changelogModal} changelog={changelog} />}\n            <Tooltip title={c('Storage').t`Release notes`}>\n                <button\n                    type=\"button\"\n                    data-testid=\"app-infos:release-notes-button\"\n                    onClick={() => setChangelogModalOpen(true)}\n                    title={title}\n                    className={className}\n                >\n                    {children}\n                </button>\n            </Tooltip>\n        </>\n    );\n};\n\nexport default AppVersion;\n","import { AppVersion } from '@proton/components';\n\nimport changelog from '../../../../../CHANGELOG.md';\n\nconst DriveSidebarFooter = () => <AppVersion changelog={changelog} />;\n\nexport default DriveSidebarFooter;\n","import { HTMLAttributes, ReactNode } from 'react';\n\nimport { classnames } from '../../helpers';\n\ninterface Props extends HTMLAttributes<HTMLUListElement> {\n    listClassName?: string;\n    className?: string;\n    children?: ReactNode;\n}\n\nconst SidebarList = ({ className, listClassName = 'navigation-list', children, ...rest }: Props) => {\n    return (\n        <ul className={classnames(['unstyled my0', listClassName, className])} {...rest}>\n            {children}\n        </ul>\n    );\n};\n\nexport const SubSidebarList = ({ children, ...rest }: Props) => {\n    return (\n        <SidebarList listClassName=\"navigation-sublist\" {...rest}>\n            {children}\n        </SidebarList>\n    );\n};\n\nexport default SidebarList;\n","import { LiHTMLAttributes } from 'react';\n\nimport { classnames } from '../../helpers';\n\ninterface Props extends LiHTMLAttributes<HTMLLIElement> {\n    itemClassName?: string;\n}\n\nconst SidebarListItem = ({\n    className = '',\n    itemClassName = 'navigation-item px0-5 mb0-15',\n    children,\n    ...rest\n}: Props) => {\n    return (\n        <li className={classnames([itemClassName, className])} {...rest}>\n            {children}\n        </li>\n    );\n};\n\nexport const SubSidebarListItem = (props: Props) => {\n    return <SidebarListItem itemClassName=\"navigation-subitem\" {...props} />;\n};\n\nexport default SidebarListItem;\n","import { ReactNode, Ref, forwardRef } from 'react';\nimport { NavLink, NavLinkProps } from 'react-router-dom';\n\nimport { classnames } from '../../helpers';\n\nexport interface Props extends Omit<NavLinkProps, 'className'> {\n    children: ReactNode;\n    itemClassName?: string;\n    className?: string;\n}\n\nconst SidebarListItemLink = forwardRef<HTMLAnchorElement, Props>(\n    ({ children, itemClassName = 'navigation-link', className, ...rest }: Props, ref: Ref<HTMLAnchorElement>) => {\n        return (\n            <NavLink ref={ref} className={classnames([itemClassName, className])} {...rest}>\n                {children}\n            </NavLink>\n        );\n    }\n);\n\nexport const SubSidebarListItemLink = ({ children, ...rest }: Props) => {\n    return (\n        <SidebarListItemLink itemClassName=\"navigation-sublink\" {...rest}>\n            {children}\n        </SidebarListItemLink>\n    );\n};\n\nSidebarListItemLink.displayName = 'SidebarListItemLink';\n\nexport default SidebarListItemLink;\n","import { HTMLAttributes, ReactNode } from 'react';\n\nimport { IconName } from '../icon';\n\ninterface Props extends HTMLAttributes<HTMLSpanElement> {\n    icon?: IconName;\n    iconColor?: string;\n    children?: ReactNode;\n    title?: string;\n    left?: ReactNode;\n    right?: ReactNode;\n}\n\nconst SidebarListItemContent = ({ left, right, children, ...rest }: Props) => {\n    return (\n        <span className=\"flex flex-nowrap w100 flex-align-items-center\" {...rest}>\n            {left}\n            <span className=\"flex-item-fluid max-w100 flex flex-align-items-center flex-nowrap\">{children}</span>\n            {right && <span className=\"flex-no-min-children flex-align-items-center\">{right}</span>}\n        </span>\n    );\n};\n\nexport default SidebarListItemContent;\n","export const generateSidebarItemStyle = (nestingLevel: number = 0) => {\n    return { marginLeft: `${(nestingLevel * 10) / 16}rem` };\n};\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { Icon, classnames } from '@proton/components';\n\ninterface Props {\n    className?: string;\n    expanded: boolean;\n    onClick: () => void;\n    style?: React.CSSProperties;\n}\n\nexport default function ExpandButton({ className, expanded, onClick, style }: Props) {\n    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {\n        e.stopPropagation();\n        e.preventDefault();\n        onClick();\n    };\n\n    return (\n        <Button\n            shape=\"ghost\"\n            size=\"small\"\n            icon\n            className={classnames([\n                'flex-item-noshrink flex flex-align-items-center drive-sidebar--button-expand',\n                className,\n            ])}\n            onClick={handleClick}\n            aria-expanded={expanded}\n            title={expanded ? c('Action').t`Collapse folder` : c('Action').t`Expand folder`}\n            style={style}\n        >\n            <Icon\n                name={expanded ? 'chevron-down' : 'chevron-right'}\n                alt={expanded ? c('Action').t`Collapse folder` : c('Action').t`Expand folder`}\n            />\n        </Button>\n    );\n}\n","import {\n    FileIcon,\n    FileNameDisplay,\n    Loader,\n    SidebarListItem,\n    SidebarListItemContent,\n    SidebarListItemLink,\n} from '@proton/components';\n\nimport { TreeItem } from '../../../../store';\nimport { generateSidebarItemStyle } from '../utils';\nimport ExpandButton from './ExpandButton';\nimport useSubfolderLoading from './useSubfolderLoading';\n\ninterface Props {\n    shareId: string;\n    folder: TreeItem;\n    level: number;\n    toggleExpand: () => void;\n}\n\nexport default function DriveSidebarSubfolder({ shareId, folder, level, toggleExpand }: Props) {\n    const isLoading = useSubfolderLoading(folder);\n\n    const handleFolderClick = (e: any) => {\n        if (e.detail !== 1) {\n            e.stopPropagation();\n            e.preventDefault();\n        }\n    };\n\n    const expandeButtonStyle: React.CSSProperties =\n        folder.children.length === 0 && folder.isLoaded\n            ? {\n                  visibility: 'hidden',\n              }\n            : {};\n\n    return (\n        <SidebarListItem>\n            <SidebarListItemLink\n                to={`/${shareId}/folder/${folder.link.linkId}`}\n                onClick={handleFolderClick}\n                onDoubleClick={toggleExpand}\n                title={folder.link.name}\n            >\n                <SidebarListItemContent>\n                    <div className=\"flex flex-nowrap\" style={generateSidebarItemStyle(level)}>\n                        <ExpandButton\n                            className=\"mr0-5\"\n                            expanded={folder.isExpanded}\n                            onClick={toggleExpand}\n                            style={expandeButtonStyle}\n                        />\n                        {isLoading ? (\n                            <Loader className=\"mr0-5 flex flex-item-noshrink drive-sidebar--icon\" />\n                        ) : (\n                            <FileIcon className=\"mr0-5 flex-item-centered-vert drive-sidebar--icon\" mimeType=\"Folder\" />\n                        )}\n                        <FileNameDisplay text={folder.link.name} />\n                    </div>\n                </SidebarListItemContent>\n            </SidebarListItemLink>\n        </SidebarListItem>\n    );\n}\n","import { useEffect, useState } from 'react';\n\nimport { TreeItem } from '../../../../store';\n\nexport default function useSubfolderLoading(folder: TreeItem) {\n    const [isLoading, setIsLoading] = useState(false);\n\n    useEffect(() => {\n        if (folder.isLoaded) {\n            setIsLoading(false);\n        }\n        if (!folder.isExpanded || folder.isLoaded) {\n            return;\n        }\n        const t = setTimeout(() => setIsLoading(true), 250);\n        return () => {\n            clearTimeout(t);\n        };\n    }, [folder]);\n\n    return isLoading;\n}\n","import { ReactNode } from 'react';\n\nimport { TreeItem } from '../../../../store';\nimport DriveSidebarSubfolder from './DriveSidebarSubfolder';\n\ninterface Props {\n    shareId: string;\n    rootFolder?: TreeItem;\n    toggleExpand: (linkId: string) => void;\n    defaultLevel?: number;\n}\n\nexport default function DriveSidebarSubfolders({ shareId, rootFolder, toggleExpand, defaultLevel = 0 }: Props) {\n    if (!rootFolder || !rootFolder.isExpanded || !rootFolder.children?.length) {\n        return null;\n    }\n\n    const folderReducer = (acc: ReactNode[], folder: TreeItem, level = defaultLevel): any[] => {\n        acc.push(\n            <DriveSidebarSubfolder\n                key={folder.link.linkId}\n                shareId={shareId}\n                folder={folder}\n                level={level}\n                toggleExpand={() => toggleExpand(folder.link.linkId)}\n            />\n        );\n        if (folder.isExpanded && folder.children?.length) {\n            folder.children.forEach((subfolder: TreeItem) => folderReducer(acc, subfolder, level + 1));\n        }\n        return acc;\n    };\n    return <>{rootFolder.children.reduce((acc: ReactNode[], folder: TreeItem) => folderReducer(acc, folder), [])}</>;\n}\n","import { classnames } from '../../helpers';\nimport Icon, { IconProps } from '../icon/Icon';\n\nconst SidebarListItemContentIcon = ({ className, ...rest }: IconProps) => {\n    return (\n        <Icon\n            className={classnames(['navigation-icon flex-item-noshrink mr0-5 flex-item-centered-vert', className])}\n            {...rest}\n        />\n    );\n};\n\nexport default SidebarListItemContentIcon;\n","import * as React from 'react';\n\nimport {\n    IconName,\n    SidebarListItem,\n    SidebarListItemContent,\n    SidebarListItemContentIcon,\n    SidebarListItemLink,\n    useLoading,\n} from '@proton/components';\nimport { wait } from '@proton/shared/lib/helpers/promise';\n\nimport { useDriveEventManager } from '../../../store';\n\ninterface Props {\n    children: React.ReactNode;\n    icon: IconName;\n    isActive: boolean;\n    shareId?: string;\n    to: string;\n    rightIcon?: React.ReactNode;\n    onDoubleClick?: () => void;\n    style?: React.CSSProperties;\n}\n\nconst DriveSidebarListItem = ({ to, children, icon, shareId, isActive, rightIcon, onDoubleClick, style }: Props) => {\n    const driveEventManager = useDriveEventManager();\n    const [refreshing, withRefreshing] = useLoading(false);\n\n    const left = icon ? <SidebarListItemContentIcon name={icon} /> : null;\n\n    const handleDoubleClick = () => {\n        onDoubleClick?.();\n        if (!refreshing && shareId) {\n            withRefreshing(\n                Promise.all([driveEventManager.pollEvents.shares([shareId], { includeCommon: true }), wait(1000)])\n            ).catch(console.warn);\n        }\n    };\n\n    return (\n        <SidebarListItem>\n            <SidebarListItemLink to={to} isActive={() => isActive}>\n                <div className=\"flex flex-nowrap\" style={style}>\n                    <SidebarListItemContent\n                        onDoubleClick={handleDoubleClick}\n                        left={left}\n                        right={rightIcon}\n                        title={typeof children === 'string' ? children : undefined}\n                    >\n                        {children}\n                    </SidebarListItemContent>\n                </div>\n            </SidebarListItemLink>\n        </SidebarListItem>\n    );\n};\n\nexport default DriveSidebarListItem;\n","import { useEffect } from 'react';\n\nimport useActiveShare from '../../../../hooks/drive/useActiveShare';\nimport { useFolderTree } from '../../../../store';\nimport { Device } from '../../../../store/_devices';\nimport DriveSidebarSubfolders from '../DriveSidebarFolders/DriveSidebarSubfolders';\nimport ExpandButton from '../DriveSidebarFolders/ExpandButton';\nimport DriveSidebarListItem from '../DriveSidebarListItem';\nimport { generateSidebarItemStyle } from '../utils';\n\nexport const SidebarDeviceItem = ({\n    device,\n    setSidebarLevel,\n}: {\n    device: Device;\n    setSidebarLevel: (level: number) => void;\n}) => {\n    const { activeFolder } = useActiveShare();\n    const { deepestOpenedLevel, rootFolder, toggleExpand } = useFolderTree(device.shareId, {\n        rootLinkId: device.linkId,\n    });\n\n    useEffect(() => {\n        setSidebarLevel(deepestOpenedLevel);\n    }, [deepestOpenedLevel]);\n\n    const isActive = activeFolder.shareId === device.shareId && activeFolder.linkId === device.linkId;\n\n    return (\n        <div>\n            <DriveSidebarListItem\n                to={`/${device.shareId}/folder/${device.linkId}`}\n                icon=\"tv\"\n                shareId={device.shareId}\n                isActive={isActive}\n                style={generateSidebarItemStyle(1)}\n            >\n                <span className=\"text-ellipsis\" title={device.name}>\n                    {device.name}\n                </span>\n                <ExpandButton\n                    className=\"ml0-5 flex-item-noshrink\"\n                    expanded={Boolean(rootFolder?.isExpanded)}\n                    onClick={() => toggleExpand(device.linkId)}\n                />\n            </DriveSidebarListItem>\n            <DriveSidebarSubfolders\n                shareId={device.shareId}\n                rootFolder={rootFolder}\n                toggleExpand={toggleExpand}\n                defaultLevel={1}\n            />\n        </div>\n    );\n};\n","import { useDevicesListing } from '../../../../store/_devices';\nimport { SidebarDeviceItem } from './SidebarDeviceItem';\n\nexport const SidebarDeviceList = ({\n    isRootExpanded,\n    setSidebarLevel,\n}: {\n    isRootExpanded: boolean;\n    setSidebarLevel: (level: number) => void;\n}) => {\n    const { cachedDevices } = useDevicesListing();\n\n    if (!isRootExpanded || cachedDevices?.length === 0) {\n        return null;\n    }\n\n    const sortedDevices = [...cachedDevices].sort((a, b) => {\n        const nameA = a.name.toUpperCase();\n        const nameB = b.name.toUpperCase();\n        if (nameA < nameB) {\n            return -1;\n        }\n        return nameA > nameB ? 1 : 0;\n    });\n\n    return (\n        <>\n            {sortedDevices.map((device) => (\n                <SidebarDeviceItem key={device.id + device.name} device={device} setSidebarLevel={setSidebarLevel} />\n            ))}\n        </>\n    );\n};\n","import { c } from 'ttag';\n\nimport { Loader } from '@proton/components/components';\n\nimport { useDevicesListing } from '../../../../store/_devices';\nimport ExpandButton from '../DriveSidebarFolders/ExpandButton';\nimport DriveSidebarListItem from '../DriveSidebarListItem';\n\nexport function SidebarDevicesRoot({\n    path,\n    isExpanded,\n    toggleExpand,\n}: {\n    path: string;\n    toggleExpand: () => void;\n    isExpanded: boolean;\n}) {\n    const { cachedDevices, isLoading } = useDevicesListing();\n\n    return (\n        <DriveSidebarListItem\n            key=\"devices-root\"\n            to={'/devices'}\n            icon=\"tv\"\n            isActive={path === '/devices'}\n            onDoubleClick={toggleExpand}\n        >\n            <span className=\"text-ellipsis\" title={c('Title').t`My files`}>\n                {c('Title').t`Synced devices`}\n            </span>\n            {isLoading ? (\n                <Loader className=\"ml0-5 drive-sidebar--icon inline-flex flex-item-noshrink\" />\n            ) : (\n                cachedDevices.length > 0 && (\n                    <ExpandButton\n                        className=\"ml0-5 flex-item-noshrink\"\n                        expanded={isExpanded}\n                        onClick={() => toggleExpand()}\n                    />\n                )\n            )}\n        </DriveSidebarListItem>\n    );\n}\n","import { useState } from 'react';\n\nimport { SidebarDeviceList } from './SidebarDevicesList';\nimport { SidebarDevicesRoot } from './SidebarDevicesRoot';\n\nconst DriveSidebarDevices = ({ path, setSidebarLevel }: { path: string; setSidebarLevel: (level: number) => void }) => {\n    const [isListExpanded, setListExpanded] = useState(false);\n\n    const toggleList = () => {\n        setListExpanded((value) => !value);\n    };\n\n    return (\n        <>\n            <SidebarDevicesRoot path={path} toggleExpand={toggleList} isExpanded={isListExpanded} />\n            <SidebarDeviceList isRootExpanded={isListExpanded} setSidebarLevel={setSidebarLevel} />\n        </>\n    );\n};\n\nexport default DriveSidebarDevices;\n","import { c } from 'ttag';\n\nimport { Icon, Tooltip, useModals } from '@proton/components';\n\nimport { useLockedVolume } from '../../../store';\nimport FilesRecoveryModal from './FilesRecoveryModal';\n\ninterface Props {\n    className?: string;\n}\n\nconst FileRecoveryIcon = ({ className }: Props) => {\n    const { createModal } = useModals();\n    const { hasVolumesForRestore } = useLockedVolume();\n\n    return hasVolumesForRestore ? (\n        <Tooltip title={c('Title').t`You have inaccessible files`}>\n            <Icon\n                color=\"red\"\n                name=\"fire\"\n                className={className}\n                onClick={(e) => {\n                    e.preventDefault();\n                    e.stopPropagation();\n\n                    createModal(<FilesRecoveryModal />);\n                }}\n            />\n        </Tooltip>\n    ) : null;\n};\n\nexport default FileRecoveryIcon;\n","import { c } from 'ttag';\n\nimport { Loader } from '@proton/components';\nimport { LinkURLType } from '@proton/shared/lib/drive/constants';\n\nimport { TreeItem } from '../../../../store';\nimport FileRecoveryIcon from '../../../ResolveLockedVolumes/FileRecovery/FileRecoveryIcon';\nimport DriveSidebarListItem from '../DriveSidebarListItem';\nimport ExpandButton from './ExpandButton';\n\ninterface Props {\n    path: string;\n    shareId: string;\n    linkId: string;\n    rootFolder?: TreeItem;\n    toggleExpand: (linkId: string) => void;\n}\n\nexport default function DriveSidebarFoldersRoot({ path, shareId, linkId, rootFolder, toggleExpand }: Props) {\n    const isLoading = !rootFolder?.isLoaded;\n\n    const url = `/${shareId}/${LinkURLType.FOLDER}/${linkId}`;\n    return (\n        <DriveSidebarListItem\n            key=\"root\"\n            to={url}\n            icon=\"inbox\"\n            shareId={shareId}\n            isActive={path === url}\n            onDoubleClick={() => toggleExpand(linkId)}\n        >\n            <span className=\"text-ellipsis\" title={c('Title').t`My files`}>\n                {c('Title').t`My files`}\n            </span>\n            {isLoading ? (\n                <Loader className=\"ml0-5 drive-sidebar--icon inline-flex\" />\n            ) : (\n                rootFolder.children.length > 0 && (\n                    <ExpandButton\n                        className=\"ml0-5 flex-item-noshrink\"\n                        expanded={rootFolder.isExpanded}\n                        onClick={() => toggleExpand(rootFolder.link.linkId)}\n                    />\n                )\n            )}\n            <FileRecoveryIcon className=\"ml0-5\" />\n        </DriveSidebarListItem>\n    );\n}\n","import { useEffect } from 'react';\n\nimport { useFolderTree } from '../../../../store';\nimport DriveSidebarFoldersRoot from './DriveSidebarFoldersRoot';\nimport DriveSidebarSubfolders from './DriveSidebarSubfolders';\n\ninterface Props {\n    path: string;\n    shareId: string;\n    linkId: string;\n    setSidebarLevel: (level: number) => void;\n}\n\nexport default function DriveSidebarFolders({ shareId, linkId, path, setSidebarLevel }: Props) {\n    const { deepestOpenedLevel, rootFolder, toggleExpand } = useFolderTree(shareId, { rootLinkId: linkId });\n\n    useEffect(() => {\n        setSidebarLevel(deepestOpenedLevel);\n    }, [deepestOpenedLevel]);\n\n    return (\n        <>\n            <DriveSidebarFoldersRoot\n                path={path}\n                shareId={shareId}\n                linkId={linkId}\n                rootFolder={rootFolder}\n                toggleExpand={toggleExpand}\n            />\n            <DriveSidebarSubfolders shareId={shareId} rootFolder={rootFolder} toggleExpand={toggleExpand} />\n        </>\n    );\n}\n","import { useState } from 'react';\nimport { useRouteMatch } from 'react-router-dom';\n\nimport { c } from 'ttag';\n\nimport { SidebarList } from '@proton/components';\n\nimport { ShareWithKey } from '../../../store';\nimport useDevicesFeatureFlag from '../../../store/_devices/useDevicesFeatureFlag';\nimport { DriveSectionRouteProps } from '../../sections/Drive/DriveView';\nimport SidebarDevices from './DriveSidebarDevices/SidebarDevices';\nimport DriveSidebarFolders from './DriveSidebarFolders/DriveSidebarFolders';\nimport DriveSidebarListItem from './DriveSidebarListItem';\n\ninterface Props {\n    shareId?: string;\n    userShares: ShareWithKey[];\n}\n\nconst DriveSidebarList = ({ shareId, userShares }: Props) => {\n    const match = useRouteMatch<DriveSectionRouteProps>();\n    const isDevicesSectionEnabled = useDevicesFeatureFlag();\n\n    const [sidebarWidth, setSidebarWidth] = useState('100%');\n    const setSidebarLevel = (level: number) => {\n        const extraWidth = Math.floor(level / 7) * 50;\n        setSidebarWidth(`${100 + extraWidth}%`);\n    };\n\n    return (\n        <SidebarList style={{ width: sidebarWidth, maxWidth: sidebarWidth }}>\n            {userShares.map((userShare) => (\n                <DriveSidebarFolders\n                    key={userShare.shareId}\n                    path={match.url}\n                    shareId={userShare.shareId}\n                    linkId={userShare.rootLinkId}\n                    setSidebarLevel={setSidebarLevel}\n                />\n            ))}\n            {isDevicesSectionEnabled ? <SidebarDevices path={match.url} setSidebarLevel={setSidebarLevel} /> : null}\n            <DriveSidebarListItem\n                to=\"/shared-urls\"\n                icon=\"link\"\n                shareId={shareId}\n                isActive={match.url === '/shared-urls'}\n            >\n                <span className=\"text-ellipsis\" title={c('Link').t`Shared`}>{c('Link').t`Shared`}</span>\n            </DriveSidebarListItem>\n            <DriveSidebarListItem to=\"/trash\" icon=\"trash\" shareId={shareId} isActive={match.url === '/trash'}>\n                <span className=\"text-ellipsis\" title={c('Link').t`Trash`}>{c('Link').t`Trash`}</span>\n            </DriveSidebarListItem>\n        </SidebarList>\n    );\n};\n\nexport default DriveSidebarList;\n","import { FeatureCode } from '@proton/components/containers';\nimport { useFeature } from '@proton/components/hooks';\n\nexport default function useDevicesFeatureFlag() {\n    const flagValue = useFeature(FeatureCode.DriveMyDevices)?.feature?.Value;\n    return flagValue;\n}\n","import { useEffect, useState } from 'react';\nimport * as React from 'react';\n\nimport { Sidebar, SidebarNav } from '@proton/components';\n\nimport useActiveShare from '../../../hooks/drive/useActiveShare';\nimport { ShareWithKey, useDefaultShare } from '../../../store';\nimport DriveSidebarFooter from './DriveSidebarFooter';\nimport DriveSidebarList from './DriveSidebarList';\n\ninterface Props {\n    isHeaderExpanded: boolean;\n    toggleHeaderExpanded: () => void;\n    primary: React.ReactNode;\n    logo: React.ReactNode;\n}\n\nconst DriveSidebar = ({ logo, primary, isHeaderExpanded, toggleHeaderExpanded }: Props) => {\n    const { activeShareId } = useActiveShare();\n    const { getDefaultShare } = useDefaultShare();\n\n    const [defaultShare, setDefaultShare] = useState<ShareWithKey>();\n\n    useEffect(() => {\n        void getDefaultShare().then(setDefaultShare);\n    }, [getDefaultShare]);\n\n    /*\n     * The sidebar supports multiple shares, but as we currently have\n     * only one main share in use, we gonna use the default share only,\n     * unless the opposite is decided.\n     */\n    const shares = defaultShare ? [defaultShare] : [];\n    return (\n        <Sidebar\n            logo={logo}\n            expanded={isHeaderExpanded}\n            onToggleExpand={toggleHeaderExpanded}\n            primary={primary}\n            version={<DriveSidebarFooter />}\n        >\n            <SidebarNav>\n                <DriveSidebarList shareId={activeShareId} userShares={shares} />\n            </SidebarNav>\n        </Sidebar>\n    );\n};\n\nexport default DriveSidebar;\n","import * as React from 'react';\nimport { useState } from 'react';\nimport { useLocation } from 'react-router-dom';\n\nimport { MainLogo, PrivateAppContainer, TopBanners, useToggle } from '@proton/components';\n\nimport AppErrorBoundary from '../AppErrorBoundary';\nimport FileRecoveryBanner from '../ResolveLockedVolumes/LockedVolumesBanner';\nimport UploadSidebarButton from '../sections/Drive/UploadButton';\nimport ShareFileSidebarButton from '../sections/SharedLinks/ShareFileSidebarButton';\nimport EmptyTrashSidebarButton from '../sections/Trash/EmptyTrashSidebarButton';\nimport { DriveHeaderPrivate } from './DriveHeader';\nimport DriveSidebar from './DriveSidebar/DriveSidebar';\n\ninterface Props {\n    children?: JSX.Element | JSX.Element[];\n}\n\nconst DriveWindow = ({ children }: Props) => {\n    const location = useLocation();\n    const { state: expanded, toggle: toggleExpanded } = useToggle();\n\n    const [recoveryBannerVisible, setReoveryBannerVisible] = useState(true);\n\n    const fileRecoveryBanner = recoveryBannerVisible ? (\n        <FileRecoveryBanner\n            onClose={() => {\n                setReoveryBannerVisible(false);\n            }}\n        />\n    ) : null;\n\n    const top = <TopBanners>{fileRecoveryBanner}</TopBanners>;\n\n    let PrimaryButton = UploadSidebarButton;\n    if (location.pathname === '/trash') {\n        PrimaryButton = EmptyTrashSidebarButton;\n    } else if (location.pathname === '/shared-urls') {\n        PrimaryButton = ShareFileSidebarButton;\n    }\n\n    const logo = <MainLogo to=\"/\" />;\n    const header = (\n        <DriveHeaderPrivate\n            logo={logo}\n            floatingPrimary={PrimaryButton && <PrimaryButton mobileVersion />}\n            isHeaderExpanded={expanded}\n            toggleHeaderExpanded={toggleExpanded}\n        />\n    );\n\n    const sidebar = (\n        <DriveSidebar\n            logo={logo}\n            primary={PrimaryButton && <PrimaryButton />}\n            isHeaderExpanded={expanded}\n            toggleHeaderExpanded={toggleExpanded}\n        />\n    );\n\n    return (\n        <PrivateAppContainer top={top} header={header} sidebar={sidebar}>\n            <AppErrorBoundary>{children}</AppErrorBoundary>\n        </PrivateAppContainer>\n    );\n};\n\nexport default DriveWindow;\n","export interface ChecklistApiResponse {\n    Code: number;\n    Items: ChecklistKey[];\n    CreatedAt: number;\n    ExpiresAt: number;\n    UserWasRewarded: boolean;\n    Visible: boolean;\n}\n\nexport type ChecklistId = 'get-started' | 'paying-user';\n\nexport enum ChecklistKey {\n    SendMessage = 'SendMessage',\n    MobileApp = 'MobileApp',\n    RecoveryMethod = 'RecoveryMethod',\n    Import = 'Import',\n    DriveUpload = 'DriveUpload',\n    DriveShare = 'DriveShare',\n}\n","import { useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { ThemeColorUnion } from '@proton/colors';\nimport {\n    FloatingButton,\n    Icon,\n    IconName,\n    Row,\n    Spotlight,\n    classnames,\n    useActiveBreakpoint,\n    useLocalState,\n} from '@proton/components';\nimport { getAppHref } from '@proton/shared/lib/apps/helper';\nimport { getSlugFromApp } from '@proton/shared/lib/apps/slugHelper';\nimport { APPS } from '@proton/shared/lib/constants';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { ChecklistKey } from '@proton/shared/lib/interfaces';\nimport spotlightIcon from '@proton/styles/assets/img/illustrations/spotlight-stars.svg';\n\nimport useActiveShare from '../../hooks/drive/useActiveShare';\nimport { useFileUploadInput } from '../../store';\nimport useOpenModal from '../useOpenModal';\nimport useChecklist from './useChecklist';\n\nexport default function GiftFloatingButton() {\n    const checklist = useChecklist();\n    const { isNarrow } = useActiveBreakpoint();\n\n    if (isNarrow || checklist.isLoading || checklist.expiresInDays === 0 || !checklist.isVisible) {\n        return null;\n    }\n\n    if (checklist.isCompleted) {\n        return <WelcomeActionsDoneSpotlight onSeen={checklist.markCompletedAsSeen} />;\n    }\n\n    return (\n        <WelcomeActionsSpotlight\n            reloadChecklist={checklist.reload}\n            completedActions={checklist.completedActions}\n            expiresInDays={checklist.expiresInDays}\n        />\n    );\n}\n\nfunction WelcomeActionsDoneSpotlight({ onSeen }: { onSeen: (dismiss?: boolean) => void }) {\n    const [show, setShow] = useState(false);\n\n    // Wait a bit so user can see it opening it up (if opened right away,\n    // it might feel as part of the page), and also it allows JS to properly\n    // calculate position of the modal when everything is rendered.\n    useEffect(() => {\n        setTimeout(() => {\n            setShow(true);\n            // Product wants to mark it seen on backend automatically.\n            onSeen(false);\n        }, 1000);\n    }, []);\n\n    const spotlightContent = (\n        <div className=\"flex flex-nowrap\">\n            <figure className=\"flex-item flex-item-noshrink mr1\">\n                <img src={spotlightIcon} />\n            </figure>\n            <div className=\"flex-item\">\n                <h6 className=\"text-semibold\">{c('Title').t`You’ve got 1 GB of storage`}</h6>\n                <div className=\"mb1 color-weak\">{c('Info').t`Way to go, you’ve just doubled your free storage!`}</div>\n            </div>\n        </div>\n    );\n\n    return (\n        <FloatingSpotlight content={spotlightContent} show={show} onClick={onSeen} color=\"success\" icon=\"checkmark\" />\n    );\n}\n\nfunction WelcomeActionsSpotlight({\n    reloadChecklist,\n    completedActions,\n    expiresInDays,\n}: {\n    reloadChecklist: () => void;\n    completedActions: ChecklistKey[];\n    expiresInDays: number;\n}) {\n    const [showPopup, setShowPopup] = useLocalState(true, 'welcome-actions-spotlight');\n    const [showList, setShowList] = useState(false);\n\n    const toggleOpen = () => {\n        setShowPopup(false); // Any click will remove automatic popup.\n        setShowList(!showList);\n        // Load latest progress before opening checklist again os user doesnt\n        // need to reload the whole page.\n        if (!showList) {\n            reloadChecklist();\n        }\n    };\n\n    const spotlightContent = showPopup ? (\n        <div className=\"flex flex-nowrap\">\n            <figure className=\"flex-item flex-item-noshrink mr1\">\n                <img src={spotlightIcon} />\n            </figure>\n            <div className=\"flex-item\">\n                <h6 className=\"text-semibold\">{c('Title').t`Your 500 MB bonus`}</h6>\n                {/* translator: You have X days left to claim your 500 MB welcome bonus and double your storage */}\n                {c('Info').t`You have ${expiresInDays} days left to claim your 500 MB welcome bonus and `}\n                <a href={getKnowledgeBaseUrl('/more-storage-proton-drive')} target=\"_blank\">{c('Info')\n                    .t`double your storage`}</a>\n            </div>\n        </div>\n    ) : (\n        <div>\n            <h6 className=\"text-semibold\">{c('Title').t`Your welcome actions`}</h6>\n            <div className=\"mb1 color-weak\">\n                {c('Info').t`Get to know Proton Drive and earn your 500 MB storage bonus! Take action today.`}\n            </div>\n            <WelcomeActions completedActions={completedActions} onActionDone={toggleOpen} />\n        </div>\n    );\n    return (\n        <FloatingSpotlight\n            content={spotlightContent}\n            hasClose={showPopup}\n            show={showPopup || showList}\n            onClick={toggleOpen}\n            color={showList ? 'weak' : 'norm'}\n            icon={showList ? 'cross' : 'gift'}\n        />\n    );\n}\n\nfunction FloatingSpotlight({\n    content,\n    show,\n    color,\n    icon,\n    hasClose = false,\n    onClick,\n}: {\n    content: React.ReactNode;\n    show: boolean;\n    color: ThemeColorUnion;\n    icon: IconName;\n    hasClose?: boolean;\n    onClick: () => void;\n}) {\n    return (\n        <Spotlight\n            content={content}\n            show={show}\n            originalPlacement=\"top-end\"\n            className=\"max-w-custom upper-layer\"\n            style={{ '--max-width-custom': '25em' }}\n            hasClose={hasClose}\n        >\n            <FloatingButton\n                title={c('Action').t`Your 500 MB bonus`}\n                onClick={onClick}\n                color={color}\n                className=\"w-custom h-custom\"\n                style={{ '--width-custom': '3em', '--height-custom': '3em' }}\n            >\n                <Icon size={24} name={icon} className=\"mauto\" />\n            </FloatingButton>\n        </Spotlight>\n    );\n}\n\nfunction WelcomeActions({\n    completedActions,\n    onActionDone,\n}: {\n    completedActions: ChecklistKey[];\n    onActionDone: () => void;\n}) {\n    const getIconName = (actionName: ChecklistKey, iconName: IconName) => {\n        return completedActions.includes(actionName) ? 'checkmark' : iconName;\n    };\n\n    const { activeFolder } = useActiveShare();\n    const {\n        inputRef: fileInput,\n        handleClick,\n        handleChange: handleFileChange,\n    } = useFileUploadInput(activeFolder.shareId, activeFolder.linkId);\n\n    const { openFileSharing } = useOpenModal();\n\n    return (\n        <>\n            <WelcomeAction icon=\"checkmark\" title={c('Label').t`Create Proton account`} />\n            <input\n                multiple\n                type=\"file\"\n                ref={fileInput}\n                className=\"hidden\"\n                onChange={(e) => {\n                    handleFileChange(e);\n                    onActionDone();\n                }}\n            />\n            <WelcomeAction\n                icon={getIconName(ChecklistKey.DriveUpload, 'arrow-up-line')}\n                title={c('Label').t`Upload your first file`}\n                text={c('Info').t`And access it from anywhere`}\n                action={() => {\n                    handleClick();\n                }}\n            />\n            <WelcomeAction\n                icon={getIconName(ChecklistKey.DriveShare, 'link')}\n                title={c('Label').t`Create a share link`}\n                text={c('Info').t`It’s easy and secure`}\n                action={() => {\n                    openFileSharing(activeFolder.shareId);\n                    onActionDone();\n                }}\n            />\n            <WelcomeAction\n                icon={getIconName(ChecklistKey.RecoveryMethod, 'key-skeleton')}\n                title={c('Label').t`Set recovery method`}\n                text={c('Info').t`Makes your account safer`}\n                action={() => {\n                    const slug = getSlugFromApp(APPS.PROTONDRIVE);\n                    const url = `/${slug}/recovery`;\n                    window.open(getAppHref(url, APPS.PROTONACCOUNT));\n                    onActionDone();\n                }}\n            />\n        </>\n    );\n}\n\nfunction WelcomeAction({\n    icon,\n    title,\n    text,\n    action,\n}: {\n    icon: IconName;\n    title: string;\n    text?: string;\n    action?: () => void;\n}) {\n    const [onHover, setOnHover] = useState(false);\n\n    const isDone = icon === 'checkmark';\n\n    return (\n        <Row\n            className={classnames(['flex flex-align-items-center rounded', !isDone && 'cursor-pointer'])}\n            onClick={isDone ? undefined : action}\n            onMouseEnter={() => setOnHover(true)}\n            onMouseLeave={() => setOnHover(false)}\n        >\n            <div\n                className={classnames([\n                    'flex-item-nowrap h-custom w-custom rounded mr0-5',\n                    'flex flex-justify-center flex-align-items-center',\n                    isDone ? 'bg-success' : 'bg-weak',\n                ])}\n                style={{ '--width-custom': '2.5em', '--height-custom': '2.5em' }}\n            >\n                <Icon name={icon} />\n            </div>\n            <div className={classnames(['flex-item-fluid', isDone && 'text-strike color-weak'])}>\n                {title}\n                {!isDone && text && <div className=\"color-weak\">{text}</div>}\n            </div>\n            {!isDone && (\n                <Icon name={onHover ? 'arrow-right' : 'chevron-right'} className={onHover ? '' : 'color-weak'} />\n            )}\n        </Row>\n    );\n}\n","import React, { ReactNode, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    Checkbox,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    PrimaryButton,\n    Radio,\n    Row,\n} from '@proton/components';\n\nimport { TransferConflictStrategy } from '../../store';\n\nexport interface ConflictModalProps {\n    name: string;\n    isFolder?: boolean;\n    originalIsFolder?: boolean;\n    apply: (strategy: TransferConflictStrategy, all: boolean) => void;\n    cancelAll: () => void;\n    onClose?: () => void;\n    onConfirm?: () => void;\n    title?: string;\n    children?: ReactNode;\n    cancel?: ReactNode;\n    confirm?: ReactNode;\n    loading?: boolean;\n    className?: string;\n    small?: boolean;\n    tiny?: boolean;\n    noTitleEllipsis?: boolean;\n    mode?: 'alert';\n    submitProps?: any;\n    closeProps?: any;\n    open?: boolean;\n}\n\nexport default function ConflictModal({\n    name,\n    isFolder = false,\n    originalIsFolder = false,\n    apply,\n    cancelAll,\n    onClose,\n    open,\n}: ConflictModalProps) {\n    const [strategy, setStrategy] = useState(\n        isFolder ? TransferConflictStrategy.Merge : TransferConflictStrategy.Rename\n    );\n    const [applyAll, setApplyAll] = useState(false);\n\n    const uploadName = (\n        <strong className=\"text-break\" key=\"filename\">\n            {name}\n        </strong>\n    );\n\n    const handleSubmit = (e: React.FormEvent) => {\n        e.preventDefault();\n        apply(strategy, applyAll);\n        onClose?.();\n    };\n\n    const closeAndCancel = () => {\n        onClose?.();\n        cancelAll();\n    };\n\n    return (\n        <ModalTwo as=\"form\" onClose={closeAndCancel} onSubmit={handleSubmit} open={open} size=\"small\">\n            <ModalTwoHeader\n                title={isFolder ? c('Title').t`Duplicate folder found` : c('Title').t`Duplicate file found`}\n            />\n            <ModalTwoContent>\n                <p>\n                    {c('Info').jt`${uploadName} already exists in this location.`}\n                    <br />\n                    {c('Info').t`What do you want to do?`}\n                </p>\n                {originalIsFolder && (\n                    <Row>\n                        <Radio\n                            id={TransferConflictStrategy.Merge}\n                            checked={strategy === TransferConflictStrategy.Merge}\n                            onChange={() => setStrategy(TransferConflictStrategy.Merge)}\n                            name=\"strategy\"\n                            className=\"inline-flex flex-nowrap\"\n                        >\n                            <div>\n                                <strong>{c('Label').t`Merge a folder`}</strong>\n                                <br />\n                                <span className=\"color-weak\">{c('Info')\n                                    .t`Folder contents will merge into a single folder`}</span>\n                            </div>\n                        </Radio>\n                    </Row>\n                )}\n                <Row>\n                    <Radio\n                        id={TransferConflictStrategy.Rename}\n                        checked={strategy === TransferConflictStrategy.Rename}\n                        onChange={() => setStrategy(TransferConflictStrategy.Rename)}\n                        name=\"strategy\"\n                        className=\"inline-flex flex-nowrap\"\n                    >\n                        <div>\n                            <strong>{c('Label').t`Upload anyway`}</strong>\n                            <br />\n                            <span className=\"color-weak\">\n                                {isFolder\n                                    ? c('Info').t`A number will be added to the folder name`\n                                    : c('Info').t`A number will be added to the filename`}\n                            </span>\n                        </div>\n                    </Radio>\n                </Row>\n                <Row>\n                    <Radio\n                        id={TransferConflictStrategy.Replace}\n                        checked={strategy === TransferConflictStrategy.Replace}\n                        onChange={() => setStrategy(TransferConflictStrategy.Replace)}\n                        name=\"strategy\"\n                        className=\"inline-flex flex-nowrap\"\n                    >\n                        <div>\n                            <strong>\n                                {originalIsFolder ? c('Label').t`Replace folder` : c('Label').t`Replace file`}\n                            </strong>\n                            <br />\n                            <span className=\"color-weak\">\n                                {originalIsFolder\n                                    ? c('Info').t`This will overwrite the existing folder`\n                                    : c('Info').t`This will overwrite the existing file`}\n                            </span>\n                        </div>\n                    </Radio>\n                </Row>\n                <Row>\n                    <Radio\n                        id={TransferConflictStrategy.Skip}\n                        checked={strategy === TransferConflictStrategy.Skip}\n                        onChange={() => setStrategy(TransferConflictStrategy.Skip)}\n                        name=\"strategy\"\n                        className=\"inline-flex flex-nowrap\"\n                    >\n                        <div>\n                            <strong>{isFolder ? c('Label').t`Skip folder` : c('Label').t`Skip file`}</strong>\n                            <br />\n                            <span className=\"color-weak\">\n                                {isFolder\n                                    ? c('Info').t`Folder will not be uploaded`\n                                    : c('Info').t`File will not be uploaded`}\n                            </span>\n                        </div>\n                    </Radio>\n                </Row>\n                <hr />\n                <Row>\n                    <Checkbox onChange={() => setApplyAll((value) => !value)}>\n                        {isFolder\n                            ? c('Label').t`Apply to all duplicated folders`\n                            : c('Label').t`Apply to all duplicated files`}\n                    </Checkbox>\n                </Row>\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                <Button type=\"button\" onClick={closeAndCancel}>\n                    {c('Action').t`Cancel all uploads`}\n                </Button>\n                <PrimaryButton type=\"submit\">{c('Action').t`Continue`}</PrimaryButton>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n}\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { Checkbox, FileNameDisplay, Icon, classnames } from '@proton/components';\n\nimport { stopPropagation } from '../../../utils/stopPropagation';\nimport { useCheckbox, useItemContextMenu, useSelection } from '../../FileBrowser';\nimport { DeviceItem } from '../Devices/Devices';\nimport { DriveItem } from '../Drive/Drive';\nimport { SharedLinkItem } from '../SharedLinks/SharedLinks';\nimport { TrashItem } from '../Trash/Trash';\n\nconst GridViewItemBase = ({\n    IconComponent,\n    SignatureIconComponent,\n    item,\n    disableSelection = false,\n}: {\n    IconComponent: React.ReactNode;\n    SignatureIconComponent?: React.ReactNode;\n    item: DriveItem | TrashItem | SharedLinkItem | DeviceItem;\n    disableSelection?: boolean;\n}) => {\n    const selectionControls = useSelection()!;\n    const contextMenuControls = useItemContextMenu();\n    const { handleCheckboxChange, handleCheckboxClick, handleCheckboxWrapperClick } = useCheckbox(item.id);\n\n    const isContextMenuButtonActive = contextMenuControls.isOpen && selectionControls.selectedItemIds.includes(item.id);\n    return (\n        <>\n            <div className=\"flex flex-item-fluid flex-justify-center flex-align-items-center file-browser-grid-item--container\">\n                {IconComponent}\n            </div>\n            <div\n                className={classnames([\n                    'flex file-browser-grid-item--select',\n                    selectionControls?.selectedItemIds.length ? null : 'opacity-on-hover-only-desktop',\n                ])}\n                onTouchStart={stopPropagation}\n                onKeyDown={stopPropagation}\n                onClick={handleCheckboxWrapperClick}\n            >\n                {!disableSelection ? (\n                    <Checkbox\n                        disabled={item.isLocked}\n                        className=\"increase-click-surface file-browser-grid-item-checkbox\"\n                        checked={selectionControls.isSelected(item.id)}\n                        onChange={handleCheckboxChange}\n                        onClick={handleCheckboxClick}\n                    />\n                ) : null}\n            </div>\n            <div className=\"file-browser-grid-item--file-name flex border-top\">\n                {SignatureIconComponent ? SignatureIconComponent : null}\n                <FileNameDisplay text={item.name} className=\"mxauto\" />\n                <Button\n                    shape=\"ghost\"\n                    size=\"small\"\n                    icon\n                    className={classnames([\n                        'file-browser-grid-view--options',\n                        isContextMenuButtonActive ? 'file-browser--options-focus' : 'opacity-on-hover-only-desktop',\n                    ])}\n                    onClick={(e) => {\n                        selectionControls?.selectItem(item.id);\n                        contextMenuControls.handleContextMenu(e);\n                    }}\n                    onTouchEnd={(e) => {\n                        selectionControls?.selectItem(item.id);\n                        contextMenuControls.handleContextMenuTouch?.(e);\n                    }}\n                >\n                    <Icon name=\"three-dots-vertical\" alt={c('Action').t`More options`} />\n                </Button>\n            </div>\n        </>\n    );\n};\n\nexport default GridViewItemBase;\n","import { Icon } from '@proton/components';\n\nimport { DeviceItem } from '../Devices/Devices';\nimport GridViewItemBase from './GridViewItem';\nimport { getDeviceIconText } from './utils';\n\nexport function GridViewItemDevice({ item }: { item: DeviceItem }) {\n    const iconText = getDeviceIconText(item.name);\n\n    return (\n        <GridViewItemBase\n            IconComponent={<Icon name=\"tv\" size={42} alt={iconText}></Icon>}\n            item={item}\n            disableSelection\n        />\n    );\n}\n","import { c } from 'ttag';\n\nimport { Icon, Tooltip } from '@proton/components';\n\ninterface Props {\n    signatureIssues?: any;\n    isFile: boolean;\n    className?: string;\n}\n\nexport default function SignatureIcon({ isFile, signatureIssues, className }: Props) {\n    if (!signatureIssues) {\n        return null;\n    }\n\n    let title = isFile\n        ? c('Title').t`This file has a missing or invalid signature. Go to Menu (⋮) → Details for info.`\n        : c('Title').t`This folder has a missing or invalid signature. Go to Menu (⋮) → Details for info.`;\n\n    return (\n        <Tooltip title={title}>\n            <Icon name=\"lock-exclamation-filled\" className={className} />\n        </Tooltip>\n    );\n}\n","import { useCallback, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { Icon, Tooltip } from '@proton/components';\n\nimport { useActions } from '../../../store';\nimport { BrowserItemId } from '../../FileBrowser/interface';\n\ninterface Props {\n    shareId: string;\n    linkId: BrowserItemId;\n    trashed: number | null;\n    isExpired: boolean;\n    className?: string;\n}\n\nconst CopyLinkIcon = ({ shareId, linkId, trashed, isExpired, className }: Props) => {\n    const [isLoading, setIsLoading] = useState(false);\n    const { copyShareLinkToClipboard } = useActions();\n\n    const handleGetLink = useCallback(\n        (e) => {\n            if (!copyShareLinkToClipboard) {\n                return;\n            }\n\n            setIsLoading(true);\n            e.stopPropagation(); // To not show file preview when clicking (to not trigger other click event).\n            e.preventDefault(); // To not show file preview when pressing enter (to disable click event).\n\n            copyShareLinkToClipboard(new AbortController().signal, shareId, linkId).finally(() => {\n                setIsLoading(false);\n            });\n        },\n        [shareId, linkId]\n    );\n\n    if (!copyShareLinkToClipboard || isExpired || trashed) {\n        return null;\n    }\n\n    return (\n        <Tooltip title={c('Action').t`Copy link`}>\n            <Button\n                loading={isLoading}\n                icon\n                shape=\"ghost\"\n                size=\"small\"\n                className={className}\n                onClick={handleGetLink}\n                onKeyDown={(e) => {\n                    if (e.key === 'Enter' || e.key === ' ') {\n                        handleGetLink(e);\n                    }\n                }}\n            >\n                <Icon name=\"link\" alt={c('Action').t`Copy link`} />\n            </Button>\n        </Tooltip>\n    );\n};\n\nexport default CopyLinkIcon;\n","import { c } from 'ttag';\n\nimport { FileIcon, Icon, TableCell, classnames, useActiveBreakpoint } from '@proton/components';\n\nimport useActiveShare from '../../../hooks/drive/useActiveShare';\nimport { formatAccessCount } from '../../../utils/formatters';\nimport { Cells } from '../../FileBrowser';\nimport SignatureIcon from '../../SignatureIcon';\nimport { DeviceItem } from '../Devices/Devices';\nimport { DriveItem } from '../Drive/Drive';\nimport { SharedLinkItem } from '../SharedLinks/SharedLinks';\nimport { TrashItem } from '../Trash/Trash';\nimport CopyLinkIcon from './CopyLinkIcon';\nimport { getDeviceIconText, getLinkIconText } from './utils';\n\nconst { LocationCell: LocationCellBase, SizeCell: SizeCellBase, NameCell: NameCellBase, TimeCell } = Cells;\n\nexport const NameCell = ({ item }: { item: DriveItem | SharedLinkItem | TrashItem }) => {\n    const iconText = getLinkIconText({\n        linkName: item.name,\n        mimeType: item.mimeType,\n        isFile: item.isFile,\n    });\n\n    return (\n        <TableCell className=\"m0 flex flex-align-items-center flex-nowrap flex-item-fluid\" data-testid=\"column-name\">\n            {item.cachedThumbnailUrl ? (\n                <img\n                    src={item.cachedThumbnailUrl}\n                    alt={iconText}\n                    className=\"file-browser-list-item--thumbnail flex-item-noshrink mr0-5\"\n                />\n            ) : (\n                <FileIcon mimeType={item.isFile ? item.mimeType : 'Folder'} alt={iconText} className=\"mr0-5\" />\n            )}\n            <SignatureIcon\n                signatureIssues={item.signatureIssues}\n                isFile={item.isFile}\n                className=\"mr0-5 flex-item-noshrink\"\n            />\n            <NameCellBase name={item.name} />\n        </TableCell>\n    );\n};\n\nexport const DeviceNameCell = ({ item }: { item: DeviceItem }) => {\n    const iconText = getDeviceIconText(item.name);\n\n    return (\n        <TableCell\n            className=\"m0 flex flex-align-items-center flex-nowrap flex-item-fluid filebrowser-list-device-name-cell\"\n            data-testid=\"column-name\"\n        >\n            <Icon name=\"tv\" alt={iconText} className=\"mr0-5\" />\n            <NameCellBase name={item.name} />\n        </TableCell>\n    );\n};\n\nexport const ModifiedCell = ({ item }: { item: DriveItem }) => {\n    return (\n        <TableCell className=\"m0 w15\" data-testid=\"column-modified\">\n            <TimeCell time={item.fileModifyTime} />\n        </TableCell>\n    );\n};\n\nexport const ModifiedCellDevice = ({ item }: { item: DeviceItem }) => {\n    return (\n        <TableCell className=\"m0 w15\" data-testid=\"column-modified\">\n            <TimeCell time={item.modificationTime} />\n        </TableCell>\n    );\n};\n\nexport function SizeCell({ item }: { item: DriveItem | TrashItem }) {\n    const { isDesktop } = useActiveBreakpoint();\n    return (\n        <TableCell className={classnames(['m0', isDesktop ? 'w10' : 'w15'])} data-testid=\"column-size\">\n            {item.isFile ? <SizeCellBase size={item.size} /> : '-'}\n        </TableCell>\n    );\n}\n\nexport const DeletedCell = ({ item }: { item: TrashItem }) => {\n    return (\n        <TableCell className=\"m0 w25\" data-testid=\"column-trashed\">\n            <TimeCell time={item.trashed || item.fileModifyTime} />\n        </TableCell>\n    );\n};\n\nexport const CreatedCell = ({ item }: { item: TrashItem }) => {\n    return (\n        <TableCell className=\"m0 w15\" data-testid=\"column-share-created\">\n            {item.shareUrl?.createTime && <TimeCell time={item.shareUrl.createTime} />}\n        </TableCell>\n    );\n};\n\nexport const LocationCell = ({ item }: { item: TrashItem }) => {\n    const { isDesktop } = useActiveBreakpoint();\n    const { activeShareId } = useActiveShare();\n    return (\n        <TableCell className={classnames(['m0', isDesktop ? 'w20' : 'w25'])} data-testid=\"column-location\">\n            <LocationCellBase shareId={activeShareId} parentLinkId={item.parentLinkId} />\n        </TableCell>\n    );\n};\n\nexport const AccessCountCell = ({ item }: { item: TrashItem }) => {\n    return (\n        <TableCell className=\"m0 w15\" data-testid=\"column-num-accesses\">\n            {formatAccessCount(item.shareUrl?.numAccesses)}\n        </TableCell>\n    );\n};\n\nexport const ExpirationCell = ({ item }: { item: TrashItem }) => {\n    const { isDesktop } = useActiveBreakpoint();\n\n    const expiredPart = isDesktop ? (\n        <span className=\"ml0-25\">{c('Label').t`(Expired)`}</span>\n    ) : (\n        <span>{c('Label').t`Expired`}</span>\n    );\n\n    let expiration;\n    if (item.shareUrl) {\n        expiration = item.shareUrl.expireTime ? (\n            <div className=\"flex flex-nowrap\">\n                {(isDesktop || !item.shareUrl.isExpired) && <TimeCell time={item.shareUrl.expireTime} />}\n                {item.shareUrl.isExpired ? expiredPart : null}\n            </div>\n        ) : (\n            c('Label').t`Never`\n        );\n    }\n\n    return (\n        <TableCell className=\"m0 w20\" data-testid=\"column-share-expires\">\n            {expiration}\n        </TableCell>\n    );\n};\n\nexport const ShareOptionsCell = ({ item }: { item: DriveItem }) => {\n    const { activeShareId } = useActiveShare();\n\n    return (\n        <TableCell\n            className=\"m0 file-browser-list--icon-column flex flex-align-items-center\"\n            data-testid=\"column-share-options\"\n        >\n            {item.shareUrl ? (\n                <CopyLinkIcon\n                    shareId={activeShareId}\n                    linkId={item.id}\n                    isExpired={Boolean(item.shareUrl?.isExpired)}\n                    trashed={item.trashed}\n                />\n            ) : null}\n        </TableCell>\n    );\n};\n","import { c } from 'ttag';\n\nimport { HeaderCellsPresets } from '../../FileBrowser/interface';\n\nexport const checkbox = {\n    type: HeaderCellsPresets.Checkbox,\n};\n\nexport const name = {\n    type: 'name',\n    getText: () => c('Label').t`Name`,\n    sorting: true,\n};\n\nexport const location = {\n    type: 'location',\n    getText: () => c('Label').t`Location`,\n    props: {\n        className: 'w20',\n    },\n};\n\nexport const trashed = {\n    type: 'trashed',\n    getText: () => c('Label').t`Deleted`,\n    props: {\n        className: 'w25',\n    },\n    sorting: true,\n};\n\nexport const size = {\n    type: 'size',\n    getText: () => c('Label').t`Size`,\n    props: {\n        className: 'w10',\n    },\n    sorting: true,\n};\n\nexport const modificationDate = {\n    type: 'fileModifyTime',\n    getText: () => c('Label').t`Modified`,\n    props: {\n        className: 'w15',\n    },\n    sorting: true,\n};\n\nexport const creationDate = {\n    type: 'linkCreateTime',\n    getText: () => c('Label').t`Created`,\n    props: {\n        className: 'w15',\n    },\n    sorting: true,\n};\n\nexport const accessCount = {\n    type: 'numAccesses',\n    getText: () => c('Label').t`# of accesses`,\n    props: {\n        className: 'w15',\n    },\n    sorting: true,\n};\n\nexport const expirationDate = {\n    type: 'linkExpireTime',\n    getText: () => c('Label').t`Expires`,\n    props: {\n        className: 'w20',\n    },\n    sorting: true,\n};\n\nexport const placeholder = {\n    type: HeaderCellsPresets.Placeholder,\n};\n\nexport default {\n    checkbox,\n    location,\n    modificationDate,\n    name,\n    placeholder,\n    size,\n    trashed,\n    creationDate,\n    expirationDate,\n    accessCount,\n};\n","import { ReactNode, RefObject, useEffect, useState } from 'react';\n\nimport { generateUID } from '../../helpers';\nimport { Dropdown } from '../dropdown';\nimport { PopperPosition, cornerPopperPlacements } from '../popper';\n\nexport interface ContextMenuProps {\n    anchorRef: RefObject<HTMLElement>;\n    isOpen: boolean;\n    children: ReactNode;\n    position?: PopperPosition;\n    close: () => void;\n    autoClose?: boolean;\n    noMaxHeight?: boolean;\n}\n\nconst ContextMenu = ({\n    anchorRef,\n    children,\n    isOpen,\n    position,\n    close,\n    autoClose = true,\n    noMaxHeight = false,\n}: ContextMenuProps) => {\n    const [uid] = useState(generateUID('context-menu'));\n\n    useEffect(() => {\n        if (!isOpen) {\n            return;\n        }\n\n        const handleContextMenu = () => {\n            if (autoClose) {\n                close();\n            }\n        };\n\n        document.addEventListener('contextmenu', handleContextMenu, { capture: true });\n\n        return () => {\n            document.removeEventListener('contextmenu', handleContextMenu, { capture: true });\n        };\n    }, [isOpen, autoClose, close]);\n\n    return (\n        <Dropdown\n            id={uid}\n            isOpen={isOpen}\n            anchorRef={anchorRef}\n            anchorPosition={position}\n            availablePlacements={cornerPopperPlacements}\n            noCaret\n            autoCloseOutsideAnchor={false}\n            originalPlacement=\"bottom-start\"\n            offset={1}\n            onClose={close}\n            onContextMenu={(e) => e.stopPropagation()}\n            noMaxHeight={noMaxHeight}\n        >\n            {children}\n        </Dropdown>\n    );\n};\n\nexport default ContextMenu;\n","import { useEffect } from 'react';\n\nimport { ContextMenu } from '@proton/components';\n\nimport { ContextMenuProps } from '../../FileBrowser/interface';\n\nexport function ItemContextMenu({ anchorRef, isOpen, position, open, close, children }: ContextMenuProps) {\n    useEffect(() => {\n        if (position) {\n            /*\n                close event doesn't fire on mobile when clicking on another context menu target.\n                unless menu is manually closed, it retains its position\n            */\n            if (isOpen) {\n                close();\n            }\n            open();\n        }\n    }, [position?.left, position?.top]);\n\n    return (\n        <ContextMenu isOpen={isOpen} close={close} position={position} noMaxHeight anchorRef={anchorRef}>\n            {children}\n        </ContextMenu>\n    );\n}\n","import { DropdownMenuButton, Icon, IconName } from '@proton/components';\n\ninterface Props {\n    name: string;\n    icon: IconName;\n    testId: string;\n    action: () => void;\n    close: () => void;\n}\n\nconst ContextMenuButton = ({ name, icon, testId, action, close }: Props) => {\n    return (\n        <DropdownMenuButton\n            key={name}\n            onContextMenu={(e) => e.stopPropagation()}\n            className=\"flex flex-align-items-center flex-nowrap text-left\"\n            onClick={(e) => {\n                e.stopPropagation();\n                action();\n                close();\n            }}\n            data-testid={testId}\n        >\n            <Icon className=\"mr0-5\" name={icon} />\n            {name}\n        </DropdownMenuButton>\n    );\n};\n\nexport default ContextMenuButton;\n","import { c } from 'ttag';\n\nimport { DecryptedLink } from '../../../../store';\nimport useOpenModal from '../../../useOpenModal';\nimport ContextMenuButton from '../ContextMenuButton';\n\ninterface Props {\n    selectedLinks: DecryptedLink[];\n    close: () => void;\n}\n\nconst DetailsButton = ({ selectedLinks, close }: Props) => {\n    const { openDetails, openFilesDetails } = useOpenModal();\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Details`}\n            icon=\"info-circle\"\n            testId=\"context-menu-details\"\n            action={() => {\n                if (selectedLinks.length === 1) {\n                    openDetails(selectedLinks[0].rootShareId, selectedLinks[0].linkId);\n                } else if (selectedLinks.length > 1) {\n                    openFilesDetails(selectedLinks);\n                }\n            }}\n            close={close}\n        />\n    );\n};\n\nexport default DetailsButton;\n","import { c } from 'ttag';\n\nimport { DecryptedLink, useDownload } from '../../../../store';\nimport ContextMenuButton from '../ContextMenuButton';\n\ninterface Props {\n    shareId: string;\n    selectedLinks: DecryptedLink[];\n    close: () => void;\n}\n\nconst DownloadButton = ({ shareId, selectedLinks, close }: Props) => {\n    const { download } = useDownload();\n\n    const onClick = () => {\n        void download(\n            selectedLinks.map((link) => ({\n                ...link,\n                shareId,\n            }))\n        );\n    };\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Download`}\n            icon=\"arrow-down-line\"\n            testId=\"context-menu-download\"\n            action={onClick}\n            close={close}\n        />\n    );\n};\n\nexport default DownloadButton;\n","import { c } from 'ttag';\n\nimport { useActions } from '../../../../store';\nimport ContextMenuButton from '../ContextMenuButton';\n\ninterface Props {\n    shareId: string;\n    linkId: string;\n    close: () => void;\n}\n\nconst CopyLinkButton = ({ shareId, linkId, close }: Props) => {\n    const { copyShareLinkToClipboard } = useActions();\n\n    if (!copyShareLinkToClipboard) {\n        return null;\n    }\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Copy link`}\n            icon=\"link\"\n            testId=\"context-menu-share-link\"\n            action={() => copyShareLinkToClipboard(new AbortController().signal, shareId, linkId)}\n            close={close}\n        />\n    );\n};\n\nexport default CopyLinkButton;\n","import { c } from 'ttag';\n\nimport useOpenModal from '../../../useOpenModal';\nimport ContextMenuButton from '../ContextMenuButton';\n\ninterface Props {\n    shareId: string;\n    linkId: string;\n    close: () => void;\n}\n\nconst PreviewButton = ({ shareId, linkId, close }: Props) => {\n    const { openPreview } = useOpenModal();\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Preview`}\n            icon=\"eye\"\n            testId=\"context-menu-preview\"\n            action={() => openPreview(shareId, linkId)}\n            close={close}\n        />\n    );\n};\n\nexport default PreviewButton;\n","import { c } from 'ttag';\n\nimport { DecryptedLink } from '../../../../store';\nimport useOpenModal from '../../../useOpenModal';\nimport ContextMenuButton from '../ContextMenuButton';\n\ninterface Props {\n    shareId: string;\n    link: DecryptedLink;\n    close: () => void;\n}\n\nconst RenameButton = ({ shareId, link, close }: Props) => {\n    const { openRename } = useOpenModal();\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Rename`}\n            icon=\"pen-square\"\n            testId=\"context-menu-rename\"\n            action={() => openRename(shareId, link)}\n            close={close}\n        />\n    );\n};\n\nexport default RenameButton;\n","import { c } from 'ttag';\n\nimport useOpenModal from '../../../useOpenModal';\nimport ContextMenuButton from '../ContextMenuButton';\n\ninterface Props {\n    shareId: string;\n    close: () => void;\n}\n\nconst ShareFileButton = ({ shareId, close }: Props) => {\n    const { openFileSharing } = useOpenModal();\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Get link`}\n            icon=\"link\"\n            testId=\"context-menu-shareViaLink\"\n            action={() => openFileSharing(shareId)}\n            close={close}\n        />\n    );\n};\n\nexport default ShareFileButton;\n","import { c } from 'ttag';\n\nimport { DecryptedLink } from '../../../../store';\nimport useOpenModal from '../../../useOpenModal';\nimport ContextMenuButton from '../ContextMenuButton';\n\ninterface Props {\n    shareId: string;\n    link: DecryptedLink;\n    close: () => void;\n}\n\nconst ShareLinkButton = ({ shareId, link, close }: Props) => {\n    const { openLinkSharing } = useOpenModal();\n\n    const hasSharedLink = !!link.shareUrl;\n\n    return (\n        <ContextMenuButton\n            name={hasSharedLink ? c('Action').t`Manage link` : c('Action').t`Get link`}\n            icon={hasSharedLink ? 'link-pen' : 'link'}\n            testId=\"context-menu-share-link\"\n            action={() => openLinkSharing(shareId, link.linkId)}\n            close={close}\n        />\n    );\n};\n\nexport default ShareLinkButton;\n","import { c } from 'ttag';\n\nimport { Device } from '../../../../../store';\nimport useOpenModal from '../../../../useOpenModal';\nimport { ContextMenuButton } from '../../../ContextMenu';\n\ninterface Props {\n    close: () => void;\n    selectedDevices: Device[];\n}\n\nconst RenameButton = ({ close, selectedDevices }: Props) => {\n    const { openRenameDevice } = useOpenModal();\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Rename`}\n            icon=\"pen-square\"\n            testId=\"context-menu-rename\"\n            action={() => openRenameDevice(selectedDevices[0])}\n            close={close}\n        />\n    );\n};\n\nexport default RenameButton;\n","import { c } from 'ttag';\n\nimport { Device } from '../../../../../store';\nimport useOpenModal from '../../../../useOpenModal';\nimport { ContextMenuButton } from '../../../ContextMenu';\n\ninterface Props {\n    selectedDevices: Device[];\n    close: () => void;\n}\n\nconst RemoveButton = ({ selectedDevices, close }: Props) => {\n    const { openRemoveDevice } = useOpenModal();\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Remove`}\n            icon=\"trash\"\n            testId=\"context-menu-rename\"\n            action={() => openRemoveDevice(selectedDevices[0])}\n            close={close}\n        />\n    );\n};\n\nexport default RemoveButton;\n","import { Device } from '../../../../store';\nimport { ContextMenuProps } from '../../../FileBrowser/interface';\nimport { ItemContextMenu } from '../../ContextMenu/ItemContextMenu';\nimport { RemoveButton, RenameButton } from './buttons';\n\nexport function DevicesItemContextMenu({\n    selectedDevices,\n    anchorRef,\n    isOpen,\n    position,\n    open,\n    close,\n}: ContextMenuProps & {\n    selectedDevices: Device[];\n}) {\n    const isOnlyOneItem = selectedDevices.length === 1;\n\n    if (!isOnlyOneItem) {\n        return null;\n    }\n\n    return (\n        <ItemContextMenu isOpen={isOpen} open={open} close={close} position={position} anchorRef={anchorRef}>\n            <RenameButton selectedDevices={selectedDevices} close={close} />\n            <RemoveButton selectedDevices={selectedDevices} close={close} />\n        </ItemContextMenu>\n    );\n}\n","import React, { ComponentPropsWithRef, ReactNode } from 'react';\n\ninterface Props {\n    imageProps?: ComponentPropsWithRef<'img'>;\n    children: ReactNode;\n    containerProps?: ComponentPropsWithRef<'div'>;\n}\n\nconst EmptyViewContainer = ({ imageProps, children, ...containerProps }: Props) => {\n    return (\n        <div className=\"mauto p1\" {...containerProps}>\n            <figure className=\"flex-item-fluid text-center p3\">\n                {imageProps && <img className=\"hauto\" {...imageProps} alt={imageProps.alt || ''} />}\n                <figcaption className=\"mt2\">{children}</figcaption>\n            </figure>\n        </div>\n    );\n};\n\nexport default EmptyViewContainer;\n","import { c } from 'ttag';\n\nimport { EmptyViewContainer } from '@proton/components';\nimport noContentSvg from '@proton/styles/assets/img/illustrations/empty-devices.svg';\n\nimport './EmptyDevices.scss';\n\nconst EmptyDevices = () => {\n    const LearnMore = (\n        <a href={''} target=\"_blank\" key=\"learn-more-link\">\n            {c('Action').t`Learn more`}\n        </a>\n    );\n\n    return (\n        <EmptyViewContainer imageProps={{ src: noContentSvg, title: c('Info').t`No synced devices` }}>\n            <h3 className=\"text-bold\">{c('Info').t`No synced devices`}</h3>\n            <p className=\"empty-devices-placeholder-info\">\n                {c('Info')\n                    .jt`Use Drive for Desktop to sync folders on your computer with Proton Drive. They’ll show up here and be accessible from anywhere.  ${LearnMore}`}\n            </p>\n        </EmptyViewContainer>\n    );\n};\n\nexport default EmptyDevices;\n","import { HTMLAttributes, ReactNode } from 'react';\n\nimport { classnames } from '../../helpers';\n\ninterface Props extends HTMLAttributes<HTMLDivElement> {\n    children?: ReactNode;\n    className?: string;\n}\n\nconst Toolbar = ({ children, className, ...rest }: Props) => (\n    <div\n        className={classnames(['toolbar flex flex-nowrap no-scroll flex-item-noshrink no-print', className])}\n        {...rest}\n    >\n        <div className=\"flex toolbar-inner w100\">{children}</div>\n    </div>\n);\n\nexport default Toolbar;\n","import { ButtonHTMLAttributes, ReactElement, ReactNode, Ref, cloneElement, forwardRef } from 'react';\n\nimport noop from '@proton/utils/noop';\n\nimport { classnames } from '../../helpers';\nimport { Tooltip } from '../tooltip';\n\ninterface Props extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'title'> {\n    icon?: ReactElement;\n    children?: ReactNode;\n    title?: ReactNode;\n}\n\nconst ToolbarButton = (\n    { icon, children, className, disabled, tabIndex, title, onClick, ...rest }: Props,\n    ref: Ref<HTMLButtonElement>\n) => {\n    const content = (\n        <button\n            type=\"button\"\n            className={classnames([className, 'flex flex-item-noshrink toolbar-button'])}\n            onClick={disabled ? noop : onClick}\n            tabIndex={disabled ? -1 : tabIndex}\n            disabled={disabled}\n            ref={ref}\n            {...rest}\n        >\n            {icon &&\n                cloneElement(icon, {\n                    className: classnames([icon.props.className, 'toolbar-icon mauto']),\n                })}\n            {children}\n        </button>\n    );\n\n    if (title) {\n        return <Tooltip title={title}>{content}</Tooltip>;\n    }\n\n    return content;\n};\n\nexport default forwardRef<HTMLButtonElement, Props>(ToolbarButton);\n","export function noSelection(selectedItems: any[]): boolean {\n    return selectedItems.length === 0;\n}\n\nexport function isMultiSelect(selectedItems: any[]): boolean {\n    return selectedItems.length > 1;\n}\n\nexport function hasFoldersSelected(selectedItems: { isFile: boolean }[]): boolean {\n    return selectedItems.some((item) => !item.isFile);\n}\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport { DecryptedLink } from '../../../store';\nimport useOpenModal from '../../useOpenModal';\nimport { noSelection } from './utils';\n\ninterface Props {\n    selectedLinks: DecryptedLink[];\n}\n\nconst DetailsButton = ({ selectedLinks }: Props) => {\n    const { openDetails, openFilesDetails } = useOpenModal();\n\n    if (noSelection(selectedLinks)) {\n        return null;\n    }\n\n    return (\n        <ToolbarButton\n            title={c('Action').t`Details`}\n            icon={<Icon name=\"info-circle\" />}\n            onClick={() => {\n                if (selectedLinks.length === 1) {\n                    openDetails(selectedLinks[0].rootShareId, selectedLinks[0].linkId);\n                } else if (selectedLinks.length > 1) {\n                    openFilesDetails(selectedLinks);\n                }\n            }}\n            data-testid=\"toolbar-details\"\n        />\n    );\n};\n\nexport default DetailsButton;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport { DecryptedLink, useDownload } from '../../../store';\nimport { hasFoldersSelected, noSelection } from './utils';\n\ninterface Props {\n    selectedLinks: DecryptedLink[];\n    disabledFolders?: boolean;\n}\n\nconst DownloadButton = ({ selectedLinks, disabledFolders }: Props) => {\n    const { download } = useDownload();\n\n    const onClick = () => {\n        void download(\n            selectedLinks.map((link) => ({\n                ...link,\n                shareId: link.rootShareId,\n            }))\n        );\n    };\n\n    if (noSelection(selectedLinks) || (disabledFolders && hasFoldersSelected(selectedLinks))) {\n        return null;\n    }\n\n    return (\n        <ToolbarButton\n            title={c('Action').t`Download`}\n            icon={<Icon name=\"arrow-down-line\" />}\n            onClick={onClick}\n            data-testid=\"toolbar-download\"\n        />\n    );\n};\n\nexport default DownloadButton;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton, useNotifications } from '@proton/components';\nimport { LayoutSetting } from '@proton/shared/lib/interfaces/drive/userSettings';\n\nimport { useUserSettings } from '../../../store';\n\nconst LayoutButton = () => {\n    const { createNotification } = useNotifications();\n    const { layout, changeLayout } = useUserSettings();\n\n    const handleClick = (e: any) => {\n        void changeLayout(layout === LayoutSetting.Grid ? LayoutSetting.List : LayoutSetting.Grid);\n\n        // Show notification after ten clicks.\n        if (e.detail === 10) {\n            createNotification({\n                type: 'info',\n                text: 'To list, or not to grid',\n            });\n        }\n    };\n\n    return (\n        <ToolbarButton\n            onClick={handleClick}\n            icon={<Icon name={layout === LayoutSetting.Grid ? 'list-bullets' : 'grid-2'} />}\n            data-testid=\"toolbar-layout\"\n            title={c('Title').t`Change layout`}\n        />\n    );\n};\n\nexport default LayoutButton;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\nimport { isPreviewAvailable } from '@proton/shared/lib/helpers/preview';\n\nimport { DecryptedLink } from '../../../store';\nimport useOpenModal from '../../useOpenModal';\nimport { hasFoldersSelected, isMultiSelect } from './utils';\n\ninterface Props {\n    selectedLinks: DecryptedLink[];\n}\n\nconst PreviewButton = ({ selectedLinks }: Props) => {\n    const { openPreview } = useOpenModal();\n\n    const disabled =\n        isMultiSelect(selectedLinks) ||\n        hasFoldersSelected(selectedLinks) ||\n        !selectedLinks[0]?.mimeType ||\n        !isPreviewAvailable(selectedLinks[0].mimeType, selectedLinks[0].size);\n    if (disabled) {\n        return null;\n    }\n\n    return (\n        <ToolbarButton\n            title={c('Action').t`Preview`}\n            icon={<Icon name=\"eye\" />}\n            onClick={() => {\n                if (selectedLinks.length) {\n                    openPreview(selectedLinks[0].rootShareId, selectedLinks[0].linkId);\n                }\n            }}\n            data-testid=\"toolbar-preview\"\n        />\n    );\n};\n\nexport default PreviewButton;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport { DecryptedLink } from '../../../store';\nimport useOpenModal from '../../useOpenModal';\nimport { isMultiSelect, noSelection } from './utils';\n\ninterface Props {\n    selectedLinks: DecryptedLink[];\n}\n\nconst RenameButton = ({ selectedLinks }: Props) => {\n    const { openRename } = useOpenModal();\n\n    if (noSelection(selectedLinks) || isMultiSelect(selectedLinks)) {\n        return null;\n    }\n\n    return (\n        <ToolbarButton\n            title={c('Action').t`Rename`}\n            icon={<Icon name=\"pen-square\" />}\n            onClick={() => openRename(selectedLinks[0].rootShareId, selectedLinks[0])}\n            data-testid=\"toolbar-rename\"\n        />\n    );\n};\n\nexport default RenameButton;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport useOpenModal from '../../useOpenModal';\n\ninterface Props {\n    shareId: string;\n}\n\nconst ShareFileButton = ({ shareId }: Props) => {\n    const { openFileSharing } = useOpenModal();\n\n    return (\n        <ToolbarButton\n            title={c('Action').t`Get link`}\n            icon={<Icon name=\"link\" />}\n            onClick={() => {\n                openFileSharing(shareId);\n            }}\n            data-testid=\"toolbar-shareViaLink\"\n        />\n    );\n};\n\nexport default ShareFileButton;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport { DecryptedLink } from '../../../store';\nimport useOpenModal from '../../useOpenModal';\nimport { isMultiSelect, noSelection } from './utils';\n\ninterface Props {\n    selectedLinks: DecryptedLink[];\n}\n\nconst ShareLinkButton = ({ selectedLinks }: Props) => {\n    const { openLinkSharing } = useOpenModal();\n\n    if (noSelection(selectedLinks) || isMultiSelect(selectedLinks)) {\n        return null;\n    }\n\n    const hasSharedLink = !!selectedLinks[0]?.shareUrl;\n\n    return (\n        <ToolbarButton\n            disabled={noSelection(selectedLinks) || isMultiSelect(selectedLinks)}\n            title={hasSharedLink ? c('Action').t`Manage link` : c('Action').t`Get link`}\n            icon={<Icon name={hasSharedLink ? 'link-pen' : 'link'} />}\n            onClick={() => openLinkSharing(selectedLinks[0].rootShareId, selectedLinks[0].linkId)}\n            data-testid=\"toolbar-share-link\"\n        />\n    );\n};\n\nexport default ShareLinkButton;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport { Device } from '../../../../../store';\nimport useOpenModal from '../../../../useOpenModal';\nimport { isMultiSelect } from '../../../ToolbarButtons/utils';\n\ninterface Props {\n    selectedDevices: Device[];\n}\n\nconst Remove = ({ selectedDevices }: Props) => {\n    const { openRemoveDevice } = useOpenModal();\n\n    const isDisabled = isMultiSelect(selectedDevices);\n\n    if (isDisabled) {\n        return null;\n    }\n\n    return (\n        <ToolbarButton\n            title={c('Action').t`Remove device`}\n            icon={<Icon name=\"trash\" />}\n            onClick={() => openRemoveDevice(selectedDevices[0])}\n            data-testid=\"toolbar-delete\"\n        />\n    );\n};\n\nexport default Remove;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport { Device } from '../../../../../store';\nimport useOpenModal from '../../../../useOpenModal';\nimport { isMultiSelect } from '../../../ToolbarButtons/utils';\n\ninterface Props {\n    selectedDevices: Device[];\n}\n\nconst RenameButton = ({ selectedDevices }: Props) => {\n    const { openRenameDevice } = useOpenModal();\n\n    const isDisabled = isMultiSelect(selectedDevices);\n\n    if (isDisabled) {\n        return null;\n    }\n\n    return (\n        <ToolbarButton\n            title={c('Action').t`Rename`}\n            icon={<Icon name=\"pen-square\" />}\n            onClick={() => openRenameDevice(selectedDevices[0])}\n            data-testid=\"toolbar-rename\"\n        />\n    );\n};\n\nexport default RenameButton;\n","import { useMemo } from 'react';\n\nimport { Toolbar } from '@proton/components';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { Device } from '../../../../store';\nimport { useSelection } from '../../../FileBrowser';\nimport { LayoutButton } from '../../ToolbarButtons';\nimport { RemoveButton, RenameButton } from './buttons';\n\ninterface Props {\n    items: Device[];\n}\n\nexport const getSelectedItems = (items: Device[], selectedItemIds: string[]): Device[] => {\n    if (items) {\n        return selectedItemIds.map((selectedItemId) => items.find(({ id }) => selectedItemId === id)).filter(isTruthy);\n    }\n\n    return [];\n};\n\nconst DevicesToolbar = ({ items }: Props) => {\n    const selectionControls = useSelection()!;\n\n    const selectedItems = useMemo(\n        () => getSelectedItems(items, selectionControls!.selectedItemIds),\n        [items, selectionControls!.selectedItemIds]\n    );\n\n    const renderSelectionActions = () => {\n        if (!selectedItems.length) {\n            return null;\n        }\n\n        return (\n            <>\n                <RenameButton selectedDevices={selectedItems} />\n                <RemoveButton selectedDevices={selectedItems} />\n            </>\n        );\n    };\n    return (\n        <Toolbar>\n            {renderSelectionActions()}\n            <span className=\"mlauto flex flex-nowrap\">\n                <LayoutButton />\n            </span>\n        </Toolbar>\n    );\n};\n\nexport default DevicesToolbar;\n","import { c } from 'ttag';\n\nexport const name = {\n    type: 'name',\n    getText: () => c('Label').t`Name`,\n    props: {\n        className: 'filebrowser-list-header-name-cell',\n    },\n};\n\nexport const modificationTimeDevice = {\n    type: 'modificationTime',\n    getText: () => c('Label').t`Modified`,\n    props: {\n        className: 'w15',\n    },\n};\n\nexport default {\n    name,\n    modificationTimeDevice,\n};\n","import { useCallback, useMemo, useRef } from 'react';\n\nimport { c } from 'ttag';\n\nimport { useActiveBreakpoint } from '@proton/components';\n\nimport useNavigate from '../../../hooks/drive/useNavigate';\nimport { useDevicesView } from '../../../store';\nimport FileBrowser, { Cells, useItemContextMenu, useSelection } from '../../FileBrowser';\nimport { BrowserItemId, FileBrowserBaseItem, ListViewHeaderItem } from '../../FileBrowser/interface';\nimport { GridViewItemDevice } from '../FileBrowser/GridViewItemDevice';\nimport { DeviceNameCell, ModifiedCellDevice } from '../FileBrowser/contentCells';\nimport headerCellsCommon from '../FileBrowser/headerCells';\nimport { DevicesItemContextMenu } from './ContextMenu/DevicesContextMenu';\nimport EmptyDevices from './EmptyDevices';\nimport { getSelectedItems } from './Toolbar/DevicesToolbar';\nimport headerCells from './headerCells';\n\nexport interface DeviceItem extends FileBrowserBaseItem {\n    modificationTime: number;\n    name: string;\n}\ninterface Props {\n    view: ReturnType<typeof useDevicesView>;\n}\n\nconst { ContextMenuCell } = Cells;\n\nconst desktopCells: React.FC<{ item: DeviceItem }>[] = [DeviceNameCell, ModifiedCellDevice, ContextMenuCell];\nconst mobileCells = [DeviceNameCell, ContextMenuCell];\n\nconst headerItemsDesktop: ListViewHeaderItem[] = [\n    headerCells.name,\n    headerCells.modificationTimeDevice,\n    headerCellsCommon.placeholder,\n];\n\nconst headeItemsMobile: ListViewHeaderItem[] = [headerCells.name, headerCellsCommon.placeholder];\n\nfunction Devices({ view }: Props) {\n    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);\n\n    const { navigateToLink } = useNavigate();\n    const browserItemContextMenu = useItemContextMenu();\n    const selectionControls = useSelection();\n    const { isDesktop } = useActiveBreakpoint();\n\n    const { layout, items: browserItems, isLoading } = view;\n\n    const selectedItems = useMemo(\n        () => getSelectedItems(browserItems, selectionControls!.selectedItemIds),\n        [browserItems, selectionControls!.selectedItemIds]\n    );\n\n    const handleClick = useCallback(\n        (id: BrowserItemId) => {\n            const item = browserItems.find((item) => item.id === id);\n\n            if (!item) {\n                return;\n            }\n            document.getSelection()?.removeAllRanges();\n            navigateToLink(item.shareId, item.linkId, false);\n        },\n        [navigateToLink, browserItems]\n    );\n\n    /* eslint-disable react/display-name */\n    const GridHeaderComponent = useMemo(\n        () => () => {\n            return null;\n        },\n        [isLoading]\n    );\n\n    if (!browserItems.length && !isLoading) {\n        return <EmptyDevices />;\n    }\n\n    const Cells = isDesktop ? desktopCells : mobileCells;\n    const headerItems = isDesktop ? headerItemsDesktop : headeItemsMobile;\n\n    return (\n        <>\n            <DevicesItemContextMenu\n                selectedDevices={selectedItems}\n                anchorRef={contextMenuAnchorRef}\n                close={browserItemContextMenu.close}\n                isOpen={browserItemContextMenu.isOpen}\n                open={browserItemContextMenu.open}\n                position={browserItemContextMenu.position}\n            />\n            <FileBrowser\n                caption={c('Title').t`Synced devices`}\n                items={browserItems}\n                headerItems={headerItems}\n                layout={layout}\n                loading={isLoading}\n                Cells={Cells}\n                GridHeaderComponent={GridHeaderComponent}\n                GridViewItem={GridViewItemDevice}\n                onItemOpen={handleClick}\n                contextMenuAnchorRef={contextMenuAnchorRef}\n                onItemContextMenu={browserItemContextMenu.handleContextMenu}\n            />\n        </>\n    );\n}\n\nexport default Devices;\n","import { c } from 'ttag';\n\nimport { PrivateMainArea, useAppTitle } from '@proton/components';\n\nimport { useDevicesView } from '../../../store';\nimport { FileBrowserStateProvider } from '../../FileBrowser';\nimport Devices from './Devices';\nimport DevicesToolbar from './Toolbar/DevicesToolbar';\n\nfunction DevicesView() {\n    useAppTitle(c('Title').t`Synced devices`);\n\n    const driveView = useDevicesView();\n\n    return (\n        <FileBrowserStateProvider itemIds={driveView.items.map(({ id }) => id)}>\n            <DevicesToolbar items={driveView.items} />\n            <PrivateMainArea hasToolbar className=\"flex-no-min-children flex-column flex-nowrap\">\n                <div className=\"p1 text-strong border-bottom section--header\">{c('Info').t`Synced devices`}</div>\n                <Devices view={driveView} />\n            </PrivateMainArea>\n        </FileBrowserStateProvider>\n    );\n}\n\nexport default DevicesView;\n","import { Redirect, Route, RouteComponentProps, Switch } from 'react-router-dom';\n\nimport DevicesView from '../components/sections/Devices/DevicesView';\n\nconst DevicesContainer = ({ match }: RouteComponentProps) => {\n    return (\n        <Switch>\n            <Route path={match.url} exact component={DevicesView} />\n            <Redirect to=\"/devices\" />\n        </Switch>\n    );\n};\n\nexport default DevicesContainer;\n","import { isToday, isValid } from 'date-fns';\n\nimport { FeatureContextValue } from '../features';\n\nconst getShouldOpenMigrationModal = (migrationModalLastShownFeature: FeatureContextValue<string>) => {\n    const isProtonMailDomain = window.location.hostname.endsWith('.protonmail.com');\n    const lastShown = migrationModalLastShownFeature.feature?.Value;\n\n    const alreadyShownToday = (() => {\n        if (!lastShown) {\n            return false;\n        }\n\n        const lastShownDate = new Date(lastShown);\n\n        if (!isValid(lastShownDate)) {\n            return false;\n        }\n\n        return isToday(lastShownDate);\n    })();\n\n    const shouldOpen =\n        isProtonMailDomain && !migrationModalLastShownFeature.loading && lastShown !== undefined && !alreadyShownToday;\n\n    return shouldOpen;\n};\n\nexport default getShouldOpenMigrationModal;\n","import { useEffect, useState } from 'react';\n\nimport { DAY } from '@proton/shared/lib/constants';\n\nimport { useFeature } from '../../hooks';\nimport { FeatureCode } from '../features';\nimport useHasRebrandingFeedback from './useHasRebrandingFeedback';\n\nexport interface RebrandingFeatureValue {\n    /* User has visited rebranding in the past */\n    visited: boolean;\n    /* User has given rebranding feedback */\n    completed: boolean;\n    /* User has been prompted for rebranding feedback in the past */\n    prompted: boolean;\n}\n\n/*\n * Need to make sure that the functionality inside of the useEffect below really only runs once per runtime of\n * the application independently of what happens in the react tree. After the useEffect has ran once, we don't\n * ever want to run it again in the same runtime.\n */\nlet logicAlreadyRanDuringCurrentRuntime = false;\n\nconst useRebrandingFeedback = () => {\n    const hasRebrandingFeedback = useHasRebrandingFeedback();\n    const rebranding = useFeature<RebrandingFeatureValue>(FeatureCode.RebrandingFeedback);\n\n    const [handleDisplay, setHandleDisplay] = useState<undefined | (() => void)>(undefined);\n\n    useEffect(() => {\n        if (\n            rebranding.loading ||\n            !rebranding.feature?.Value ||\n            logicAlreadyRanDuringCurrentRuntime ||\n            !hasRebrandingFeedback\n        ) {\n            return;\n        }\n\n        /**\n         * Features are assumed to be loaded at this point, as ensured by the conditions above.\n         * This is important because this logic is only supposed to run once ever, therefore the\n         * data it consumes needs to be guaranteed in advance.\n         */\n        logicAlreadyRanDuringCurrentRuntime = true;\n\n        let promptTimeoutId: undefined | number;\n\n        const { Value: rebrandingValue } = rebranding.feature;\n\n        const updateRebranding = (value: Partial<RebrandingFeatureValue>) => {\n            void rebranding.update({ ...rebrandingValue, ...value });\n        };\n\n        const { visited, completed, prompted } = rebrandingValue;\n\n        const prompt = () => {\n            /**\n             * User has already visited the v5 / rebranding update AND has already been\n             * prompted for feedback previously. So we don't ask again.\n             */\n            if (prompted) {\n                return;\n            }\n\n            /* We didn't prompt the user but they already gave feedback on their own */\n            if (completed) {\n                return;\n            }\n\n            /*\n             * We want to store the \"handleDisplay\" callback here, not use react's\n             * setState callback api, therefore the curry. Yum!\n             */\n            setHandleDisplay(() => () => {\n                updateRebranding({ prompted: true });\n            });\n        };\n\n        /**\n         * User is visiting v5 / rebranding for the first time, we register this so\n         * that we can prompt them the next time they visit again.\n         *\n         * Alternatively, we also schedule a timer should the user not refresh / close\n         * his browser for a really long time, prompting him anyway after expiration of\n         * a certain amount of time in that case.\n         */\n        if (!visited) {\n            updateRebranding({ visited: true });\n\n            promptTimeoutId = window.setTimeout(prompt, DAY);\n\n            return;\n        }\n\n        prompt();\n\n        return () => {\n            window.clearTimeout(promptTimeoutId);\n        };\n    }, [rebranding.loading, rebranding, hasRebrandingFeedback]);\n\n    return handleDisplay;\n};\n\nexport default useRebrandingFeedback;\n","import { useEffect } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button, ButtonLike } from '@proton/atoms';\nimport {\n    FeatureCode,\n    Href,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    useFeature,\n    useSettingsLink,\n} from '@proton/components';\nimport { APPS, APP_NAMES } from '@proton/shared/lib/constants';\nimport userPromptSvg from '@proton/styles/assets/img/illustrations/sign-in-at-proton-me.svg';\n\ninterface Props extends ModalProps {\n    app?: APP_NAMES;\n}\n\nconst MigrationModal = ({ app = APPS.PROTONACCOUNT, ...rest }: Props) => {\n    const { update } = useFeature(FeatureCode.MigrationModalLastShown);\n    const settingsLink = useSettingsLink();\n\n    useEffect(() => {\n        if (!open) {\n            return;\n        }\n        const now = new Date().toISOString();\n        void update(now);\n    }, [open]);\n\n    // Should not be translated\n    const PROTON_ME_DOMAIN = 'proton.me';\n\n    const link = (\n        <Href key=\"link\" href=\"https://account.proton.me\">\n            account.proton.me\n        </Href>\n    );\n\n    return (\n        <ModalTwo {...rest}>\n            <ModalTwoHeader\n                title={\n                    // translator: full sentence \"Sign in at proton.me\"\n                    c('Title').t`Sign in at ${PROTON_ME_DOMAIN}`\n                }\n            />\n            <ModalTwoContent>\n                <img src={userPromptSvg} alt=\"\" />\n                <p className=\"mb1\">\n                    {\n                        // translator: full sentence \"We’re moving to proton.me.\"\n                        c('Info').t`We’re moving to ${PROTON_ME_DOMAIN}.`\n                    }\n                </p>\n                <p className=\"my1\">\n                    {\n                        // translator: full sentence \"Your email address will not change. But soon, you’ll need to sign in at account.proton.me. \"\n                        c('Info').jt`Your email address will not change. But soon, you’ll need to sign in at ${link}.`\n                    }\n                </p>\n                <p className=\"my1\">\n                    {c('Info')\n                        .t`If you don’t know your password, set a recovery phrase to make sure you don’t lose access to your account and data.`}\n                </p>\n            </ModalTwoContent>\n\n            <ModalTwoFooter>\n                <Button\n                    onClick={() => {\n                        rest.onClose?.();\n                        settingsLink('/recovery?action=generate-recovery-phrase', app);\n                    }}\n                    shape=\"outline\"\n                >\n                    {c('Info').t`Set recovery phrase`}\n                </Button>\n                <ButtonLike color=\"norm\" as={Href} href=\"https://account.proton.me\">\n                    {c('Info').t`Sign in`}\n                </ButtonLike>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default MigrationModal;\n","import { c } from 'ttag';\n\nimport { Icon, Info, StripedItem, StripedList } from '@proton/components';\nimport { CALENDAR_APP_NAME, DRIVE_APP_NAME, MAIL_APP_NAME } from '@proton/shared/lib/constants';\nimport humanSize from '@proton/shared/lib/helpers/humanSize';\n\nconst ReferralFeaturesList = () => {\n    const storageSize = humanSize(15 * 1024 ** 3, undefined, undefined, 0);\n    return (\n        <StripedList>\n            <StripedItem left={<Icon className=\"color-success\" name=\"storage\" size={20} />}>\n                {c('Info').t`${storageSize} storage`}\n                <Info\n                    className=\"ml0-5\"\n                    title={c('Info')\n                        .t`Storage space is shared across ${MAIL_APP_NAME}, ${CALENDAR_APP_NAME}, and ${DRIVE_APP_NAME}.`}\n                />\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"envelope\" size={20} />}>\n                {c('Info').t`10 email addresses`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"tag\" size={20} />}>\n                {c('Info').t`Unlimited folders, labels, and filters`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"paper-plane\" size={20} />}>\n                {c('Info').t`Unlimited messages`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"globe\" size={20} />}>\n                {c('Info').t`Support for 1 custom email domain`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"life-ring\" size={20} />}>\n                {c('Info').t`Priority support`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"brand-proton-calendar\" size={20} />}>\n                {CALENDAR_APP_NAME}\n            </StripedItem>\n        </StripedList>\n    );\n};\n\nexport default ReferralFeaturesList;\n","import { useEffect } from 'react';\n\nimport { format } from 'date-fns';\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    FeatureCode,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    ReferralFeaturesList,\n    useFeature,\n    useSettingsLink,\n} from '@proton/components';\nimport { PLANS, PLAN_NAMES } from '@proton/shared/lib/constants';\nimport { dateLocale } from '@proton/shared/lib/i18n';\nimport emptyMailboxSvg from '@proton/styles/assets/img/illustrations/empty-mailbox.svg';\n\ninterface Props extends ModalProps<'div'> {\n    endDate: Date;\n}\n\nconst ReferralModal = ({ endDate, ...rest }: Props) => {\n    const planName = PLAN_NAMES[PLANS.MAIL];\n    const settingsLink = useSettingsLink();\n    const { feature, update } = useFeature(FeatureCode.SeenReferralModal);\n\n    useEffect(() => {\n        if (!open) {\n            return;\n        }\n        if (feature?.Value === false) {\n            void update(true);\n        }\n    }, [open]);\n\n    const handlePlan = (plan: PLANS, target: 'compare' | 'checkout') => {\n        const params = new URLSearchParams();\n        params.set('plan', plan);\n        params.set('type', 'referral');\n        params.set('target', target);\n        settingsLink(`/dashboard?${params.toString()}`);\n    };\n\n    const formattedEndDate = format(endDate, 'P', { locale: dateLocale });\n\n    return (\n        <ModalTwo {...rest}>\n            <ModalTwoHeader\n                title={\n                    // translator: complete sentence would be : Your free trial ends soon, on 01/01/2022\n                    c('Title').t`Your free trial ends soon, on ${formattedEndDate}`\n                }\n            />\n            <ModalTwoContent>\n                <p>{\n                    // translator: complete sentence would be \"Upgrade today to avoid losing the following Mail Plus benefits\"\n                    c('Info').t`Upgrade today to avoid losing the following ${planName} benefits.`\n                }</p>\n                <div className=\"flex flex-justify-center\">\n                    <img src={emptyMailboxSvg} alt=\"Mailbox image\" />\n                </div>\n                <ReferralFeaturesList />\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                {/** TODO */}\n                <Button\n                    onClick={() => {\n                        rest.onClose?.();\n                        handlePlan(PLANS.MAIL, 'compare');\n                    }}\n                    shape=\"outline\"\n                >{c('Info').t`Other options`}</Button>\n                <Button\n                    color=\"norm\"\n                    onClick={() => {\n                        rest.onClose?.();\n                        handlePlan(PLANS.MAIL, 'checkout');\n                    }}\n                >{\n                    // translator: full sentence could be \"Continue with Plus\"\n                    c('Info').t`Continue with ${planName}`\n                }</Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default ReferralModal;\n","import { useEffect, useRef } from 'react';\n\nimport {\n    FeatureCode,\n    MigrationModal,\n    RebrandingFeedbackModal,\n    ReferralModal,\n    getShouldOpenMigrationModal,\n    getShouldOpenReferralModal,\n    useFeature,\n    useModalState,\n    useRebrandingFeedback,\n    useSubscription,\n} from '@proton/components';\nimport { APPS } from '@proton/shared/lib/constants';\n\nconst DriveStartupModals = () => {\n    // Migration modal\n    const [migrationModal, setMigrationModal, renderMigrationModal] = useModalState();\n    const migrationModalLastShownFeature = useFeature<string>(FeatureCode.MigrationModalLastShown);\n    const shouldOpenMigrationModal = getShouldOpenMigrationModal(migrationModalLastShownFeature);\n\n    // Referral modal\n    const [subscription] = useSubscription();\n    const seenReferralModal = useFeature<boolean>(FeatureCode.SeenReferralModal);\n    const [referralModal, setReferralModal, renderReferralModal] = useModalState();\n    const shouldOpenReferralModal = getShouldOpenReferralModal({ subscription, feature: seenReferralModal.feature });\n\n    const [rebrandingFeedbackModal, setRebrandingFeedbackModal, renderRebrandingFeedbackModal] = useModalState();\n    const handleRebrandingFeedbackModalDisplay = useRebrandingFeedback();\n\n    const onceRef = useRef(false);\n    useEffect(() => {\n        if (onceRef.current) {\n            return;\n        }\n\n        const openModal = (setModalOpen: (newValue: boolean) => void) => {\n            onceRef.current = true;\n            setModalOpen(true);\n        };\n\n        if (shouldOpenMigrationModal) {\n            openModal(setMigrationModal);\n        } else if (shouldOpenReferralModal.open) {\n            openModal(setReferralModal);\n        } else if (handleRebrandingFeedbackModalDisplay) {\n            openModal(setRebrandingFeedbackModal);\n        }\n    }, [shouldOpenMigrationModal, shouldOpenReferralModal.open, handleRebrandingFeedbackModalDisplay]);\n\n    return (\n        <>\n            {renderMigrationModal && <MigrationModal app={APPS.PROTONDRIVE} {...migrationModal} />}\n            {renderReferralModal && <ReferralModal endDate={shouldOpenReferralModal.endDate} {...referralModal} />}\n            {renderRebrandingFeedbackModal && (\n                <RebrandingFeedbackModal onMount={handleRebrandingFeedbackModalDisplay} {...rebrandingFeedbackModal} />\n            )}\n        </>\n    );\n};\n\nexport default DriveStartupModals;\n","import { fromUnixTime, subDays } from 'date-fns';\n\nimport { isTrial } from '@proton/shared/lib/helpers/subscription';\nimport { Subscription } from '@proton/shared/lib/interfaces';\n\nimport { Feature } from '../../features';\n\nexport const getShouldOpenReferralModal = ({\n    subscription,\n    feature,\n}: {\n    subscription: Subscription | undefined;\n    feature: Feature<boolean> | undefined;\n}) => {\n    if (!subscription?.PeriodEnd || !isTrial(subscription)) {\n        return { open: false, endDate: new Date() };\n    }\n\n    const endDate = fromUnixTime(subscription.PeriodEnd);\n    // Should be in trial and 3 days before end\n    const willEndSoon = new Date() >= subDays(endDate, 3);\n\n    const open = willEndSoon && feature?.Value === false;\n\n    return { open, endDate };\n};\n","import { useContext } from 'react';\n\nimport { GlobalLoaderContext, TaskOptions } from './GlobalLoaderProvider';\n\ntype WithGlobalLoading = <T>(promise: Promise<T>) => Promise<T>;\n\nfunction useGlobalLoader(defaultTaskOptions: TaskOptions = {}): WithGlobalLoading {\n    const globalLoader = useContext(GlobalLoaderContext);\n\n    if (!globalLoader) {\n        throw new Error('Trying to use uninitialized GlobalLoaderContext');\n    }\n\n    const withGlobalLoader = <T>(promise: Promise<T>, options: TaskOptions = defaultTaskOptions) => {\n        const [taskPromise] = globalLoader.addPendingTask(promise, options);\n        return taskPromise;\n    };\n\n    return withGlobalLoader;\n}\n\nexport default useGlobalLoader;\n","import { useRef, useState } from 'react';\nimport * as React from 'react';\n\nimport { c } from 'ttag';\n\nimport { useGlobalLoader } from '@proton/components';\nimport { CUSTOM_DATA_FORMAT } from '@proton/shared/lib/drive/constants';\nimport isTruthy from '@proton/utils/isTruthy';\nimport noop from '@proton/utils/noop';\n\nimport { useSelection } from '../../components/FileBrowser';\nimport { DragMoveControls } from '../../components/FileBrowser/interface';\nimport { DriveItem } from '../../components/sections/Drive/Drive';\nimport { useActions } from '../../store';\nimport { LinkInfo } from '../../store/_actions/interface';\n\ntype DragAndDropItem = DriveItem;\n\nexport default function useDriveDragMove(shareId: string, contents: DragAndDropItem[], clearSelections: () => void) {\n    const { moveLinks } = useActions();\n    const withGlobalLoader = useGlobalLoader({ text: c('Info').t`Moving files` });\n    const [allDragging, setAllDragging] = useState<DragAndDropItem[]>([]);\n    const [activeDropTarget, setActiveDropTarget] = useState<DragAndDropItem>();\n    const dragEnterCounter = useRef(0);\n    const selectionControls = useSelection();\n\n    const selectedItems = React.useMemo(\n        () =>\n            selectionControls?.selectedItemIds\n                .map((selectedItemId) => contents.find(({ id, isLocked }) => !isLocked && selectedItemId === id))\n                .filter(isTruthy) || [],\n        [selectionControls?.selectedItemIds]\n    );\n\n    const getHandleItemDrop = (newParentLinkId: string) => async (e: React.DragEvent) => {\n        let toMove: DragAndDropItem[];\n        try {\n            toMove = JSON.parse(e.dataTransfer.getData(CUSTOM_DATA_FORMAT));\n        } catch (err: any) {\n            // Data should be set by DecryptedLink when drag starts.\n            // If the data transfer was not available or the move was so\n            // fast that the data were not set yet, we should ignore the\n            // event.\n            console.warn('Could not finish move operation due to', err);\n            return;\n        }\n        dragEnterCounter.current = 0;\n\n        clearSelections();\n        setActiveDropTarget(undefined);\n\n        const toMoveInfo: LinkInfo[] = toMove.map((item) => ({\n            parentLinkId: item.parentLinkId,\n            name: item.name,\n            isFile: item.isFile,\n            linkId: item.id,\n            rootShareId: shareId,\n        }));\n\n        await withGlobalLoader(moveLinks(new AbortController().signal, shareId, toMoveInfo, newParentLinkId));\n    };\n\n    const getDragMoveControls = (item: DragAndDropItem): DragMoveControls => {\n        const dragging = allDragging.some(({ id }) => id === item.id);\n        const setDragging = (isDragging: boolean) =>\n            isDragging\n                ? setAllDragging(selectedItems.some(({ id }) => id === item.id) ? selectedItems : [item])\n                : setAllDragging([]);\n\n        const isActiveDropTarget = activeDropTarget?.id === item.id;\n        const availableTarget = !item.isFile && allDragging.every(({ id }) => item.id !== id);\n        // console.log({item});\n        const handleDrop = getHandleItemDrop(item.id);\n\n        const handleDragOver = (e: React.DragEvent<HTMLTableRowElement>) => {\n            if (availableTarget) {\n                e.dataTransfer.dropEffect = 'move';\n                e.preventDefault();\n                if (dragEnterCounter.current === 1 && !isActiveDropTarget) {\n                    setActiveDropTarget(item);\n                }\n            }\n        };\n\n        const handleDragLeave = () => {\n            if (availableTarget) {\n                dragEnterCounter.current -= 1;\n\n                if (dragEnterCounter.current <= 0 && isActiveDropTarget) {\n                    setActiveDropTarget(undefined);\n                }\n            }\n        };\n\n        const handleDragEnter = () => {\n            if (availableTarget) {\n                dragEnterCounter.current += 1;\n            }\n        };\n\n        return {\n            handleDragOver,\n            handleDrop,\n            handleDragLeave,\n            handleDragEnter,\n            dragging,\n            setDragging,\n            isActiveDropTarget,\n            selectedItems,\n        };\n    };\n\n    return { getDragMoveControls, getHandleItemDrop };\n}\n\nexport function useDriveDragMoveTarget(shareId: string) {\n    const { getHandleItemDrop } = useDriveDragMove(shareId, [], noop);\n    return { getHandleItemDrop };\n}\n","import { useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { CollapsingBreadcrumbs, Loader, useNotifications } from '@proton/components';\nimport { BreadcrumbInfo } from '@proton/components/components/collapsingBreadcrumbs/interfaces';\n\nimport { DriveFolder } from '../../hooks/drive/useActiveShare';\nimport { useDriveDragMoveTarget } from '../../hooks/drive/useDriveDragMove';\nimport useNavigate from '../../hooks/drive/useNavigate';\nimport { useLinkPath } from '../../store';\nimport { Share, ShareType, useShare } from '../../store/_shares';\nimport { reportError } from '../../store/_utils';\nimport SignatureIcon from '../SignatureIcon';\n\ninterface Props {\n    activeFolder: DriveFolder;\n}\n\nconst DriveBreadcrumbs = ({ activeFolder }: Props) => {\n    const { navigateToLink, navigateToDevices } = useNavigate();\n    const { createNotification } = useNotifications();\n    const { getHandleItemDrop } = useDriveDragMoveTarget(activeFolder.shareId);\n    const { traverseLinksToRoot } = useLinkPath(); // TODO: Get data using useFolderView instead one day.\n\n    const [dropTarget, setDropTarget] = useState<string>();\n    const [rootShare, setRootShare] = useState<Share>();\n    const { getShare } = useShare();\n\n    const [breadcrumbs, setBreadcrumbs] = useState<BreadcrumbInfo[]>([]);\n\n    useEffect(() => {\n        const abortController = new AbortController();\n\n        traverseLinksToRoot(abortController.signal, activeFolder.shareId, activeFolder.linkId)\n            .then((pathItems) => {\n                const breadcrumbs = pathItems.map(({ linkId, name, isRoot, link }) => {\n                    const handleDrop = getHandleItemDrop(linkId);\n\n                    const breadcrumb: BreadcrumbInfo = {\n                        key: linkId,\n                        text: name,\n                        richText: (\n                            <span className=\"flex flex-align-items-center flex-nowrap flex-item-fluid\">\n                                <SignatureIcon\n                                    isFile={link.isFile}\n                                    signatureIssues={link.signatureIssues}\n                                    className=\"mr0-25\"\n                                />\n                                <span className=\"text-pre text-ellipsis\">{name}</span>\n                            </span>\n                        ),\n                        noShrink: isRoot && rootShare?.type !== ShareType.device, // Keep root (My files) to be always fully visible.\n                        highlighted: dropTarget === linkId,\n                        collapsedText: name,\n                        onClick:\n                            linkId === activeFolder.linkId\n                                ? undefined\n                                : () => navigateToLink(activeFolder.shareId, linkId, false),\n                        onDragLeave: () => {\n                            setDropTarget(undefined);\n                        },\n                        onDragOver: (e) => {\n                            e.stopPropagation();\n                            e.preventDefault();\n                            if (dropTarget !== linkId) {\n                                setDropTarget(linkId);\n                            }\n                        },\n                        onDrop: async (e) => {\n                            setDropTarget(undefined);\n                            try {\n                                await handleDrop(e);\n                            } catch (e: any) {\n                                createNotification({\n                                    text: c('Notification').t`Failed to move, please try again`,\n                                    type: 'error',\n                                });\n                                console.error(e);\n                            }\n                        },\n                    };\n                    return breadcrumb;\n                });\n                setBreadcrumbs(breadcrumbs);\n            })\n            .catch((err: any) => {\n                reportError(err);\n            });\n\n        return () => {\n            abortController.abort();\n        };\n    }, [activeFolder.shareId, activeFolder.linkId, dropTarget, rootShare]);\n\n    useEffect(() => {\n        const abortController = new AbortController();\n        void getShare(abortController.signal, activeFolder.shareId).then((share) => {\n            setRootShare(share);\n        });\n    }, [activeFolder.shareId]);\n\n    if (breadcrumbs.length === 0) {\n        return <Loader className=\"pt0-5 pb0-5 pl0-75 pr0-75\" />;\n    }\n\n    if (rootShare?.type === ShareType.device) {\n        breadcrumbs.unshift({\n            key: 'devices-root',\n            text: c('Title').t`Synced devices`,\n            noShrink: true,\n            onClick: navigateToDevices,\n        });\n    }\n\n    return <CollapsingBreadcrumbs breadcrumbs={breadcrumbs} />;\n};\n\nexport default DriveBreadcrumbs;\n","import { ReactNode, SyntheticEvent, useCallback, useState } from 'react';\nimport * as React from 'react';\n\nimport { c } from 'ttag';\n\nimport { useNotifications } from '@proton/components/hooks';\nimport dragdropImageSvg from '@proton/styles/assets/img/illustrations/drag-and-drop.svg';\n\nimport useActiveShare from '../../../hooks/drive/useActiveShare';\nimport { useUpload } from '../../../store';\nimport { UploadFileList } from '../../../store';\nimport { isTransferCancelError } from '../../../utils/transfer';\n\ninterface UploadDragDropProps {\n    children: ReactNode;\n    disabled?: boolean;\n    className?: string;\n}\n\nconst UploadDragDrop = ({ children, className, disabled }: UploadDragDropProps) => {\n    const { createNotification } = useNotifications();\n    const { activeFolder } = useActiveShare();\n    const { uploadFiles } = useUpload();\n\n    const [overlayIsVisible, setOverlayIsVisible] = useState(false);\n\n    const overlayEnabled = !disabled;\n\n    const handleDragOver = useCallback(\n        (e: React.DragEvent<HTMLDivElement>) => {\n            if (!e.dataTransfer.types.includes('Files')) {\n                return;\n            }\n\n            if (overlayIsVisible !== overlayEnabled) {\n                setOverlayIsVisible(overlayEnabled);\n            }\n        },\n        [overlayEnabled, overlayIsVisible]\n    );\n\n    const handleDragLeave = useCallback(() => {\n        setOverlayIsVisible(false);\n    }, [overlayIsVisible]);\n\n    const handleDrop = useCallback(\n        async (e: React.DragEvent<HTMLDivElement>) => {\n            e.preventDefault();\n            setOverlayIsVisible(false);\n            const { items } = e.dataTransfer;\n\n            if (!items) {\n                return;\n            }\n\n            const filesToUpload: UploadFileList = [];\n\n            const traverseDirectories = async (item: any, path: string[] = []) => {\n                if (item.isFile) {\n                    return new Promise<void>((resolve, reject) => {\n                        item.file(\n                            (file: File) => {\n                                filesToUpload.push({ path, file });\n                                resolve();\n                            },\n                            (error: Error) => {\n                                createNotification({\n                                    type: 'warning',\n                                    // translator: here is an example of full sentence: File \".abc\" cannot be uploaded due to \"browser specific error such as hidden files are not allowed\" error\n                                    text: c('Error').t`File \"${item.name}\" cannot be uploaded due to \"${error}\" error`,\n                                });\n                                reject(new Error(`Unable to get File ${item}: ${error}`));\n                            }\n                        );\n                    });\n                }\n                if (item.isDirectory) {\n                    const reader = item.createReader();\n\n                    const modificationTime = await new Promise<Date | undefined>((resolve, reject) => {\n                        item.getMetadata(resolve, reject);\n                    })\n                        .then((metadata: any) => {\n                            return metadata.modificationTime;\n                        })\n                        .catch(() => {\n                            // For example, Firefox does not support `getMetadata`\n                            // and there is no other way to get modification time\n                            // at this moment.\n                            return undefined;\n                        });\n                    filesToUpload.push({\n                        path,\n                        folder: item.name,\n                        modificationTime,\n                    });\n\n                    // Iterates over folders recursively and puts them into filesToUpload list\n                    const getEntries = async () => {\n                        const promises: Promise<any>[] = [];\n\n                        // Folders are read in batch, need to wait\n                        await new Promise<PromiseSettledResult<any>[] | void>((resolve, reject) => {\n                            reader.readEntries(\n                                (entries: any[]) => {\n                                    if (entries.length) {\n                                        entries.forEach((entry) =>\n                                            promises.push(traverseDirectories(entry, [...path, item.name]))\n                                        );\n                                        resolve(getEntries());\n                                    } else {\n                                        resolve();\n                                    }\n                                },\n                                (error: Error) => reject(new Error(`Unable to traverse directory ${item}: ${error}`))\n                            );\n                        });\n\n                        return Promise.allSettled(promises);\n                    };\n                    await getEntries();\n                }\n            };\n\n            const promises: Promise<any>[] = [];\n            for (let i = 0; i < items.length; i++) {\n                const item = (items[i] as any).getAsEntry\n                    ? (items[i] as any).getAsEntry()\n                    : items[i].webkitGetAsEntry();\n\n                if (item) {\n                    promises.push(traverseDirectories(item));\n                }\n            }\n\n            // Need to wait for all files to have been read\n            const results = await Promise.allSettled(promises);\n            const errors = results.reduce((err, result) => {\n                if (result.status === 'rejected') {\n                    err.push(result.reason);\n                }\n                return err;\n            }, [] as string[]);\n\n            if (errors.length) {\n                console.error(errors);\n            }\n\n            uploadFiles(activeFolder.shareId, activeFolder.linkId, filesToUpload).catch((err) => {\n                if (!isTransferCancelError(err)) {\n                    console.error(err);\n                }\n            });\n        },\n        [overlayIsVisible]\n    );\n\n    const preventDefaultEvent = useCallback((e: SyntheticEvent) => e.preventDefault(), []);\n\n    return (\n        <div\n            className={className}\n            onDragEnter={handleDragOver}\n            onDragOver={handleDragOver}\n            onDrop={preventDefaultEvent}\n        >\n            <img className=\"visibility-hidden absolute h0 w0\" src={dragdropImageSvg} alt=\"\" aria-hidden=\"true\" />\n            {children}\n            {overlayEnabled && overlayIsVisible && (\n                <div\n                    className=\"upload-drag-drop\"\n                    onDragLeave={handleDragLeave}\n                    onDragOver={preventDefaultEvent}\n                    onDrop={handleDrop}\n                >\n                    <section className=\"upload-drag-drop-infobox p4 pt3\">\n                        <img className=\"upload-drag-drop-image\" src={dragdropImageSvg} alt=\"\" aria-hidden=\"true\" />\n                        <h2 className=\"text-bold mt1 mb0\">{c('Title').t`Drop to upload`}</h2>\n                        <p className=\"mt1 mb0\">{c('Info').t`Your files will be encrypted and then saved.`}</p>\n                    </section>\n                </div>\n            )}\n        </div>\n    );\n};\n\nexport default UploadDragDrop;\n","import { FileIcon } from '@proton/components';\n\nimport SignatureIcon from '../../SignatureIcon';\nimport { DriveItem } from '../Drive/Drive';\nimport { SharedLinkItem } from '../SharedLinks/SharedLinks';\nimport { TrashItem } from '../Trash/Trash';\nimport GridViewItemBase from './GridViewItem';\nimport { getLinkIconText } from './utils';\n\nexport function GridViewItem({ item }: { item: DriveItem | TrashItem | SharedLinkItem }) {\n    const iconText = getLinkIconText({\n        isFile: item.isFile,\n        mimeType: item.mimeType,\n        linkName: item.name,\n    });\n\n    const IconComponent = (\n        <>\n            {item.cachedThumbnailUrl ? (\n                <img src={item.cachedThumbnailUrl} className=\"file-browser-grid-item--thumbnail\" alt={iconText} />\n            ) : (\n                <FileIcon size={48} mimeType={item.isFile ? item.mimeType : 'Folder'} alt={iconText} />\n            )}\n        </>\n    );\n\n    return (\n        <GridViewItemBase\n            IconComponent={IconComponent}\n            SignatureIconComponent={\n                <SignatureIcon\n                    isFile={item.isFile}\n                    signatureIssues={item.signatureIssues}\n                    className=\"file-browser-grid-view--signature-icon\"\n                />\n            }\n            item={item}\n        />\n    );\n}\n","import { classnames } from '../../helpers';\n\nexport interface Props {\n    className?: string;\n}\n\nconst ContextSeparator = ({ className = '', ...rest }: Props) => {\n    return <hr className={classnames(['m0', className])} {...rest} />;\n};\n\nexport default ContextSeparator;\n","import { c } from 'ttag';\n\nimport useOpenModal from '../../../useOpenModal';\nimport { ContextMenuButton } from '../../ContextMenu';\n\ninterface Props {\n    close: () => void;\n}\n\nconst CreateNewFileButton = ({ close }: Props) => {\n    const { openCreateFile } = useOpenModal();\n\n    return (\n        <ContextMenuButton\n            testId=\"toolbar-new-file\"\n            icon=\"file\"\n            name={c('Action').t`Create new text file`}\n            action={openCreateFile}\n            close={close}\n        />\n    );\n};\n\nexport default CreateNewFileButton;\n","import { c } from 'ttag';\n\nimport useOpenModal from '../../../useOpenModal';\nimport { ContextMenuButton } from '../../ContextMenu';\n\ninterface Props {\n    close: () => void;\n}\n\nconst CreateNewFolderButton = ({ close }: Props) => {\n    const { openCreateFolder } = useOpenModal();\n\n    return (\n        <ContextMenuButton\n            testId=\"toolbar-new-folder\"\n            icon=\"folder-plus\"\n            name={c('Action').t`Create new folder`}\n            action={openCreateFolder}\n            close={close}\n        />\n    );\n};\n\nexport default CreateNewFolderButton;\n","import { c } from 'ttag';\n\nimport { DecryptedLink } from '../../../../store';\nimport useOpenModal from '../../../useOpenModal';\nimport { ContextMenuButton } from '../../ContextMenu';\n\ninterface Props {\n    shareId: string;\n    selectedLinks: DecryptedLink[];\n    close: () => void;\n}\n\nconst MoveToFolderButton = ({ shareId, selectedLinks, close }: Props) => {\n    const { openMoveToFolder } = useOpenModal();\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Move to folder`}\n            icon=\"arrows-cross\"\n            testId=\"context-menu-move\"\n            action={() => openMoveToFolder(shareId, selectedLinks)}\n            close={close}\n        />\n    );\n};\n\nexport default MoveToFolderButton;\n","import { c } from 'ttag';\n\nimport { DecryptedLink, useActions } from '../../../../store';\nimport { ContextMenuButton } from '../../ContextMenu';\n\ninterface Props {\n    selectedLinks: DecryptedLink[];\n    close: () => void;\n}\n\nconst MoveToTrashButton = ({ selectedLinks, close }: Props) => {\n    const { trashLinks } = useActions();\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Move to trash`}\n            icon=\"trash\"\n            testId=\"context-menu-trash\"\n            action={() => trashLinks(new AbortController().signal, selectedLinks)}\n            close={close}\n        />\n    );\n};\n\nexport default MoveToTrashButton;\n","import { c } from 'ttag';\n\nimport { ContextMenuButton } from '../../ContextMenu';\n\ninterface Props {\n    close: () => void;\n    onClick: () => void;\n}\n\nconst UploadFileButton = ({ close, onClick }: Props) => {\n    return (\n        <ContextMenuButton\n            testId=\"toolbar-upload-file\"\n            icon=\"file-arrow-in-up\"\n            name={c('Action').t`Upload file`}\n            action={onClick}\n            close={close}\n        />\n    );\n};\n\nexport default UploadFileButton;\n","import { c } from 'ttag';\n\nimport { ContextMenuButton } from '../../ContextMenu';\n\ninterface Props {\n    close: () => void;\n    onClick: () => void;\n}\n\nconst UploadFolderButton = ({ close, onClick }: Props) => {\n    return (\n        <ContextMenuButton\n            testId=\"toolbar-upload-folder\"\n            icon=\"folder-arrow-up\"\n            name={c('Action').t`Upload folder`}\n            action={onClick}\n            close={close}\n        />\n    );\n};\n\nexport default UploadFolderButton;\n","import { ContextSeparator } from '@proton/components';\nimport { isPreviewAvailable } from '@proton/shared/lib/helpers/preview';\n\nimport { DecryptedLink } from '../../../store';\nimport { ContextMenuProps } from '../../FileBrowser/interface';\nimport {\n    CopyLinkButton,\n    DetailsButton,\n    DownloadButton,\n    PreviewButton,\n    RenameButton,\n    ShareLinkButton,\n} from '../ContextMenu';\nimport { ItemContextMenu } from '../ContextMenu/ItemContextMenu';\nimport { MoveToFolderButton, MoveToTrashButton } from './ContextMenuButtons';\n\nexport function DriveItemContextMenu({\n    shareId,\n    selectedLinks,\n    anchorRef,\n    isOpen,\n    position,\n    open,\n    close,\n    children,\n}: ContextMenuProps & {\n    shareId: string;\n    selectedLinks: DecryptedLink[];\n}) {\n    const selectedLink = selectedLinks[0];\n    const isOnlyOneItem = selectedLinks.length === 1;\n    const isOnlyOneFileItem = isOnlyOneItem && selectedLink.isFile;\n    const hasPreviewAvailable =\n        isOnlyOneFileItem && selectedLink.mimeType && isPreviewAvailable(selectedLink.mimeType, selectedLink.size);\n    const hasLink = isOnlyOneItem && selectedLink.shareUrl && !selectedLink.shareUrl.isExpired && !selectedLink.trashed;\n\n    return (\n        <ItemContextMenu isOpen={isOpen} open={open} close={close} position={position} anchorRef={anchorRef}>\n            {hasPreviewAvailable && <PreviewButton shareId={shareId} linkId={selectedLink.linkId} close={close} />}\n            {hasPreviewAvailable && <ContextSeparator />}\n            <DownloadButton shareId={shareId} selectedLinks={selectedLinks} close={close} />\n            {hasLink && <CopyLinkButton shareId={shareId} linkId={selectedLink.linkId} close={close} />}\n            {isOnlyOneItem && <ShareLinkButton shareId={shareId} link={selectedLink} close={close} />}\n            <ContextSeparator />\n            <MoveToFolderButton shareId={shareId} selectedLinks={selectedLinks} close={close} />\n            {isOnlyOneItem && <RenameButton shareId={shareId} link={selectedLink} close={close} />}\n            <DetailsButton selectedLinks={selectedLinks} close={close} />\n            <ContextSeparator />\n            <MoveToTrashButton selectedLinks={selectedLinks} close={close} />\n            {children}\n        </ItemContextMenu>\n    );\n}\n","import { useEarlyAccess } from '@proton/components';\n\nexport default function useIsEditEnabled() {\n    const { currentEnvironment } = useEarlyAccess();\n    return currentEnvironment === 'alpha' || currentEnvironment === 'beta';\n}\n","import { useEffect } from 'react';\nimport * as React from 'react';\n\nimport { ContextMenu, ContextSeparator } from '@proton/components';\n\nimport useActiveShare from '../../../hooks/drive/useActiveShare';\nimport { useFileUploadInput, useFolderUploadInput } from '../../../store';\nimport { ContextMenuProps } from '../../FileBrowser/interface';\nimport { ShareFileButton } from '../ContextMenu/buttons';\nimport useIsEditEnabled from '../useIsEditEnabled';\nimport { CreateNewFileButton, CreateNewFolderButton, UploadFileButton, UploadFolderButton } from './ContextMenuButtons';\n\nexport function FolderContextMenu({\n    shareId,\n    anchorRef,\n    isOpen,\n    position,\n    open,\n    close,\n}: ContextMenuProps & {\n    shareId: string;\n}) {\n    useEffect(() => {\n        if (position) {\n            open();\n        }\n    }, [position]);\n\n    const isEditEnabled = useIsEditEnabled();\n\n    const { activeFolder } = useActiveShare();\n    const {\n        inputRef: fileInput,\n        handleClick: fileClick,\n        handleChange: fileChange,\n    } = useFileUploadInput(activeFolder.shareId, activeFolder.linkId);\n    const {\n        inputRef: folderInput,\n        handleClick: folderClick,\n        handleChange: folderChange,\n    } = useFolderUploadInput(activeFolder.shareId, activeFolder.linkId);\n\n    // ContextMenu is removed from DOM when any action is executed but inputs\n    // need to stay rendered so onChange handler can work.\n    return (\n        <>\n            <input multiple type=\"file\" ref={fileInput} className=\"hidden\" onChange={fileChange} />\n            <input multiple type=\"file\" ref={folderInput} className=\"hidden\" onChange={folderChange} />\n            <ContextMenu isOpen={isOpen} close={close} position={position} anchorRef={anchorRef}>\n                <CreateNewFolderButton close={close} />\n                {isEditEnabled && <CreateNewFileButton close={close} />}\n                <ContextSeparator />\n                <UploadFileButton close={close} onClick={fileClick} />\n                <UploadFolderButton close={close} onClick={folderClick} />\n                <ContextSeparator />\n                <ShareFileButton close={close} shareId={shareId} />\n            </ContextMenu>\n        </>\n    );\n}\n","import { useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { EmptyViewContainer, Icon, useActiveBreakpoint, usePopperAnchor } from '@proton/components';\nimport uploadSvg from '@proton/styles/assets/img/illustrations/upload.svg';\n\nimport { FolderContextMenu } from './FolderContextMenu';\nimport { UploadButton } from './UploadButton';\n\nconst EmptyFolder = ({ shareId }: { shareId: string }) => {\n    const { isNarrow } = useActiveBreakpoint();\n    const { anchorRef, isOpen, open, close } = usePopperAnchor<HTMLDivElement>();\n    const [contextMenuPosition, setContextMenuPosition] = useState<{ top: number; left: number }>();\n\n    useEffect(() => {\n        if (!anchorRef.current) {\n            return;\n        }\n\n        const handleContextMenu = (ev: MouseEvent) => {\n            ev.stopPropagation();\n            ev.preventDefault();\n\n            if (isOpen) {\n                close();\n            }\n\n            setContextMenuPosition({ top: ev.clientY, left: ev.clientX });\n        };\n\n        anchorRef.current.addEventListener('contextmenu', handleContextMenu);\n\n        return () => {\n            anchorRef.current?.removeEventListener('contextmenu', handleContextMenu);\n        };\n    }, [anchorRef, isOpen, close, setContextMenuPosition]);\n\n    return (\n        <>\n            <div role=\"presentation\" ref={anchorRef} onClick={close} className=\"flex w100 flex flex-item-fluid\">\n                <EmptyViewContainer\n                    imageProps={{ src: uploadSvg, title: c('Info').t`There are no files yet` }}\n                    data-test-id=\"my-files-empty-placeholder\"\n                >\n                    <h3 className=\"text-bold\">{c('Info').t`Go ahead, upload a file`}</h3>\n                    <p className=\"color-weak\">\n                        {!isNarrow\n                            ? c('Info').t`It’s as easy as drag and drop or selecting files`\n                            : c('Info').t`Tap the + button to upload a file or folder`}\n                    </p>\n                    {!isNarrow && (\n                        <div className=\"flex flex-justify-center\">\n                            <UploadButton className=\"w13e\">\n                                <Icon name=\"arrow-up-line\" className=\"mr0-5\" />\n                                {c('Action').t`Upload files`}\n                            </UploadButton>\n                        </div>\n                    )}\n                </EmptyViewContainer>\n            </div>\n            <FolderContextMenu\n                shareId={shareId}\n                isOpen={isOpen}\n                open={open}\n                close={close}\n                position={contextMenuPosition}\n                anchorRef={anchorRef}\n            />\n        </>\n    );\n};\n\nexport default EmptyFolder;\n","import { useCallback, useEffect, useMemo, useRef } from 'react';\n\nimport { useActiveBreakpoint } from '@proton/components';\n\nimport { DriveFolder } from '../../../hooks/drive/useActiveShare';\nimport useDriveDragMove from '../../../hooks/drive/useDriveDragMove';\nimport useNavigate from '../../../hooks/drive/useNavigate';\nimport { EncryptedLink, LinkShareUrl, useFolderView, useThumbnailsDownload } from '../../../store';\nimport { SortField } from '../../../store/_views/utils/useSorting';\nimport FileBrowser, {\n    Cells,\n    GridHeader,\n    useContextMenuControls,\n    useItemContextMenu,\n    useSelection,\n} from '../../FileBrowser';\nimport { BrowserItemId, FileBrowserBaseItem, ListViewHeaderItem } from '../../FileBrowser/interface';\nimport useOpenModal from '../../useOpenModal';\nimport { GridViewItem } from '../FileBrowser/GridViewItemLink';\nimport { ModifiedCell, NameCell, ShareOptionsCell, SizeCell } from '../FileBrowser/contentCells';\nimport headerItems from '../FileBrowser/headerCells';\nimport { translateSortField } from '../SortDropdown';\nimport { getSelectedItems } from '../helpers';\nimport { DriveItemContextMenu } from './DriveContextMenu';\nimport EmptyFolder from './EmptyFolder';\nimport { FolderContextMenu } from './FolderContextMenu';\n\nexport interface DriveItem extends FileBrowserBaseItem {\n    activeRevision?: EncryptedLink['activeRevision'];\n    cachedThumbnailUrl?: string;\n    hasThumbnail: boolean;\n    isFile: boolean;\n    mimeType: string;\n    fileModifyTime: number;\n    name: string;\n    shareUrl?: LinkShareUrl;\n    signatureIssues?: any;\n    size: number;\n    trashed: number | null;\n    parentLinkId: string;\n}\n\ninterface Props {\n    activeFolder: DriveFolder;\n    folderView: ReturnType<typeof useFolderView>;\n}\n\nconst { CheckboxCell, ContextMenuCell } = Cells;\n\nconst myFilesDesktopCells: React.FC<{ item: DriveItem }>[] = [\n    CheckboxCell,\n    NameCell,\n    ModifiedCell,\n    SizeCell,\n    ShareOptionsCell,\n    ContextMenuCell,\n];\nconst myFilesMobileCells = [CheckboxCell, NameCell, ContextMenuCell];\n\nconst headerItemsDesktop: ListViewHeaderItem[] = [\n    headerItems.checkbox,\n    headerItems.name,\n    headerItems.modificationDate,\n    headerItems.size,\n    headerItems.placeholder,\n    headerItems.placeholder,\n];\n\nconst headerItemsMobile: ListViewHeaderItem[] = [headerItems.checkbox, headerItems.name, headerItems.placeholder];\n\ntype DriveSortFields = Extract<SortField, SortField.name | SortField.fileModifyTime | SortField.size>;\nconst SORT_FIELDS: DriveSortFields[] = [SortField.name, SortField.fileModifyTime, SortField.size];\n\nfunction Drive({ activeFolder, folderView }: Props) {\n    const { shareId, linkId } = activeFolder;\n    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);\n\n    const browserContextMenu = useContextMenuControls();\n    const browserItemContextMenu = useItemContextMenu();\n    const thumbnails = useThumbnailsDownload();\n    const { navigateToLink } = useNavigate();\n    const selectionControls = useSelection();\n    const { isDesktop } = useActiveBreakpoint();\n\n    const { layout, folderName, items, sortParams, setSorting, isLoading } = folderView;\n\n    const selectedItems = useMemo(\n        () => getSelectedItems(items, selectionControls!.selectedItemIds),\n        [items, selectionControls!.selectedItemIds]\n    );\n\n    const { openPreview } = useOpenModal();\n    const browserItems: DriveItem[] = items.map((item) => ({ ...item, id: item.linkId }));\n    const { getDragMoveControls } = useDriveDragMove(shareId, browserItems, selectionControls!.clearSelections);\n\n    /* eslint-disable react/display-name */\n    const GridHeaderComponent = useMemo(\n        () =>\n            ({ scrollAreaRef }: { scrollAreaRef: React.RefObject<HTMLDivElement> }) => {\n                const activeSortingText = translateSortField(sortParams.sortField);\n                return (\n                    <GridHeader\n                        isLoading={isLoading}\n                        sortFields={SORT_FIELDS}\n                        onSort={setSorting}\n                        sortField={sortParams.sortField}\n                        sortOrder={sortParams.sortOrder}\n                        itemCount={browserItems.length}\n                        onToggleAllSelected={selectionControls!.toggleAllSelected}\n                        scrollAreaRef={scrollAreaRef}\n                        activeSortingText={activeSortingText}\n                    />\n                );\n            },\n        [sortParams.sortField, sortParams.sortOrder, isLoading]\n    );\n\n    const handleItemRender = useCallback(\n        (item: DriveItem) => {\n            if (item.hasThumbnail && item.activeRevision && !item.cachedThumbnailUrl) {\n                thumbnails.addToDownloadQueue(shareId, item.id, item.activeRevision.id);\n            }\n        },\n        [items]\n    );\n\n    const handleClick = useCallback(\n        (id: BrowserItemId) => {\n            const item = browserItems.find((item) => item.id === id);\n\n            if (!item) {\n                return;\n            }\n            document.getSelection()?.removeAllRanges();\n            if (item.isFile) {\n                openPreview(shareId, id);\n                return;\n            }\n            navigateToLink(shareId, id, item.isFile);\n        },\n        [navigateToLink, shareId, browserItems]\n    );\n\n    const handleScroll = () => {\n        browserContextMenu.close();\n        browserItemContextMenu.close();\n    };\n\n    useEffect(() => {\n        browserContextMenu.close();\n        browserItemContextMenu.close();\n    }, [shareId, linkId]);\n\n    if (!items.length && !isLoading) {\n        return <EmptyFolder shareId={shareId} />;\n    }\n\n    const Cells = isDesktop ? myFilesDesktopCells : myFilesMobileCells;\n    const headerItems = isDesktop ? headerItemsDesktop : headerItemsMobile;\n\n    return (\n        <>\n            <FolderContextMenu\n                shareId={shareId}\n                anchorRef={contextMenuAnchorRef}\n                close={browserContextMenu.close}\n                isOpen={browserContextMenu.isOpen}\n                open={browserContextMenu.open}\n                position={browserContextMenu.position}\n            />\n            <DriveItemContextMenu\n                shareId={shareId}\n                selectedLinks={selectedItems}\n                anchorRef={contextMenuAnchorRef}\n                close={browserItemContextMenu.close}\n                isOpen={browserItemContextMenu.isOpen}\n                open={browserItemContextMenu.open}\n                position={browserItemContextMenu.position}\n            />\n            <FileBrowser\n                // data\n                caption={folderName}\n                headerItems={headerItems}\n                items={browserItems}\n                layout={layout}\n                loading={isLoading}\n                sortParams={sortParams}\n                // components\n                Cells={Cells}\n                GridHeaderComponent={GridHeaderComponent}\n                GridViewItem={GridViewItem}\n                // handlers\n                onItemOpen={handleClick}\n                contextMenuAnchorRef={contextMenuAnchorRef}\n                onItemContextMenu={browserItemContextMenu.handleContextMenu}\n                onItemRender={handleItemRender}\n                onSort={setSorting}\n                onScroll={handleScroll}\n                onViewContextMenu={browserContextMenu.handleContextMenu}\n                getDragMoveControls={getDragMoveControls}\n            />\n        </>\n    );\n}\n\nexport default Drive;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport {\n    Dropdown,\n    DropdownMenu,\n    DropdownMenuButton,\n    Icon,\n    IconName,\n    ToolbarButton,\n    generateUID,\n    usePopperAnchor,\n} from '@proton/components';\n\nimport { DecryptedLink, useActions } from '../../../../store';\nimport useToolbarActions from '../../../useOpenModal';\n\ninterface Props {\n    shareId: string;\n    selectedLinks: DecryptedLink[];\n}\n\nconst ActionsDropdown = ({ shareId, selectedLinks }: Props) => {\n    const [uid] = useState(generateUID('actions-dropdown'));\n    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();\n    const { openDetails, openFilesDetails, openMoveToFolder, openRename, openLinkSharing } = useToolbarActions();\n    const { trashLinks } = useActions();\n\n    const hasFoldersSelected = selectedLinks.some((item) => !item.isFile);\n    const isMultiSelect = selectedLinks.length > 1;\n    const hasSharedLink = !!selectedLinks[0]?.shareUrl;\n    const selectedLinkIds = selectedLinks.map(({ linkId }) => linkId);\n\n    const menuItems: {\n        hidden: boolean;\n        name: string;\n        icon: IconName;\n        testId: string;\n        action: () => void;\n    }[] = [\n        {\n            hidden: isMultiSelect || hasFoldersSelected,\n            name: hasSharedLink ? c('Action').t`Manage link` : c('Action').t`Get link`,\n            icon: 'link',\n            testId: 'actions-dropdown-share-link',\n            action: () => openLinkSharing(shareId, selectedLinkIds[0]),\n        },\n        {\n            hidden: false,\n            name: c('Action').t`Move to folder`,\n            icon: 'arrows-cross',\n            testId: 'actions-dropdown-move',\n            action: () => openMoveToFolder(shareId, selectedLinks),\n        },\n        {\n            hidden: isMultiSelect,\n            name: c('Action').t`Rename`,\n            icon: 'pen-square',\n            testId: 'actions-dropdown-rename',\n            action: () => openRename(shareId, selectedLinks[0]),\n        },\n        {\n            hidden: isMultiSelect,\n            name: c('Action').t`Details`,\n            icon: 'info-circle',\n            testId: 'actions-dropdown-details',\n            action: () => openDetails(shareId, selectedLinkIds[0]),\n        },\n        {\n            hidden: !isMultiSelect || hasFoldersSelected,\n            name: c('Action').t`Details`,\n            icon: 'info-circle',\n            testId: 'actions-dropdown-details',\n            action: () => openFilesDetails(selectedLinks),\n        },\n        {\n            hidden: false,\n            name: c('Action').t`Move to trash`,\n            icon: 'trash',\n            testId: 'actions-dropdown-trash',\n            action: () => trashLinks(new AbortController().signal, selectedLinks),\n        },\n        {\n            hidden: isMultiSelect,\n            name: hasSharedLink ? c('Action').t`Sharing options` : c('Action').t`Share via link`,\n            icon: 'link',\n            testId: 'actions-dropdown-share-link',\n            action: () => openLinkSharing(shareId, selectedLinkIds[0]),\n        },\n    ];\n\n    const dropdownMenuButtons = menuItems\n        .filter((menuItem) => !menuItem.hidden)\n        .map((item) => (\n            <DropdownMenuButton\n                key={item.name}\n                hidden={item.hidden}\n                onContextMenu={(e) => e.stopPropagation()}\n                className=\"flex flex-nowrap text-left\"\n                onClick={(e) => {\n                    e.stopPropagation();\n                    item.action();\n                    close();\n                }}\n                data-testid={item.testId}\n            >\n                <Icon className=\"mt0-25 mr0-5\" name={item.icon} />\n                {item.name}\n            </DropdownMenuButton>\n        ));\n\n    return (\n        <>\n            <ToolbarButton\n                disabled={!selectedLinks.length}\n                aria-describedby={uid}\n                ref={anchorRef}\n                aria-expanded={isOpen}\n                onClick={toggle}\n                icon={<Icon name=\"chevron-down-filled\" rotate={isOpen ? 180 : 0} />}\n                data-testid=\"actions-dropdown\"\n                title={c('Title').t`Show actions`}\n            />\n            <Dropdown id={uid} isOpen={isOpen} anchorRef={anchorRef} onClose={close} originalPlacement=\"bottom\">\n                <DropdownMenu>{dropdownMenuButtons}</DropdownMenu>\n            </Dropdown>\n        </>\n    );\n};\n\nexport default ActionsDropdown;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport useOpenModal from '../../../useOpenModal';\n\nconst CreateNewFileButton = () => {\n    const { openCreateFile } = useOpenModal();\n\n    return (\n        <ToolbarButton\n            icon={<Icon name=\"file\" />}\n            title={c('Action').t`Create new text file`}\n            onClick={openCreateFile}\n            data-testid=\"toolbar-create-file\"\n        />\n    );\n};\n\nexport default CreateNewFileButton;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport useOpenModal from '../../../useOpenModal';\n\nconst CreateNewFolderButton = () => {\n    const { openCreateFolder } = useOpenModal();\n\n    return (\n        <ToolbarButton\n            icon={<Icon name=\"folder-plus\" />}\n            title={c('Action').t`Create new folder`}\n            onClick={openCreateFolder}\n            data-testid=\"toolbar-new-folder\"\n        />\n    );\n};\n\nexport default CreateNewFolderButton;\n","import { c } from 'ttag';\n\nimport { Icon, ToolbarButton } from '@proton/components';\n\nimport { DecryptedLink } from '../../../../store';\nimport useOpenModal from '../../../useOpenModal';\n\ninterface Props {\n    shareId: string;\n    selectedLinks: DecryptedLink[];\n}\n\nconst MoveToFolderButton = ({ shareId, selectedLinks }: Props) => {\n    const { openMoveToFolder } = useOpenModal();\n\n    return (\n        <ToolbarButton\n            title={c('Action').t`Move to folder`}\n            icon={<Icon name=\"arrows-cross\" />}\n            onClick={() => openMoveToFolder(shareId, selectedLinks)}\n            data-testid=\"toolbar-move\"\n        />\n    );\n};\n\nexport default MoveToFolderButton;\n","import { c } from 'ttag';\n\nimport 