eUploadFolder,\n        handleChange,\n    } = useFolderUploadInput(activeFolder.shareId, activeFolder.linkId);\n\n    return (\n        <>\n            <input multiple type=\"file\" ref={fileInput} className=\"hidden\" onChange={handleChange} />\n            <ToolbarButton\n                data-testid=\"toolbar-upload-folder\"\n                icon={<Icon name=\"folder-arrow-up\" />}\n                title={c('Action').t`Upload folder`}\n                onClick={handleUploadFolder}\n            />\n        </>\n    );\n};\n\nexport default UploadFolderButton;\n","import { useMemo } from 'react';\n\nimport { Vr } from '@proton/atoms';\nimport { Toolbar, useActiveBreakpoint } from '@proton/components';\nimport { getDevice } from '@proton/shared/lib/helpers/browser';\n\nimport { DecryptedLink } from '../../../store';\nimport { useSelection } from '../../FileBrowser';\nimport {\n    DetailsButton,\n    DownloadButton,\n    LayoutButton,\n    PreviewButton,\n    RenameButton,\n    ShareFileButton,\n    ShareLinkButton,\n} from '../ToolbarButtons';\nimport { getSelectedItems } from '../helpers';\nimport useIsEditEnabled from '../useIsEditEnabled';\nimport {\n    ActionsDropdown,\n    CreateNewFileButton,\n    CreateNewFolderButton,\n    MoveToFolderButton,\n    MoveToTrashButton,\n    UploadFileButton,\n    UploadFolderButton,\n} from './ToolbarButtons';\n\ninterface Props {\n    shareId: string;\n    items: DecryptedLink[];\n    showOptionsForNoSelection?: boolean;\n}\n\nconst DriveToolbar = ({ shareId, items, showOptionsForNoSelection = true }: Props) => {\n    const isDesktop = !getDevice()?.type;\n    const { isNarrow } = useActiveBreakpoint();\n    const selectionControls = useSelection()!;\n    const isEditEnabled = useIsEditEnabled();\n\n    const selectedItems = useMemo(\n        () => getSelectedItems(items, selectionControls!.selectedItemIds),\n        [items, selectionControls!.selectedItemIds]\n    );\n\n    const renderSelectionActions = () => {\n        if (!selectedItems.length) {\n            if (!showOptionsForNoSelection) {\n                return null;\n            }\n            return (\n                <>\n                    <CreateNewFolderButton />\n                    {isEditEnabled && <CreateNewFileButton />}\n                    {isDesktop && (\n                        <>\n                            <Vr />\n                            <UploadFolderButton />\n                            <UploadFileButton />\n                        </>\n                    )}\n                    <Vr />\n                    <ShareFileButton shareId={shareId} />\n                </>\n            );\n        }\n\n        return (\n            <>\n                <PreviewButton selectedLinks={selectedItems} />\n                <DownloadButton selectedLinks={selectedItems} />\n                {isNarrow ? (\n                    <ActionsDropdown shareId={shareId} selectedLinks={selectedItems} />\n                ) : (\n                    <>\n                        <ShareLinkButton selectedLinks={selectedItems} />\n                        <Vr />\n                        <MoveToFolderButton shareId={shareId} selectedLinks={selectedItems} />\n                        <RenameButton selectedLinks={selectedItems} />\n                        <DetailsButton selectedLinks={selectedItems} />\n                        <Vr />\n                        <MoveToTrashButton selectedLinks={selectedItems} />\n                    </>\n                )}\n            </>\n        );\n    };\n\n    return (\n        <Toolbar>\n            {renderSelectionActions()}\n            <span className=\"mlauto flex flex-nowrap\">\n                <LayoutButton />\n            </span>\n        </Toolbar>\n    );\n};\n\nexport default DriveToolbar;\n","import { useEffect } from 'react';\n\nimport { PrivateMainArea, Toolbar } from '@proton/components';\nimport { LinkURLType, RESPONSE_CODE } from '@proton/shared/lib/drive/constants';\n\nimport useActiveShare from '../../../hooks/drive/useActiveShare';\nimport useNavigate from '../../../hooks/drive/useNavigate';\nimport { useFolderView } from '../../../store';\nimport DriveBreadcrumbs from '../../DriveBreadcrumbs';\nimport { FileBrowserStateProvider } from '../../FileBrowser';\nimport UploadDragDrop from '../../uploads/UploadDragDrop/UploadDragDrop';\nimport Drive from './Drive';\nimport DriveToolbar from './DriveToolbar';\n\nexport type DriveSectionRouteProps = { shareId?: string; type?: LinkURLType; linkId?: string };\n\nfunction DriveView() {\n    const { activeFolder } = useActiveShare();\n    const { navigateToRoot, navigateToLink } = useNavigate();\n\n    const folderView = useFolderView(activeFolder);\n\n    useEffect(() => {\n        if (folderView.error) {\n            const code = folderView.error.data?.Code;\n            if (code === RESPONSE_CODE.INVALID_LINK_TYPE) {\n                navigateToLink(activeFolder.shareId, activeFolder.linkId, true);\n            } else if (code === RESPONSE_CODE.NOT_FOUND || code === RESPONSE_CODE.INVALID_ID) {\n                navigateToRoot();\n            } else {\n                throw folderView.error;\n            }\n        }\n    }, [folderView.error]);\n\n    return (\n        <FileBrowserStateProvider itemIds={folderView.items.map(({ linkId }) => linkId)}>\n            <UploadDragDrop className=\"flex flex-column flex-nowrap flex-item-fluid\">\n                {activeFolder ? <DriveToolbar shareId={activeFolder.shareId} items={folderView.items} /> : <Toolbar />}\n                <PrivateMainArea hasToolbar className=\"flex-no-min-children flex-column flex-nowrap\">\n                    <div className=\"max-w100 pt0-5 pb0-5 pl0-75 pr0-75 border-bottom section--header\">\n                        {activeFolder && <DriveBreadcrumbs activeFolder={activeFolder} />}\n                    </div>\n                    {activeFolder && <Drive activeFolder={activeFolder} folderView={folderView} />}\n                </PrivateMainArea>\n            </UploadDragDrop>\n        </FileBrowserStateProvider>\n    );\n}\n\nexport default DriveView;\n","import { c } from 'ttag';\n\nimport corruptedPreviewSvg from '@proton/styles/assets/img/errors/broken-image.svg';\nimport unsupportedPreviewSvg from '@proton/styles/assets/img/errors/preview-unavailable.svg';\n\nimport { PrimaryButton } from '../../components';\nimport { classnames } from '../../helpers';\nimport { useActiveBreakpoint } from '../../hooks';\n\ninterface Props {\n    type?: 'file' | 'image' | 'video' | 'audio';\n    onDownload?: () => void;\n}\n\nconst UnsupportedPreview = ({ onDownload, type = 'file' }: Props) => {\n    const { isNarrow } = useActiveBreakpoint();\n\n    return (\n        <div className=\"absolute-center text-center w100 pl1 pr1\">\n            <img\n                className=\"mb1 w80p\"\n                src={type === 'file' ? unsupportedPreviewSvg : corruptedPreviewSvg}\n                alt={c('Info').t`Unsupported file`}\n            />\n\n            <h2 className={classnames(['p0-25 text-bold', isNarrow && 'h3'])}>{c('Info').t`No preview available`}</h2>\n\n            {onDownload && (\n                <PrimaryButton size={!isNarrow ? 'large' : undefined} className=\"text-bold\" onClick={onDownload}>{c(\n                    'Action'\n                ).t`Download`}</PrimaryButton>\n            )}\n        </div>\n    );\n};\n\nexport default UnsupportedPreview;\n","import { useEffect, useState } from 'react';\n\nimport UnsupportedPreview from './UnsupportedPreview';\n\ninterface Props {\n    mimeType: string;\n    contents?: Uint8Array[];\n    onDownload?: () => void;\n}\n\nconst AudioPreview = ({ contents, mimeType, onDownload }: Props) => {\n    const [url, setUrl] = useState<string>();\n    const [error, setError] = useState(false);\n\n    useEffect(() => {\n        const newUrl = URL.createObjectURL(new Blob(contents, { type: mimeType }));\n        setUrl(newUrl);\n        return () => {\n            if (newUrl) {\n                URL.revokeObjectURL(newUrl);\n            }\n        };\n    }, [contents]);\n\n    const handleBrokenAudio = () => {\n        setError(true);\n    };\n\n    if (error) {\n        return (\n            <div className=\"flex flex-item-fluid-auto relative\">\n                <UnsupportedPreview onDownload={onDownload} type=\"audio\" />\n            </div>\n        );\n    }\n    return (\n        <div className=\"flex w100 h100\">\n            <div className=\"mauto w50\">\n                <audio className=\"w100\" onError={handleBrokenAudio} src={url} controls />\n            </div>\n        </div>\n    );\n};\n\nexport default AudioPreview;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\n\nimport { AlertModal, ModalProps } from '../../components';\n\ninterface Props extends ModalProps {\n    isSaving?: boolean;\n    handleDiscard?: () => void;\n}\n\nconst CloseModal = ({ isSaving, handleDiscard, ...rest }: Props) => {\n    const { onClose } = rest;\n\n    if (isSaving) {\n        return (\n            <AlertModal\n                title={c('Title').t`Your changes are not synced yet`}\n                buttons={[<Button onClick={onClose}>{c('Action').t`Cancel`}</Button>]}\n                {...rest}\n            >\n                {c('Info').t`Please wait till your changes are synced with the server.`}\n            </AlertModal>\n        );\n    }\n\n    const handleClose = () => {\n        handleDiscard?.();\n        onClose?.();\n    };\n\n    return (\n        <AlertModal\n            title={c('Title').t`Are you sure you want to close the preview?`}\n            buttons={[\n                <Button color=\"danger\" onClick={handleClose}>{c('Action').t`Discard`}</Button>,\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,\n            ]}\n            {...rest}\n        >\n            {c('Info').t`All your changes will be lost.`}\n            <br />\n            {c('Info').t`Are you sure you want to discard your changes?`}\n        </AlertModal>\n    );\n};\n\nexport default CloseModal;\n","import { ReactNode, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\n\nimport { useLoading } from '../../';\nimport { FileIcon, FileNameDisplay, Icon } from '../../components';\n\nconst SHARED_STATUS_TO_COLOR = {\n    '': undefined,\n    shared: 'color-info',\n    inactive: 'color-weak',\n};\n\nexport type SharedStatus = '' | 'shared' | 'inactive';\n\ninterface Props {\n    name?: string;\n    mimeType?: string;\n    sharedStatus?: SharedStatus;\n    signatureStatus?: ReactNode;\n    isDirty?: boolean;\n    onClose?: () => void;\n    onDownload?: () => void;\n    onSave?: () => Promise<void>;\n    onDetail?: () => void;\n    onShare?: () => void;\n    children?: ReactNode;\n}\n\nconst Header = ({\n    mimeType,\n    name,\n    sharedStatus,\n    signatureStatus,\n    isDirty,\n    onClose,\n    onDownload,\n    onSave,\n    onDetail,\n    onShare,\n    children,\n}: Props) => {\n    const [isSaving, withSaving] = useLoading();\n    const [saveError, setSaveError] = useState();\n\n    const handleSave = () => {\n        if (!onSave) {\n            return;\n        }\n        withSaving(\n            onSave().catch((err) => {\n                setSaveError(err?.message || err?.toString?.());\n            })\n        );\n    };\n\n    return (\n        <div className=\"flex flex-justify-space-between flex-align-items-center p2 relative\">\n            <div className=\"file-preview-filename flex flex-align-items-center flex-nowrap\">\n                {mimeType && <FileIcon mimeType={mimeType} className=\"mr0-5\" />}\n                <FileNameDisplay text={name} />\n                {signatureStatus}\n            </div>\n            {children}\n            <div className=\"flex flex-align-items-center\">\n                {onDownload && (\n                    <Button\n                        icon\n                        shape=\"ghost\"\n                        title={c('Action').t`Download`}\n                        onClick={onDownload}\n                        className=\"ml0-5\"\n                        data-testid=\"preview:button:download\"\n                    >\n                        <Icon name=\"arrow-down-line\" size={20} alt={c('Action').t`Download`} />\n                    </Button>\n                )}\n                {onSave && (\n                    <Button\n                        icon\n                        shape=\"ghost\"\n                        title={\n                            saveError\n                                ? c('Action').t`Try to save again. Saving failed due to: ${saveError}`\n                                : c('Action').t`Save`\n                        }\n                        onClick={handleSave}\n                        className=\"ml0-5\"\n                        data-testid=\"preview:button:save\"\n                        loading={isSaving}\n                        disabled={!isDirty}\n                    >\n                        <Icon\n                            name={saveError ? 'exclamation-circle-filled' : 'arrow-up-line'}\n                            size={20}\n                            alt={c('Action').t`Save`}\n                        />\n                    </Button>\n                )}\n                {onDetail && (\n                    <Button\n                        icon\n                        shape=\"ghost\"\n                        title={c('Action').t`Details`}\n                        onClick={onDetail}\n                        className=\"ml0-5 no-mobile\"\n                        data-testid=\"preview:button:details\"\n                    >\n                        <Icon name=\"info-circle\" size={20} alt={c('Action').t`Details`} />\n                    </Button>\n                )}\n                {onShare && (\n                    <Button\n                        icon\n                        shape=\"ghost\"\n                        title={sharedStatus === '' ? c('Action').t`Share via link` : c('Action').t`Sharing options`}\n                        onClick={onShare}\n                        className=\"ml0-5 no-mobile\"\n                        data-testid=\"preview:button:share\"\n                    >\n                        <Icon\n                            name=\"link\"\n                            size={20}\n                            alt={sharedStatus === '' ? c('Action').t`Share via link` : c('Action').t`Sharing options`}\n                            className={SHARED_STATUS_TO_COLOR[sharedStatus || '']}\n                        />\n                    </Button>\n                )}\n                {onClose && (\n                    <Button\n                        icon\n                        shape=\"ghost\"\n                        title={c('Action').t`Close`}\n                        onClick={onClose}\n                        className=\"ml0-5\"\n                        data-testid=\"preview:button:close\"\n                    >\n                        <Icon name=\"cross\" size={20} alt={c('Action').t`Close`} />\n                    </Button>\n                )}\n            </div>\n        </div>\n    );\n};\n\nexport default Header;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { classnames } from '@proton/components';\n\nimport Icon from '../../components/icon/Icon';\n\ninterface Props {\n    className?: string;\n    scale: number;\n    onZoomIn: () => void;\n    onZoomOut: () => void;\n    onReset: () => void;\n}\n\nconst ZoomControl = ({ className, scale, onZoomIn, onZoomOut, onReset }: Props) => {\n    const isZoomOutDisabled = scale <= 0.005;\n    const isZoomInDisabled = scale >= 10;\n\n    const displayedZoomValueInPercent = `${Math.round(scale * 100)}%`;\n\n    return (\n        <div className={classnames(['w100 p2 flex', className])}>\n            <div className=\"mxauto flex flex-align-items-center\">\n                <Button\n                    icon\n                    shape=\"ghost\"\n                    disabled={isZoomOutDisabled}\n                    onClick={onZoomOut}\n                    title={c('Action').t`Zoom out`}\n                >\n                    <Icon name=\"minus\" size={12} alt={c('Action').t`Zoom out`} />\n                </Button>\n                <Button shape=\"ghost\" title={c('Action').t`Fit to window`} className=\"ml0-5 mr0-5\" onClick={onReset}>\n                    <span>{displayedZoomValueInPercent}</span>\n                </Button>\n                <Button\n                    icon\n                    shape=\"ghost\"\n                    disabled={isZoomInDisabled}\n                    onClick={onZoomIn}\n                    title={c('Action').t`Zoom in`}\n                >\n                    <Icon name=\"plus\" size={12} alt={c('Action').t`Zoom in`} />\n                </Button>\n            </div>\n        </div>\n    );\n};\n\nexport default ZoomControl;\n","import { useEffect, useRef, useState } from 'react';\n\nimport DOMPurify from 'dompurify';\nimport { c } from 'ttag';\n\nimport { stringToUint8Array, uint8ArrayToString } from '@proton/shared/lib/helpers/encoding';\nimport { isSVG } from '@proton/shared/lib/helpers/mimetype';\n\nimport { classnames } from '../..';\nimport useElementRect from '../../hooks/useElementRect';\nimport UnsupportedPreview from './UnsupportedPreview';\nimport ZoomControl from './ZoomControl';\n\ninterface Props {\n    mimeType: string;\n    onDownload?: () => void;\n    contents?: Uint8Array[];\n    placeholderSrc?: string;\n    isLoading: boolean;\n}\n\nconst FALLBACK_IMAGE_DIMENSION_VALUE = window.innerHeight / 2;\n\n// These are just arbitrary numbers to keep image reasonable size\n// on giant screens when we don't have information about image\n// dimensions\nconst DEFAULT_IMAGE_DIMENSION_LIMIT_WIDTH = 2400;\nconst DEFAULT_IMAGE_DIMENSION_LIMIT_HEIGHT = 1400;\n\n/*\n * Svg image dimension are 0 in Firefox. For these cases fallback values\n * will be used, so the image preview is visible.\n * https://bugzilla.mozilla.org/show_bug.cgi?id=1328124\n */\nfunction getImageNaturalDimensions(imageElement: HTMLImageElement | null) {\n    return {\n        height: imageElement?.naturalHeight || FALLBACK_IMAGE_DIMENSION_VALUE,\n        width: imageElement?.naturalWidth || FALLBACK_IMAGE_DIMENSION_VALUE,\n    };\n}\n\n/**\n * SVG can contain nasty scripts. We do have security headers set but attacker\n * can overcome it by asking user to open the previewed image in the new tab,\n * where browsers don't check headers and allow scripts from the SVG.\n * One option would be to render it as PNG, but zooming or rescaling the window\n * would mean to redraw. Better to keep SVG then. Sanitizing small SVGs takes\n * milliseconds, bigger ones (MBs) under second. Only super huge ones takes even\n * 10 seconds on slow computer as is mine, but we talk about huge SVGs as 30 MB.\n * Because such SVG is more edge case, we can live with that.\n */\nfunction sanitizeSVG(contents: Uint8Array[]): Uint8Array[] {\n    const contentsString = contents.map(uint8ArrayToString).join('');\n    const sanitzedSVG = DOMPurify.sanitize(contentsString);\n    return [stringToUint8Array(sanitzedSVG)];\n}\n\nconst ImagePreview = ({ isLoading = false, mimeType, contents, onDownload, placeholderSrc }: Props) => {\n    const imageRef = useRef<HTMLImageElement>(null);\n    const containerRef = useRef<HTMLDivElement>(null);\n    const containerBounds = useElementRect(containerRef);\n\n    const [error, setError] = useState(false);\n    const [thumbnailScale, setThumbnailScale] = useState(0);\n    const [scale, setScale] = useState(0);\n    const [imageData, setImageData] = useState({\n        src: '',\n    });\n    const [ready, setReady] = useState(false);\n\n    const handleZoomOut = () => setScale((zoom) => (zoom ? zoom * 0.9 : 1));\n    const handleZoomIn = () => setScale((zoom) => (zoom ? zoom * 1.1 : 1));\n    const fitToContainer = () => {\n        if (!imageRef.current || !containerBounds) {\n            return;\n        }\n\n        const heightLimit = Math.min(containerBounds.height, DEFAULT_IMAGE_DIMENSION_LIMIT_HEIGHT);\n        const widthLimit = Math.min(containerBounds.width, DEFAULT_IMAGE_DIMENSION_LIMIT_WIDTH);\n\n        const dimensions = getImageNaturalDimensions(imageRef.current);\n        const heightRatio = heightLimit / dimensions.height;\n        const widthRatio = widthLimit / dimensions.width;\n\n        const scale = Math.min(heightRatio, widthRatio);\n\n        if (isLoading) {\n            setThumbnailScale(scale);\n        } else {\n            setScale(scale);\n        }\n    };\n\n    const handleBrokenImage = () => {\n        if (!error) {\n            setError(true);\n        }\n    };\n\n    const dimensions = getImageNaturalDimensions(imageRef.current);\n    const scaledDimensions = {\n        height: dimensions.height * (scale || thumbnailScale),\n        width: dimensions.width * (scale || thumbnailScale),\n    };\n\n    const styles = isLoading ? {} : scaledDimensions;\n    const shouldHideZoomControls = isLoading || !Boolean(scale);\n\n    useEffect(() => {\n        if (error) {\n            setError(false);\n        }\n\n        if (!contents) {\n            setImageData({ src: '' });\n            return;\n        }\n\n        const data = isSVG(mimeType) ? sanitizeSVG(contents) : contents;\n        const blob = new Blob(data, { type: mimeType });\n        const srcUrl = URL.createObjectURL(blob);\n\n        setImageData({\n            src: srcUrl,\n        });\n\n        // Load image before rendering\n        const buffer = new Image();\n        buffer.onload = () => {\n            setReady(true);\n        };\n        buffer.src = srcUrl;\n\n        return () => {\n            if (srcUrl) {\n                URL.revokeObjectURL(srcUrl);\n            }\n        };\n    }, [contents, mimeType]);\n\n    return (\n        <>\n            <div ref={containerRef} className=\"file-preview-container\">\n                {error ? (\n                    <UnsupportedPreview onDownload={onDownload} type=\"image\" />\n                ) : (\n                    <div\n                        className=\"flex-no-min-children mauto relative\"\n                        style={{\n                            ...scaledDimensions,\n                            // Add checkered background to override any theme\n                            // so transparent images are better visible.\n                            background: isLoading\n                                ? ''\n                                : 'repeating-conic-gradient(#606060 0% 25%, transparent 0% 50%) 50% / 20px 20px',\n                            overflow: 'hidden',\n                        }}\n                    >\n                        {!isLoading && ready && (\n                            <img\n                                ref={imageRef}\n                                onLoad={() => fitToContainer()}\n                                onError={handleBrokenImage}\n                                className={classnames(['file-preview-image file-preview-image-full-size'])}\n                                style={styles}\n                                src={imageData.src}\n                                alt={c('Info').t`Preview`}\n                            />\n                        )}\n                        <img\n                            ref={imageRef}\n                            onLoad={() => fitToContainer()}\n                            onError={handleBrokenImage}\n                            className={classnames(['file-preview-image', ready && 'hide'])}\n                            style={{\n                                // Scaling up the image to hide its edges that become\n                                // transparent when blurred\n                                transform: 'scale(1.1)',\n                                filter: 'blur(5px)',\n                                ...scaledDimensions,\n                            }}\n                            src={placeholderSrc}\n                            alt={c('Info').t`Preview`}\n                        />\n                    </div>\n                )}\n            </div>\n\n            {!error && (\n                <ZoomControl\n                    className={shouldHideZoomControls ? 'visibility-hidden' : ''}\n                    onReset={fitToContainer}\n                    scale={scale}\n                    onZoomIn={handleZoomIn}\n                    onZoomOut={handleZoomOut}\n                />\n            )}\n        </>\n    );\n};\n\nexport default ImagePreview;\n","import { useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\ninterface Props {\n    filename?: string;\n    contents?: Uint8Array[];\n}\nconst PDFPreview = ({ filename = 'preview.pdf', contents }: Props) => {\n    const [url, setUrl] = useState<string>();\n\n    useEffect(() => {\n        const newUrl = URL.createObjectURL(new Blob(contents, { type: 'application/pdf' }));\n        setUrl(newUrl);\n        return () => {\n            if (newUrl) {\n                URL.revokeObjectURL(newUrl);\n            }\n        };\n    }, [contents]);\n\n    return (\n        <>\n            {url && (\n                <object\n                    data={url}\n                    className=\"w100 flex-no-min-children flex-item-fluid-auto flex-column-reverse\"\n                    type=\"application/pdf\"\n                    title={filename}\n                >\n                    <embed src={url} className=\"flex\" type=\"application/pdf\" />\n                    <p className=\"mauto\">{c('Info')\n                        .t`This browser does not support previewing PDF documents. Please download the file.`}</p>\n                </object>\n            )}\n        </>\n    );\n};\n\nexport default PDFPreview;\n","import { c } from 'ttag';\n\nimport { CircleLoader } from '@proton/atoms';\n\nimport { TextLoader } from '../../components';\n\nconst PreviewLoader = () => {\n    return (\n        <div className=\"file-preview-container\">\n            <div className=\"absolute-center text-center w100\">\n                <CircleLoader size=\"large\" />\n                <TextLoader>{c('Info').t`Loading preview`}</TextLoader>\n            </div>\n        </div>\n    );\n};\n\nexport default PreviewLoader;\n","import { ReactNode } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Icon, PrimaryButton } from '../../components';\nimport { classnames } from '../../helpers';\nimport { useActiveBreakpoint } from '../../hooks';\n\nconst SignatureIssue = ({\n    signatureConfirmation,\n    onClick,\n}: {\n    signatureConfirmation: ReactNode;\n    onClick: () => void;\n}) => {\n    const { isNarrow } = useActiveBreakpoint();\n\n    return (\n        <div className=\"file-preview-container\">\n            <div className=\"absolute-center w100\">\n                <div className={classnames(['mlauto mrauto', isNarrow ? 'w300p' : 'w500p'])}>\n                    <div className=\"text-center\">\n                        <Icon name=\"lock-exclamation-filled\" size={60} className=\"color-danger\" />\n                    </div>\n                    <div className=\"mt1 mb2\">{signatureConfirmation}</div>\n                </div>\n                <div className=\"text-center\">\n                    <PrimaryButton size={!isNarrow ? 'large' : undefined} className=\"text-bold\" onClick={onClick}>\n                        {c('Action').t`Show preview`}\n                    </PrimaryButton>\n                </div>\n            </div>\n        </div>\n    );\n};\n\nexport default SignatureIssue;\n","import { useState } from 'react';\n\nimport mergeUint8Arrays from '@proton/utils/mergeUint8Arrays';\n\ninterface Props {\n    contents?: Uint8Array[];\n    onNewContents?: (content: Uint8Array[]) => void;\n}\n\nconst TextPreview = ({ contents = [], onNewContents }: Props) => {\n    const string = new TextDecoder().decode(mergeUint8Arrays(contents));\n\n    const [value, setValue] = useState(string);\n\n    const handleChange = (event: any) => {\n        const newValue = event.target.value as string;\n        setValue(newValue);\n        const content = Uint8Array.from(newValue.split('').map((x) => x.charCodeAt(0)));\n        onNewContents?.([content]);\n    };\n\n    return (\n        <div className=\"file-preview-container\">\n            {onNewContents ? (\n                <textarea className=\"file-preview-text\" value={value} onChange={handleChange} />\n            ) : (\n                <div className=\"file-preview-text\">{value}</div>\n            )}\n        </div>\n    );\n};\n\nexport default TextPreview;\n","import { useEffect, useRef, useState } from 'react';\n\nimport useElementRect from '../../hooks/useElementRect';\nimport UnsupportedPreview from './UnsupportedPreview';\n\ninterface Props {\n    mimeType: string;\n    contents?: Uint8Array[];\n    onDownload?: () => void;\n}\n\nconst VideoPreview = ({ contents, mimeType, onDownload }: Props) => {\n    const videoRef = useRef<HTMLVideoElement>(null);\n    const containerRef = useRef<HTMLDivElement>(null);\n    const containerBounds = useElementRect(containerRef);\n    const [url, setUrl] = useState<string>();\n    const [scale, setScale] = useState(1);\n    const [error, setError] = useState(false);\n\n    useEffect(() => {\n        const newUrl = URL.createObjectURL(new Blob(contents, { type: mimeType }));\n        setUrl(newUrl);\n        return () => {\n            if (newUrl) {\n                URL.revokeObjectURL(newUrl);\n            }\n        };\n    }, [contents]);\n\n    const fitToContainer = () => {\n        if (!videoRef.current || !containerBounds) {\n            return;\n        }\n\n        const heightRatio = containerBounds.height / videoRef.current.videoHeight;\n        const widthRatio = containerBounds.width / videoRef.current.videoWidth;\n        const scale = Math.min(1, heightRatio, widthRatio);\n        setScale(scale);\n    };\n\n    const handleBrokenVideo = () => {\n        setError(true);\n    };\n\n    const scaledDimensions = !videoRef.current?.videoHeight\n        ? {}\n        : {\n              height: videoRef.current.videoHeight * scale,\n              width: videoRef.current.videoWidth * scale,\n          };\n\n    if (error) {\n        return (\n            <div className=\"flex flex-item-fluid-auto relative\">\n                <UnsupportedPreview onDownload={onDownload} type=\"video\" />\n            </div>\n        );\n    }\n    return (\n        <div ref={containerRef} className=\"flex w100 h100\">\n            <div className=\"mauto\">\n                {/* eslint-disable-next-line */}\n                <video\n                    ref={videoRef}\n                    onLoadedMetadata={fitToContainer}\n                    onError={handleBrokenVideo}\n                    src={url}\n                    style={scaledDimensions}\n                    controls\n                />\n            </div>\n        </div>\n    );\n};\n\nexport default VideoPreview;\n","import { ReactNode, Ref, forwardRef, useEffect, useRef, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport busy from '@proton/shared/lib/busy';\nimport {\n    isAudio,\n    isPDF,\n    isSupportedImage,\n    isSupportedText,\n    isSupportedVideo,\n} from '@proton/shared/lib/helpers/mimetype';\nimport { isPreviewAvailable } from '@proton/shared/lib/helpers/preview';\n\nimport { useFocusTrap, useModalState } from '../../components';\nimport { useBeforeUnload, useCombinedRefs, useHotkeys, useLoading } from '../../hooks';\nimport AudioPreview from './AudioPreview';\nimport CloseModal from './CloseModal';\nimport Header, { SharedStatus } from './Header';\nimport ImagePreview from './ImagePreview';\nimport PDFPreview from './PDFPreview';\nimport PreviewLoader from './PreviewLoader';\nimport SignatureIssue from './SignatureIssue';\nimport TextPreview from './TextPreview';\nimport UnsupportedPreview from './UnsupportedPreview';\nimport VideoPreview from './VideoPreview';\n\ninterface Props {\n    isMetaLoading?: boolean;\n    isLoading: boolean;\n\n    fileName?: string;\n    mimeType?: string;\n    fileSize?: number;\n    navigationControls?: ReactNode;\n    contents?: Uint8Array[];\n    sharedStatus?: SharedStatus;\n    signatureStatus?: ReactNode;\n    signatureConfirmation?: ReactNode;\n    imgThumbnailUrl?: string;\n    onClose?: () => void;\n    onDownload?: () => void;\n    onSave?: (content: Uint8Array[]) => Promise<void>;\n    onDetail?: () => void;\n    onShare?: () => void;\n}\n\nconst FilePreview = (\n    {\n        isMetaLoading = false,\n        isLoading = false,\n\n        contents,\n        fileName,\n        mimeType,\n        fileSize,\n        navigationControls,\n        sharedStatus,\n        signatureStatus,\n        signatureConfirmation,\n        onClose,\n        onDownload,\n        onSave,\n        onDetail,\n        onShare,\n        imgThumbnailUrl,\n    }: Props,\n    ref: Ref<HTMLDivElement>\n) => {\n    const rootRef = useRef<HTMLDivElement>(null);\n    const combinedRefs = useCombinedRefs<HTMLDivElement>(ref, rootRef);\n    const focusTrapProps = useFocusTrap({\n        rootRef,\n    });\n    const [forcePreview, setForcePreview] = useState(false);\n\n    const [isSaving, withSaving] = useLoading(false);\n    const [isDirty, setIsDirty] = useState<boolean>(false);\n    const [newContent, setNewContent] = useState<Uint8Array[]>([]);\n\n    // Block browser from leaving and do not refresh page with unsaved document.\n    useBeforeUnload(isDirty);\n    useEffect(() => {\n        if (!isDirty) {\n            return;\n        }\n\n        const unregister = busy.register();\n        return () => {\n            unregister();\n        };\n    }, [isDirty]);\n\n    // Reset when another content is loaded (for example after going to the next item through navigation).\n    useEffect(() => {\n        setIsDirty(false);\n    }, [contents]);\n\n    const [closeModalProps, setCloseModalOpen] = useModalState();\n    const handleClose = () => {\n        if (!isDirty) {\n            onClose?.();\n            return;\n        }\n\n        setCloseModalOpen(true);\n    };\n\n    // There is an issue saving empty file at this moment. Lets not allow it for now.\n    const handleSave = onSave\n        ? async () => {\n              return withSaving(onSave(newContent)).then(() => {\n                  // Compare to latest changes and unset dirty flag only if the user\n                  // didn't do any extra modifications after saving the file.\n                  setNewContent((latestNewContent) => {\n                      if (latestNewContent === newContent) {\n                          setIsDirty(false);\n                          setCloseModalOpen(false);\n                      }\n                      return latestNewContent;\n                  });\n              });\n          }\n        : undefined;\n\n    useHotkeys(rootRef, [\n        [\n            'Escape',\n            (e) => {\n                e.stopPropagation();\n                handleClose();\n            },\n        ],\n    ]);\n\n    const renderPreview = () => {\n        if (!imgThumbnailUrl && isLoading) {\n            return <PreviewLoader />;\n        }\n\n        if (signatureConfirmation && !forcePreview) {\n            return (\n                <SignatureIssue signatureConfirmation={signatureConfirmation} onClick={() => setForcePreview(true)} />\n            );\n        }\n\n        if (\n            !mimeType ||\n            (!contents && !imgThumbnailUrl && !isSupportedText(mimeType)) ||\n            !isPreviewAvailable(mimeType, fileSize)\n        ) {\n            return (\n                <div className=\"file-preview-container\">\n                    <UnsupportedPreview onDownload={onDownload} />\n                </div>\n            );\n        }\n\n        if (isSupportedImage(mimeType)) {\n            return (\n                <ImagePreview\n                    isLoading={isLoading}\n                    placeholderSrc={imgThumbnailUrl}\n                    contents={contents}\n                    mimeType={mimeType}\n                    onDownload={onDownload}\n                />\n            );\n        }\n        if (isSupportedVideo(mimeType, fileSize)) {\n            return <VideoPreview contents={contents} mimeType={mimeType} onDownload={onDownload} />;\n        }\n        if (isAudio(mimeType)) {\n            return <AudioPreview contents={contents} mimeType={mimeType} onDownload={onDownload} />;\n        }\n        if (isSupportedText(mimeType)) {\n            return (\n                <TextPreview\n                    contents={contents}\n                    onNewContents={\n                        onSave\n                            ? (content: Uint8Array[]) => {\n                                  setIsDirty(true);\n                                  setNewContent(content);\n                              }\n                            : undefined\n                    }\n                />\n            );\n        }\n        if (isPDF(mimeType)) {\n            return <PDFPreview contents={contents} filename={fileName} />;\n        }\n    };\n\n    return (\n        <div className=\"file-preview ui-prominent\" ref={combinedRefs} {...focusTrapProps}>\n            <Header\n                mimeType={mimeType}\n                name={fileName}\n                sharedStatus={sharedStatus}\n                signatureStatus={signatureStatus}\n                isDirty={\n                    isDirty &&\n                    // There is an issue saving empty file at this moment. Lets not allow it for now.\n                    newContent.some((item) => item.length > 0)\n                }\n                onClose={handleClose}\n                onDownload={onDownload}\n                onSave={handleSave}\n                onDetail={onDetail}\n                onShare={onShare}\n            >\n                {isDirty ? (\n                    <div className=\"flex flex-align-items-center absolute-center\">{c('Info').t`Unsaved changes`}</div>\n                ) : (\n                    navigationControls\n                )}\n            </Header>\n            {isMetaLoading ? <PreviewLoader /> : renderPreview()}\n            <CloseModal {...closeModalProps} handleDiscard={onClose} isSaving={isSaving} />\n        </div>\n    );\n};\n\nexport default forwardRef(FilePreview);\n","import { RefObject } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\n\nimport Icon from '../../components/icon/Icon';\nimport { useHotkeys } from '../../hooks';\n\ninterface Props {\n    current: number;\n    total: number;\n    rootRef: RefObject<HTMLDivElement>;\n    onNext: () => void;\n    onPrev: () => void;\n}\n\nconst NavigationControl = ({ current, total, rootRef, onNext, onPrev }: Props) => {\n    const isPrevDisabled = current === 1;\n    const isNextDisabled = current === total;\n\n    useHotkeys(rootRef, [\n        [\n            'ArrowLeft',\n            (e) => {\n                e.stopPropagation();\n                if (!isPrevDisabled) {\n                    onPrev();\n                }\n            },\n        ],\n        [\n            'ArrowRight',\n            (e) => {\n                e.stopPropagation();\n                if (!isNextDisabled) {\n                    onNext();\n                }\n            },\n        ],\n    ]);\n\n    return (\n        <div className=\"flex flex-align-items-center absolute-center\">\n            <Button\n                icon\n                shape=\"ghost\"\n                className=\"on-rtl-mirror\"\n                disabled={isPrevDisabled}\n                onClick={onPrev}\n                title={c('Action').t`Previous`}\n                data-testid=\"preview:button:previous\"\n            >\n                <Icon name=\"chevron-left\" size={16} alt={c('Action').t`Previous`} />\n            </Button>\n            <span className=\"ml0-5 mr0-5\">\n                <span>{current}</span>\n                <span className=\"ml0-25 mr0-25 color-weak text-sm\">{c('Info').t`of`}</span>\n                <span>{total}</span>\n            </span>\n            <Button\n                icon\n                shape=\"ghost\"\n                className=\"on-rtl-mirror\"\n                disabled={isNextDisabled}\n                onClick={onNext}\n                title={c('Action').t`Next`}\n                data-testid=\"preview:button:next\"\n            >\n                <Icon name=\"chevron-right\" size={16} alt={c('Action').t`Next`} />\n            </Button>\n        </div>\n    );\n};\n\nexport default NavigationControl;\n","import { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport { RouteComponentProps, useLocation } from 'react-router-dom';\n\nimport { FilePreview, NavigationControl, useModals } from '@proton/components';\nimport { HTTP_STATUS_CODE } from '@proton/shared/lib/constants';\nimport { RESPONSE_CODE } from '@proton/shared/lib/drive/constants';\n\nimport DetailsModal from '../components/DetailsModal';\nimport ShareLinkModal from '../components/ShareLinkModal/ShareLinkModal';\nimport { SignatureAlertBody } from '../components/SignatureAlert';\nimport SignatureIcon from '../components/SignatureIcon';\nimport useIsEditEnabled from '../components/sections/useIsEditEnabled';\nimport useActiveShare from '../hooks/drive/useActiveShare';\nimport useNavigate from '../hooks/drive/useNavigate';\nimport { DecryptedLink, useActions, useFileView } from '../store';\n// TODO: ideally not use here\nimport useSearchResults from '../store/_search/useSearchResults';\n\nconst getSharedStatus = (link?: DecryptedLink) => {\n    if (!link?.isShared) {\n        return '';\n    }\n    if (link?.shareUrl?.isExpired || link?.trashed) {\n        return 'inactive';\n    }\n    return 'shared';\n};\n\nexport default function PreviewContainer({ match }: RouteComponentProps<{ shareId: string; linkId: string }>) {\n    const { shareId, linkId } = match.params;\n    const { navigateToLink, navigateToSharedURLs, navigateToTrash, navigateToRoot, navigateToSearch } = useNavigate();\n    const { setFolder } = useActiveShare();\n    const [, setError] = useState();\n    const { createModal, removeModal } = useModals();\n    const { query: lastQuery } = useSearchResults();\n    const { saveFile } = useActions();\n\n    const isEditEnabled = useIsEditEnabled();\n\n    const referer = new URLSearchParams(useLocation().search).get('r');\n    const useNavigation =\n        !referer?.startsWith('/shared-urls') && !referer?.startsWith('/trash') && !referer?.startsWith('/search');\n\n    const { isLinkLoading, isContentLoading, error, link, contents, downloadFile, navigation } = useFileView(\n        shareId,\n        linkId,\n        useNavigation\n    );\n\n    // If the link is not type of file, probably user modified the URL.\n    useEffect(() => {\n        if (link && !link.isFile) {\n            navigateToLink(shareId, linkId, false);\n        }\n    }, [link?.isFile]);\n\n    useEffect(() => {\n        if (link) {\n            setFolder({ shareId, linkId: link.parentLinkId });\n        }\n    }, [shareId, link?.parentLinkId]);\n\n    useEffect(() => {\n        if (error) {\n            if (\n                // Block not found (storage response).\n                error.status === HTTP_STATUS_CODE.NOT_FOUND ||\n                // Meta data not found (API response).\n                error.data?.Code === RESPONSE_CODE.NOT_FOUND ||\n                error.data?.Code === RESPONSE_CODE.INVALID_ID\n            ) {\n                navigateToRoot();\n            } else {\n                setError(() => {\n                    throw error;\n                });\n            }\n        }\n    }, [error]);\n\n    const navigateToParent = useCallback(() => {\n        if (referer?.startsWith('/shared-urls')) {\n            navigateToSharedURLs();\n            return;\n        }\n        if (referer?.startsWith('/trash')) {\n            navigateToTrash();\n            return;\n        }\n        if (referer?.startsWith('/search')) {\n            if (lastQuery) {\n                navigateToSearch(lastQuery);\n                return;\n            }\n        }\n        if (link?.parentLinkId) {\n            navigateToLink(shareId, link.parentLinkId, false);\n        }\n    }, [link?.parentLinkId, shareId, referer]);\n\n    const onOpen = useCallback(\n        (linkId: string | undefined) => {\n            if (linkId) {\n                navigateToLink(shareId, linkId, true);\n            }\n        },\n        [shareId]\n    );\n\n    // Remember modal ID created by preview and close it together\n    // with closing the preview itself.\n    const modalId = useRef<string>();\n    useEffect(() => {\n        return () => {\n            if (modalId.current) {\n                removeModal(modalId.current);\n            }\n        };\n    }, []);\n\n    const openDetails = useCallback(() => {\n        createModal(<DetailsModal shareId={shareId} linkId={linkId} />);\n    }, [shareId, linkId]);\n\n    const openShareOptions = useCallback(() => {\n        createModal(<ShareLinkModal shareId={shareId} linkId={linkId} />);\n    }, [shareId, linkId]);\n\n    const signatureStatus = useMemo(() => {\n        if (!link) {\n            return;\n        }\n\n        return (\n            <SignatureIcon isFile={link.isFile} signatureIssues={link.signatureIssues} className=\"ml0-5 color-danger\" />\n        );\n    }, [link]);\n\n    const signatureConfirmation = useMemo(() => {\n        if (!link?.signatureIssues?.blocks) {\n            return;\n        }\n\n        return (\n            <SignatureAlertBody\n                signatureIssues={link.signatureIssues}\n                signatureAddress={link.signatureAddress}\n                isFile={link.isFile}\n                name={link.name}\n            />\n        );\n    }, [link]);\n\n    const handleSaveFile = useCallback(\n        (content: Uint8Array[]) => {\n            if (!link) {\n                return Promise.reject('missing link');\n            }\n\n            return saveFile(shareId, link.parentLinkId, link.name, link.mimeType, content);\n        },\n        [shareId, link?.name, link?.parentLinkId]\n    );\n\n    const rootRef = useRef<HTMLDivElement>(null);\n\n    return (\n        <FilePreview\n            isMetaLoading={isLinkLoading}\n            isLoading={isContentLoading}\n            contents={contents}\n            fileName={link?.name}\n            mimeType={link?.mimeType}\n            sharedStatus={getSharedStatus(link)}\n            fileSize={link?.size}\n            onClose={navigateToParent}\n            onDownload={downloadFile}\n            onSave={isEditEnabled ? handleSaveFile : undefined}\n            onDetail={openDetails}\n            onShare={isLinkLoading || !!link?.trashed ? undefined : openShareOptions}\n            imgThumbnailUrl={link?.cachedThumbnailUrl}\n            ref={rootRef}\n            navigationControls={\n                link &&\n                navigation && (\n                    <NavigationControl\n                        current={navigation.current}\n                        total={navigation.total}\n                        rootRef={rootRef}\n                        onPrev={() => onOpen?.(navigation.prevLinkId)}\n                        onNext={() => onOpen?.(navigation.nextLinkId)}\n                    />\n                )\n            }\n            signatureStatus={signatureStatus}\n            signatureConfirmation={signatureConfirmation}\n        />\n    );\n}\n","import { useEffect, useMemo, useRef, useState } from 'react';\nimport { Route, RouteComponentProps } from 'react-router';\n\nimport { useAppTitle } from '@proton/components';\nimport { LinkURLType } from '@proton/shared/lib/drive/constants';\n\nimport DriveView, { DriveSectionRouteProps } from '../components/sections/Drive/DriveView';\nimport useActiveShare, { DriveFolder } from '../hooks/drive/useActiveShare';\nimport { useFolderContainerTitle } from '../hooks/drive/useFolderContainerTitle';\nimport useNavigate from '../hooks/drive/useNavigate';\nimport { useDefaultShare, useDriveEventManager } from '../store';\nimport PreviewContainer from './PreviewContainer';\n\nexport default function FolderContainer({ match }: RouteComponentProps<DriveSectionRouteProps>) {\n    const { navigateToRoot } = useNavigate();\n    const { activeFolder, setFolder } = useActiveShare();\n    const lastFolderPromise = useRef<Promise<DriveFolder | undefined>>();\n    const [, setError] = useState();\n    const { getDefaultShare } = useDefaultShare();\n    useFolderContainerTitle({ params: match.params, setAppTitle: useAppTitle });\n    const events = useDriveEventManager();\n\n    const hasValidLinkType = (type: string) => {\n        return type === LinkURLType.FILE || type === LinkURLType.FOLDER;\n    };\n\n    const folderPromise = useMemo(async () => {\n        const { shareId, type, linkId } = match.params;\n\n        if (!shareId && !type && !linkId) {\n            const defaultShare = await getDefaultShare();\n            if (defaultShare) {\n                return { shareId: defaultShare.shareId, linkId: defaultShare.rootLinkId };\n            }\n            setError(() => {\n                // Throwing error in async function does not propagate it to\n                // the view. Therefore we need to use this setError hack.\n                throw new Error('Drive is not initilized, cache has been cleared unexpectedly');\n            });\n        } else if (!shareId || !hasValidLinkType(type as string) || !linkId) {\n            console.warn('Missing parameters, should be none or shareId/type/linkId');\n            navigateToRoot();\n        } else if (type === LinkURLType.FOLDER) {\n            return { shareId, linkId };\n        }\n        return lastFolderPromise.current;\n    }, [match.params.shareId, match.params.type, match.params.linkId]);\n\n    useEffect(() => {\n        folderPromise\n            .then((folder) => {\n                if (folder) {\n                    setFolder(folder);\n                }\n            })\n            .catch(console.warn);\n    }, [folderPromise]);\n\n    // In case we open preview, folder doesn't need to change.\n    lastFolderPromise.current = folderPromise;\n\n    const shouldRenderDriveView = Boolean(activeFolder.shareId && activeFolder.linkId);\n\n    useEffect(() => {\n        events.shares.startSubscription(activeFolder.shareId).catch(reportError);\n\n        return () => {\n            events.shares.pauseSubscription(activeFolder.shareId);\n        };\n    }, [activeFolder.shareId]);\n\n    return (\n        <>\n            {shouldRenderDriveView ? <DriveView /> : null}\n            <Route path={`/:shareId?/${LinkURLType.FILE}/:linkId?`} component={PreviewContainer} exact />\n        </>\n    );\n}\n","import { DriveSectionRouteProps } from '../../components/sections/Drive/DriveView';\nimport { useLinkName } from '../../store/_views/utils';\n\nexport const useFolderContainerTitle = ({\n    params,\n    setAppTitle,\n}: {\n    params: DriveSectionRouteProps;\n    setAppTitle: (title?: string) => void;\n}) => {\n    const name = useLinkName(params.shareId || '', params.linkId || '');\n    setAppTitle(name);\n};\n","import { useRef } from 'react';\n\nimport { c } from 'ttag';\n\nimport {\n    CollapsingBreadcrumbs,\n    FloatingButton,\n    Icon,\n    MainLogo,\n    ModalsChildren,\n    PrivateAppContainer,\n    PrivateMainArea,\n    SidebarPrimaryButton,\n    useActiveBreakpoint,\n    useToggle,\n} from '@proton/components';\nimport { getAppName } from '@proton/shared/lib/apps/helper';\nimport { APPS } from '@proton/shared/lib/constants';\n\nimport { ListView } from '../components/FileBrowser';\nimport { ListViewHeaderItem } from '../components/FileBrowser/interface';\nimport { DriveHeader } from '../components/layout/DriveHeader';\nimport DriveSidebar from '../components/layout/DriveSidebar/DriveSidebar';\nimport { DriveItem } from '../components/sections/Drive/Drive';\nimport { ModifiedCell, NameCell, SizeCell } from '../components/sections/FileBrowser/contentCells';\nimport headerItems from '../components/sections/FileBrowser/headerCells';\n\nconst desktopCells: React.FC<{ item: DriveItem }>[] = [NameCell, ModifiedCell, SizeCell];\nconst mobileCells = [NameCell];\n\nconst headerItemsDesktop: ListViewHeaderItem[] = [headerItems.name, headerItems.modificationDate, headerItems.size];\n\nconst headerItemsMobile: ListViewHeaderItem[] = [headerItems.name, headerItems.placeholder];\n\nconst DriveContainerBlurred = () => {\n    const scrollAreaRef = useRef<HTMLDivElement>(null);\n    const { state: expanded, toggle: toggleExpanded } = useToggle();\n    const appName = getAppName(APPS.PROTONDRIVE);\n    const { isDesktop } = useActiveBreakpoint();\n\n    const logo = <MainLogo to=\"/\" />;\n    const dummyUploadButton = (\n        <SidebarPrimaryButton className=\"no-mobile\">{c('Action').t`New upload`}</SidebarPrimaryButton>\n    );\n    const dummyFolderTitle = c('Title').t`My files`;\n\n    const header = (\n        <DriveHeader\n            logo={logo}\n            floatingPrimary={\n                <FloatingButton title={c('Action').t`New upload`}>\n                    <Icon size={24} name=\"plus\" className=\"mauto\" />\n                </FloatingButton>\n            }\n            isHeaderExpanded={expanded}\n            toggleHeaderExpanded={toggleExpanded}\n        />\n    );\n\n    const sidebar = (\n        <DriveSidebar\n            logo={logo}\n            primary={dummyUploadButton}\n            isHeaderExpanded={expanded}\n            toggleHeaderExpanded={toggleExpanded}\n        />\n    );\n\n    const items: DriveItem[] = [\n        {\n            id: 'dummy-link-1',\n            parentLinkId: '',\n            mimeType: 'text/plain',\n            name: 'Private files',\n            fileModifyTime: Date.now() / 1000,\n            trashed: null,\n            size: 1024 * 1024,\n            isFile: false,\n            hasThumbnail: false,\n        },\n        {\n            id: 'dummy-link-2',\n            parentLinkId: '',\n            mimeType: 'text/plain',\n            name: `Welcome to ${appName}.txt`,\n            fileModifyTime: Date.now() / 1000,\n            trashed: null,\n            size: 1024 * 1024,\n            isFile: true,\n            hasThumbnail: false,\n        },\n    ];\n\n    const headerItems = isDesktop ? headerItemsDesktop : headerItemsMobile;\n\n    const Cells = isDesktop ? desktopCells : mobileCells;\n\n    return (\n        <>\n            <ModalsChildren />\n            <PrivateAppContainer isBlurred header={header} sidebar={sidebar}>\n                <PrivateMainArea hasToolbar className=\"flex-no-min-children flex-column flex-nowrap\">\n                    <div className=\"max-w100 pt0-5 pb0-5 pl0-75 pr0-75 border-bottom\">\n                        <CollapsingBreadcrumbs\n                            breadcrumbs={[\n                                {\n                                    key: 'my-files',\n                                    text: c('Title').t`My files`,\n                                    noShrink: true,\n                                    highlighted: true,\n                                },\n                            ]}\n                        />\n                    </div>\n                    <ListView\n                        caption={dummyFolderTitle}\n                        Cells={Cells}\n                        headerItems={headerItems}\n                        items={items}\n                        loading={false}\n                        scrollAreaRef={scrollAreaRef}\n                    />\n                </PrivateMainArea>\n            </PrivateAppContainer>\n        </>\n    );\n};\n\nexport default DriveContainerBlurred;\n","import DriveOnboardingModal from '../components/onboarding/DriveOnboardingModal';\nimport DriveContainerBlurred from './DriveContainerBlurred';\n\ninterface Props {\n    onDone: () => void;\n}\n\nconst OnboardingContainer = ({ onDone }: Props) => {\n    return (\n        <>\n            <DriveContainerBlurred />\n            <DriveOnboardingModal open onDone={onDone} />\n        </>\n    );\n};\nexport default OnboardingContainer;\n","import { c } from 'ttag';\n\nimport useNavigate from '../../../../hooks/drive/useNavigate';\nimport { ContextMenuButton } from '../../ContextMenu';\n\ninterface Props {\n    shareId: string;\n    parentLinkId: string;\n    close: () => void;\n}\n\nexport default function GoToParent({ shareId, parentLinkId, close }: Props) {\n    const { navigateToLink } = useNavigate();\n\n    return (\n        <ContextMenuButton\n            testId=\"go-to-parent\"\n            icon=\"folder\"\n            name={c('Action').t`Go to parent`}\n            action={() => navigateToLink(shareId, parentLinkId, false)}\n            close={close}\n        />\n    );\n}\n","import { ContextSeparator } from '@proton/components';\n\nimport { DecryptedLink } from '../../../store';\nimport { ContextMenuProps } from '../../FileBrowser/interface';\nimport { DriveItemContextMenu } from '../Drive/DriveContextMenu';\nimport { GoToParent } from './ContextMenuButtons';\n\nexport function SearchItemContextMenu(\n    props: ContextMenuProps & {\n        shareId: string;\n        selectedLinks: DecryptedLink[];\n    }\n) {\n    const { shareId, selectedLinks, close } = props;\n\n    const isOnlyOneItem = selectedLinks.length === 1;\n\n    return (\n        <DriveItemContextMenu {...props}>\n            {isOnlyOneItem && (\n                <>\n                    <ContextSeparator />\n                    <GoToParent shareId={shareId} parentLinkId={selectedLinks[0].parentLinkId} close={close} />\n                </>\n            )}\n        </DriveItemContextMenu>\n    );\n}\n","import { useCallback, useMemo, useRef } from 'react';\n\nimport { c } from 'ttag';\n\nimport { useActiveBreakpoint } from '@proton/components';\n\nimport useDriveDragMove from '../../../hooks/drive/useDriveDragMove';\nimport useNavigate from '../../../hooks/drive/useNavigate';\nimport { EncryptedLink, LinkShareUrl, useSearchView, useThumbnailsDownload } from '../../../store';\nimport { SortField } from '../../../store/_views/utils/useSorting';\nimport FileBrowser, { Cells, GridHeader, useItemContextMenu, useSelection } from '../../FileBrowser';\nimport { BrowserItemId, FileBrowserBaseItem, ListViewHeaderItem } from '../../FileBrowser/interface';\nimport { GridViewItem } from '../FileBrowser/GridViewItemLink';\nimport { LocationCell, ModifiedCell, NameCell, SizeCell } from '../FileBrowser/contentCells';\nimport headerItems from '../FileBrowser/headerCells';\nimport { translateSortField } from '../SortDropdown';\nimport { getSelectedItems } from '../helpers';\nimport { SearchItemContextMenu } from './SearchItemContextMenu';\n\nexport interface SearchItem extends FileBrowserBaseItem {\n    activeRevision?: EncryptedLink['activeRevision'];\n    cachedThumbnailUrl?: string;\n    hasThumbnail: boolean;\n    isFile: boolean;\n    mimeType: string;\n    fileModifyTime: number;\n    name: string;\n    shareUrl?: LinkShareUrl;\n    signatureIssues?: any;\n    size: number;\n    trashed: number | null;\n    parentLinkId: string;\n}\n\ninterface Props {\n    shareId: string;\n    searchView: ReturnType<typeof useSearchView>;\n}\n\nconst { CheckboxCell, ContextMenuCell } = Cells;\n\nconst desktopCells: React.FC<{ item: SearchItem }>[] = [\n    CheckboxCell,\n    NameCell,\n    LocationCell,\n    ModifiedCell,\n    SizeCell,\n    ContextMenuCell,\n];\nconst mobileCells = [CheckboxCell, NameCell, ContextMenuCell];\n\nconst headerItemsDesktop: ListViewHeaderItem[] = [\n    headerItems.checkbox,\n    headerItems.name,\n    headerItems.location,\n    headerItems.modificationDate,\n    headerItems.size,\n    headerItems.placeholder,\n];\n\nconst headerItemsMobile: ListViewHeaderItem[] = [headerItems.checkbox, headerItems.name, headerItems.placeholder];\n\ntype SearchSortFields = Extract<SortField, SortField.name | SortField.fileModifyTime | SortField.size>;\nconst SORT_FIELDS: SearchSortFields[] = [SortField.name, SortField.size, SortField.fileModifyTime];\n\nexport const Search = ({ shareId, searchView }: Props) => {\n    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);\n\n    const browserItemContextMenu = useItemContextMenu();\n    const thumbnails = useThumbnailsDownload();\n    const { navigateToLink } = useNavigate();\n    const selectionControls = useSelection();\n    const { isDesktop } = useActiveBreakpoint();\n\n    const { layout, items, sortParams, setSorting, isLoading } = searchView;\n\n    const selectedItems = useMemo(\n        () => getSelectedItems(items, selectionControls!.selectedItemIds),\n        [items, selectionControls!.selectedItemIds]\n    );\n\n    const browserItems: SearchItem[] = items.map((item) => ({ ...item, id: item.linkId }));\n    const { getDragMoveControls } = useDriveDragMove(shareId, browserItems, selectionControls!.clearSelections);\n\n    /* eslint-disable react/display-name */\n    const GridHeaderComponent = useMemo(\n        () =>\n            ({ scrollAreaRef }: { scrollAreaRef: React.RefObject<HTMLDivElement> }) => {\n                const activeSortingText = translateSortField(sortParams.sortField);\n                return (\n                    <GridHeader\n                        isLoading={isLoading}\n                        sortFields={SORT_FIELDS}\n                        onSort={setSorting}\n                        sortField={sortParams.sortField}\n                        sortOrder={sortParams.sortOrder}\n                        itemCount={browserItems.length}\n                        onToggleAllSelected={selectionControls!.toggleAllSelected}\n                        scrollAreaRef={scrollAreaRef}\n                        activeSortingText={activeSortingText}\n                    />\n                );\n            },\n        [sortParams.sortField, sortParams.sortOrder, isLoading]\n    );\n\n    const handleItemRender = useCallback((item: SearchItem) => {\n        if (item.hasThumbnail && item.activeRevision && !item.cachedThumbnailUrl) {\n            thumbnails.addToDownloadQueue(shareId, item.id, item.activeRevision.id);\n        }\n    }, []);\n\n    const handleClick = useCallback(\n        (id: BrowserItemId) => {\n            const item = browserItems.find((item) => item.id === id);\n\n            if (!item) {\n                return;\n            }\n            document.getSelection()?.removeAllRanges();\n            navigateToLink(shareId, item.id, item.isFile);\n        },\n        [navigateToLink, shareId, browserItems]\n    );\n\n    const Cells = isDesktop ? desktopCells : mobileCells;\n    const headerItems = isDesktop ? headerItemsDesktop : headerItemsMobile;\n\n    return (\n        <>\n            <SearchItemContextMenu\n                shareId={shareId}\n                selectedLinks={selectedItems}\n                anchorRef={contextMenuAnchorRef}\n                close={browserItemContextMenu.close}\n                isOpen={browserItemContextMenu.isOpen}\n                open={browserItemContextMenu.open}\n                position={browserItemContextMenu.position}\n            />\n            <FileBrowser\n                // data\n                caption={c('Title').t`Search results`}\n                headerItems={headerItems}\n                items={browserItems}\n                layout={layout}\n                loading={isLoading}\n                sortParams={sortParams}\n                // components\n                Cells={Cells}\n                GridHeaderComponent={GridHeaderComponent}\n                GridViewItem={GridViewItem}\n                // handlers\n                onItemOpen={handleClick}\n                contextMenuAnchorRef={contextMenuAnchorRef}\n                onItemContextMenu={browserItemContextMenu.handleContextMenu}\n                onItemRender={handleItemRender}\n                onSort={setSorting}\n                onScroll={browserItemContextMenu.close}\n                getDragMoveControls={getDragMoveControls}\n            />\n        </>\n    );\n};\n","import { useLocation } from 'react-router';\n\nimport { c, msgid } from 'ttag';\n\nimport { PrivateMainArea } from '@proton/components';\n\n// TODO: handle with container\nimport useActiveShare from '../../../hooks/drive/useActiveShare';\nimport { useSearchView } from '../../../store';\nimport { extractSearchParameters } from '../../../store/_search/utils';\nimport { FileBrowserStateProvider } from '../../FileBrowser';\nimport DriveToolbar from '../Drive/DriveToolbar';\nimport { Search } from './Search';\n\nexport function SearchView() {\n    const { activeShareId } = useActiveShare();\n\n    const location = useLocation();\n    const query = extractSearchParameters(location);\n\n    const searchView = useSearchView(activeShareId, query);\n\n    return (\n        <FileBrowserStateProvider itemIds={searchView.items.map(({ linkId }) => linkId)}>\n            <DriveToolbar shareId={activeShareId} items={searchView.items} showOptionsForNoSelection={false} />\n            <PrivateMainArea hasToolbar className=\"flex-no-min-children flex-column flex-nowrap\">\n                <div className=\"max-w100 text-pre pt1 pb1 pl0-75 pr0-75 border-bottom section--header text-strong\">\n                    {searchView.isLoading\n                        ? c('Title').t`Searching…`\n                        : c('Title').ngettext(\n                              msgid`Found ${searchView.numberOfResults} result`,\n                              `Found ${searchView.numberOfResults} results`,\n                              searchView.numberOfResults\n                          )}\n                </div>\n                <Search shareId={activeShareId} searchView={searchView} />\n            </PrivateMainArea>\n        </FileBrowserStateProvider>\n    );\n}\n","import { SearchView } from '../components/sections/Search/SearchView';\n\nexport const SearchContainer = () => {\n    return <SearchView />;\n};\n","import { c } from 'ttag';\n\nimport { EmptyViewContainer, PrimaryButton } from '@proton/components';\nimport noLinksSvg from '@proton/styles/assets/img/illustrations/file-share.svg';\n\nimport useOpenModal from '../../useOpenModal';\n\ntype Props = {\n    shareId: string;\n};\n\nconst EmptyShared = ({ shareId }: Props) => {\n    const { openFileSharing } = useOpenModal();\n\n    const onShareFile = () => {\n        if (shareId) {\n            openFileSharing(shareId);\n        }\n    };\n\n    return (\n        <EmptyViewContainer\n            imageProps={{ src: noLinksSvg, title: c('Info').t`Share files with links` }}\n            data-test-id=\"shared-links-empty-placeholder\"\n        >\n            <h3 className=\"text-bold\">{c('Info').t`Share files with links`}</h3>\n            <p>{c('Info').t`Create links and share your files with others.`}</p>\n            <div className=\"flex flex-justify-center\">\n                <PrimaryButton size=\"large\" className=\"text-bold w13e\" onClick={onShareFile}>\n                    {c('Action').t`Share file`}\n                </PrimaryButton>\n            </div>\n        </EmptyViewContainer>\n    );\n};\n\nexport default EmptyShared;\n","import { c } from 'ttag';\n\nimport { DecryptedLink, useActions } from '../../../../store';\nimport { ContextMenuButton } from '../../ContextMenu';\n\ninterface Props {\n    selectedLinks: DecryptedLink[];\n    close: () => void;\n}\n\nconst StopSharingButton = ({ selectedLinks, close }: Props) => {\n    const { stopSharingLinks } = useActions();\n\n    return (\n        <ContextMenuButton\n            name={c('Action').t`Stop sharing`}\n            icon=\"link-slash\"\n            testId=\"context-menu-stop-sharing\"\n            action={() => stopSharingLinks(new AbortController().signal, selectedLinks)}\n            close={close}\n        />\n    );\n};\n\nexport default StopSharingButton;\n","import { isPreviewAvailable } from '@proton/shared/lib/helpers/preview';\n\nimport { DecryptedLink } from '../../../store';\nimport { ContextMenuProps } from '../../FileBrowser/interface';\nimport { DetailsButton, DownloadButton, PreviewButton, RenameButton, ShareLinkButton } from '../ContextMenu';\nimport { ItemContextMenu } from '../ContextMenu/ItemContextMenu';\nimport { StopSharingButton } from './ContextMenuButtons';\n\nexport function SharedLinksItemContextMenu({\n    shareId,\n    selectedLinks,\n    anchorRef,\n    isOpen,\n    position,\n    open,\n    close,\n}: ContextMenuProps & {\n    shareId: string;\n    selectedLinks: DecryptedLink[];\n}) {\n    const selectedLink = selectedLinks[0];\n    const isOnlyOneItem = selectedLinks.length === 1;\n    const hasPreviewAvailable =\n        isOnlyOneItem &&\n        selectedLink.isFile &&\n        selectedLink.mimeType &&\n        isPreviewAvailable(selectedLink.mimeType, selectedLink.size);\n\n    return (\n        <ItemContextMenu isOpen={isOpen} open={open} close={close} position={position} anchorRef={anchorRef}>\n            {hasPreviewAvailable && <PreviewButton shareId={shareId} linkId={selectedLink.linkId} close={close} />}\n            <DownloadButton shareId={shareId} selectedLinks={selectedLinks} close={close} />\n            {isOnlyOneItem && <RenameButton shareId={shareId} link={selectedLink} close={close} />}\n            <DetailsButton selectedLinks={selectedLinks} close={close} />\n            {isOnlyOneItem && <ShareLinkButton shareId={shareId} link={selectedLink} close={close} />}\n            <StopSharingButton selectedLinks={selectedLinks} close={close} />\n        </ItemContextMenu>\n    );\n}\n","import { useCallback, useMemo, useRef } from 'react';\n\nimport { c } from 'ttag';\n\nimport { useActiveBreakpoint } from '@proton/components';\n\nimport useNavigate from '../../../hooks/drive/useNavigate';\nimport { EncryptedLink, LinkShareUrl, useSharedLinksView, useThumbnailsDownload } from '../../../store';\nimport { SortField } from '../../../store/_views/utils/useSorting';\nimport FileBrowser, { Cells, GridHeader, useItemContextMenu, useSelection } from '../../FileBrowser';\nimport { BrowserItemId, FileBrowserBaseItem, ListViewHeaderItem } from '../../FileBrowser/interface';\nimport { GridViewItem } from '../FileBrowser/GridViewItemLink';\nimport { AccessCountCell, CreatedCell, ExpirationCell, LocationCell, NameCell } from '../FileBrowser/contentCells';\nimport headerItems from '../FileBrowser/headerCells';\nimport { translateSortField } from '../SortDropdown';\nimport { getSelectedItems } from '../helpers';\nimport EmptyShared from './EmptyShared';\nimport { SharedLinksItemContextMenu } from './SharedLinksItemContextMenu';\n\nexport interface SharedLinkItem extends FileBrowserBaseItem {\n    activeRevision?: EncryptedLink['activeRevision'];\n    cachedThumbnailUrl?: string;\n    hasThumbnail: boolean;\n    isFile: boolean;\n    mimeType: string;\n    fileModifyTime: number;\n    name: string;\n    shareUrl?: LinkShareUrl;\n    signatureIssues?: any;\n    size: number;\n    trashed: number | null;\n    parentLinkId: string;\n}\n\ntype Props = {\n    shareId: string;\n    sharedLinksView: ReturnType<typeof useSharedLinksView>;\n};\n\nconst { CheckboxCell, ContextMenuCell } = Cells;\n\nconst desktopCells: React.FC<{ item: SharedLinkItem }>[] = [\n    CheckboxCell,\n    NameCell,\n    LocationCell,\n    CreatedCell,\n    AccessCountCell,\n    ExpirationCell,\n    ContextMenuCell,\n];\nconst mobileCells = [CheckboxCell, NameCell, LocationCell, ExpirationCell, ContextMenuCell];\n\nconst headerItemsDesktop: ListViewHeaderItem[] = [\n    headerItems.checkbox,\n    headerItems.name,\n    headerItems.location,\n    headerItems.creationDate,\n    headerItems.accessCount,\n    headerItems.expirationDate,\n    headerItems.placeholder,\n];\n\nconst headeItemsMobile: ListViewHeaderItem[] = [\n    headerItems.checkbox,\n    headerItems.name,\n    headerItems.location,\n    headerItems.expirationDate,\n    headerItems.placeholder,\n];\ntype SharedLinksSortFields = Extract<\n    SortField,\n    SortField.name | SortField.linkCreateTime | SortField.linkExpireTime | SortField.numAccesses\n>;\nconst SORT_FIELDS: SharedLinksSortFields[] = [\n    SortField.name,\n    SortField.linkCreateTime,\n    SortField.linkExpireTime,\n    SortField.numAccesses,\n];\n\nconst SharedLinks = ({ shareId, sharedLinksView }: Props) => {\n    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);\n\n    const { navigateToLink } = useNavigate();\n    const browserItemContextMenu = useItemContextMenu();\n    const thumbnails = useThumbnailsDownload();\n    const selectionControls = useSelection();\n    const { isDesktop } = useActiveBreakpoint();\n\n    const { layout, items, sortParams, setSorting, isLoading } = sharedLinksView;\n\n    const selectedItems = useMemo(\n        () => getSelectedItems(items, selectionControls!.selectedItemIds),\n        [items, selectionControls!.selectedItemIds]\n    );\n\n    const browserItems: SharedLinkItem[] = items.map((item) => ({ ...item, id: item.linkId }));\n\n    const handleClick = useCallback(\n        (id: BrowserItemId) => {\n            const item = browserItems.find((item) => item.id === id);\n\n            if (!item) {\n                return;\n            }\n            document.getSelection()?.removeAllRanges();\n            navigateToLink(shareId, item.id, item.isFile);\n        },\n        [navigateToLink, shareId, browserItems]\n    );\n\n    const handleItemRender = useCallback((item: SharedLinkItem) => {\n        if (item.hasThumbnail && item.activeRevision && !item.cachedThumbnailUrl) {\n            thumbnails.addToDownloadQueue(shareId, item.id, item.activeRevision.id);\n        }\n    }, []);\n\n    /* eslint-disable react/display-name */\n    const GridHeaderComponent = useMemo(\n        () =>\n            ({ scrollAreaRef }: { scrollAreaRef: React.RefObject<HTMLDivElement> }) => {\n                const activeSortingText = translateSortField(sortParams.sortField);\n                return (\n                    <GridHeader\n                        isLoading={isLoading}\n                        sortFields={SORT_FIELDS}\n                        onSort={setSorting}\n                        sortField={sortParams.sortField}\n                        sortOrder={sortParams.sortOrder}\n                        itemCount={browserItems.length}\n                        onToggleAllSelected={selectionControls!.toggleAllSelected}\n                        scrollAreaRef={scrollAreaRef}\n                        activeSortingText={activeSortingText}\n                    />\n                );\n            },\n        [sortParams.sortField, sortParams.sortOrder, isLoading]\n    );\n\n    if (!items.length && !isLoading) {\n        return <EmptyShared shareId={shareId} />;\n    }\n\n    const Cells = isDesktop ? desktopCells : mobileCells;\n    const headerItems = isDesktop ? headerItemsDesktop : headeItemsMobile;\n\n    return (\n        <>\n            <SharedLinksItemContextMenu\n                shareId={shareId}\n                selectedLinks={selectedItems}\n                anchorRef={contextMenuAnchorRef}\n                close={browserItemContextMenu.close}\n                isOpen={browserItemContextMenu.isOpen}\n                open={browserItemContextMenu.open}\n                position={browserItemContextMenu.position}\n            />\n            <FileBrowser\n                caption={c('Title').t`Shared`}\n                items={browserItems}\n                headerItems={headerItems}\n                layout={layout}\n                loading={isLoading}\n                sortParams={sortParams}\n                Cells={Cells}\n            